	text = {
		"--!strict\n",
		"--[[\n",
		"\tBigNum\n",
		"\tLocation: ReplicatedStorage > Shared > BigNum (ModuleScript)\n",
		"\n",
		"\tNon-negative big numbers for values that grow exponentially: enemy HP, tap\n",
		"\tdamage, Gold balances, upgrade costs and (later) hero DPS.\n",
		"\n",
		"\tRepresentation: value = m * 10^e, in one of two regimes chosen by size:\n",
		"\t  - small: e == 0 and 0 <= m < 2^53. m holds the exact double, so early-game\n",
		"\t    arithmetic is bit-for-bit the same as Milestone 1's plain numbers.\n",
		"\t  - large: 1 <= m < 10 and e >= 15, with value >= 2^53. e is an integer up\n",
		"\t    to 2^53 - 1, so values far beyond 10^308 are supported.\n",
		"\tEvery value has exactly one representation, so comparisons and canonical\n",
		"\tstrings are stable.\n",
		"\n",
		"\tValues are frozen; create new ones with the functions below.\n",
		"\tCanonical text (saves and network): \"%.17g\" of m, plus \"e<exponent>\" for\n",
		"\tlarge values, e.g. \"13\", \"0.5\", \"1.5e400\". Positive subnormal m (below\n",
		"\t2.2250738585072014e-308) uses Luau's shortest round-trip tostring instead,\n",
		"\te.g. \"5e-324\" (DEFECT-001B).\n",
		"]]\n",
		"\n",
		"-- Every BigNum is frozen at runtime (see make). The fields are not marked `read`, because the old\n",
		"-- type solver rejects that syntax (\"read keyword is illegal here\") and Studio may use either solver.\n",
		"export type BigNum = {\n",
		"\tm: number,\n",
		"\te: number,\n",
		"}\n",
		"\n",
		"local SMALL_LIMIT = 9007199254740992 -- 2^53: below this, doubles represent every integer exactly\n",
		"local MAX_EXPONENT = 9007199254740991 -- 2^53 - 1: largest exponent that is still an exact integer\n",
		"local SMALL_LOG_LIMIT = 16 -- below 10^16 a value may be computed with plain doubles first\n",
		"local MAX_EXACT_POWER_OF_TEN = 22 -- 10^22 is the largest power of ten a double holds exactly\n",
		"local IGNORE_GAP = 17 -- a value 17+ orders of magnitude smaller cannot change a sum or difference\n",
		"local MAX_TEXT_LENGTH = 64\n",
		"local MIN_NORMAL = 2.2250738585072014e-308 -- smallest positive normal double; positive values below it are subnormal\n",
		"local SUFFIXES = { \"\", \"K\", \"M\", \"B\", \"T\", \"Qa\", \"Qi\", \"Sx\", \"Sp\", \"Oc\", \"No\", \"Dc\" }\n",
		"\n",
		"local BigNum = {}\n",
		"\n",
		"local function make(m: number, e: number): BigNum\n",
		"\tlocal value: BigNum = { m = m, e = e }\n",
		"\t-- Freezes in place. The cast stops the new solver from narrowing value to read-only fields.\n",
		"\ttable.freeze(value :: any)\n",
		"\treturn value\n",
		"end\n",
		"\n",
		"local ZERO = make(0, 0)\n",
		"local ONE = make(1, 0)\n",
		"\n",
		"BigNum.zero = ZERO\n",
		"BigNum.one = ONE\n",
		"\n",
		"local function isFiniteNumber(value: unknown): boolean\n",
		"\treturn typeof(value) == \"number\" and value == value and value ~= math.huge and value ~= -math.huge\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tm * 10^power and m / 10^power. Powers below -300 are applied in two steps:\n",
		"\tsubnormal doubles (down to 5e-324) need 10^-324, which underflows to zero on\n",
		"\tits own. Every other power uses the single operation, so ordinary values\n",
		"\tround exactly as before.\n",
		"\n",
		"\tDEFECT-001: a host that flushes subnormal results to zero (FTZ, as Roblox Studio\n",
		"\tdid) makes the two-step product 0 even when m * 10^power is a representable\n",
		"\tsubnormal. Only then (a zero product from a positive m) the value is rebuilt from\n",
		"\tdecimal text, which tonumber rounds correctly; it still returns 0 for a genuine\n",
		"\tunderflow (below half of 5e-324). Every other result is returned unchanged.\n",
		"]]\n",
		"local function multiplyByPowerOfTen(m: number, power: number): number\n",
		"\tif power < -300 then\n",
		"\t\tlocal value = m * 10 ^ (power + 300) * 1e-300\n",
		"\t\tif value == 0 and m > 0 then\n",
		"\t\t\tvalue = tonumber(string.format(\"%.17ge%.0f\", m, power)) or 0\n",
		"\t\tend\n",
		"\t\treturn value\n",
		"\tend\n",
		"\treturn m * 10 ^ power\n",
		"end\n",
		"\n",
		"local function divideByPowerOfTen(m: number, power: number): number\n",
		"\tif power < -300 then\n",
		"\t\treturn m * 1e300 / 10 ^ (power + 300)\n",
		"\tend\n",
		"\treturn m / 10 ^ power\n",
		"end\n",
		"\n",
		"-- Brings any finite, non-negative m * 10^e (e an integer) into canonical form; nil if e would exceed 2^53 - 1.\n",
		"local function tryNormalize(m: number, e: number): BigNum?\n",
		"\tif m <= 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tif m < 1 or m >= 10 then\n",
		"\t\tlocal shift = math.floor(math.log10(m))\n",
		"\t\tm = divideByPowerOfTen(m, shift)\n",
		"\t\te += shift\n",
		"\t\tif m >= 10 then\n",
		"\t\t\tm /= 10\n",
		"\t\t\te += 1\n",
		"\t\telseif m < 1 then\n",
		"\t\t\tm *= 10\n",
		"\t\t\te -= 1\n",
		"\t\tend\n",
		"\tend\n",
		"\tif e > MAX_EXPONENT then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif e < SMALL_LOG_LIMIT then\n",
		"\t\tlocal value = multiplyByPowerOfTen(m, e)\n",
		"\t\tif value < SMALL_LIMIT then\n",
		"\t\t\treturn make(value, 0)\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn make(m, e)\n",
		"end\n",
		"\n",
		"-- tryNormalize for arithmetic results, where an exponent beyond 2^53 - 1 is an overflow error.\n",
		"local function normalize(m: number, e: number): BigNum\n",
		"\tlocal value = tryNormalize(m, e)\n",
		"\tif value == nil then\n",
		"\t\terror(\"BigNum overflow: exponent exceeds 2^53 - 1\", 3)\n",
		"\tend\n",
		"\treturn value\n",
		"end\n",
		"\n",
		"-- Mantissa in [1, 10) and integer exponent for any non-zero value (small values included).\n",
		"local function toScientific(value: BigNum): (number, number)\n",
		"\tif value.e ~= 0 or value.m == 0 then\n",
		"\t\treturn value.m, value.e\n",
		"\tend\n",
		"\tlocal mantissa = value.m\n",
		"\tlocal exponent = math.floor(math.log10(mantissa))\n",
		"\tmantissa = divideByPowerOfTen(mantissa, exponent)\n",
		"\tif mantissa >= 10 then\n",
		"\t\tmantissa /= 10\n",
		"\t\texponent += 1\n",
		"\telseif mantissa < 1 then\n",
		"\t\tmantissa *= 10\n",
		"\t\texponent -= 1\n",
		"\tend\n",
		"\treturn mantissa, exponent\n",
		"end\n",
		"\n",
		"local function trimZeros(text: string): string\n",
		"\treturn (string.gsub(text, \"%.?0+$\", \"\"))\n",
		"end\n",
		"\n",
		"---------------------------------------------------------------------------\n",
		"-- Construction and validation\n",
		"---------------------------------------------------------------------------\n",
		"\n",
		"-- Converts a plain number. Errors on NaN, infinity or negative input (programmer error).\n",
		"function BigNum.fromNumber(value: number): BigNum\n",
		"\tif not isFiniteNumber(value) or value < 0 then\n",
		"\t\terror(`BigNum.fromNumber expects a finite, non-negative number (got {value})`, 2)\n",
		"\tend\n",
		"\tif value == 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tif value < SMALL_LIMIT then\n",
		"\t\treturn make(value, 0)\n",
		"\tend\n",
		"\treturn normalize(value, 0)\n",
		"end\n",
		"\n",
		"-- 10^exponent for any finite exponent, without ever computing an overflowing double.\n",
		"function BigNum.fromLog10(exponent: number): BigNum\n",
		"\tif not isFiniteNumber(exponent) then\n",
		"\t\terror(\"BigNum.fromLog10 expects a finite number\", 2)\n",
		"\tend\n",
		"\tif exponent < SMALL_LOG_LIMIT then\n",
		"\t\tlocal value = 10 ^ exponent\n",
		"\t\tif value < SMALL_LIMIT then\n",
		"\t\t\treturn if value == 0 then ZERO else make(value, 0)\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal whole = math.floor(exponent)\n",
		"\treturn normalize(10 ^ (exponent - whole), whole)\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tbase * growth^steps, the shape of every scaling formula in Emberbound.\n",
		"\tWhile the result stays below 10^16 it is computed with the same double\n",
		"\texpression Milestone 1 used, so early values match exactly. Beyond that it\n",
		"\tis computed in log space and never overflows.\n",
		"]]\n",
		"function BigNum.scaledPower(base: number, growth: number, steps: number): BigNum\n",
		"\tif not isFiniteNumber(base) or base < 0 then\n",
		"\t\terror(\"BigNum.scaledPower expects a finite, non-negative base\", 2)\n",
		"\tend\n",
		"\tif not isFiniteNumber(growth) or growth <= 0 then\n",
		"\t\terror(\"BigNum.scaledPower expects a finite, positive growth\", 2)\n",
		"\tend\n",
		"\tif not isFiniteNumber(steps) or steps < 0 then\n",
		"\t\terror(\"BigNum.scaledPower expects finite, non-negative steps\", 2)\n",
		"\tend\n",
		"\tif base == 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tlocal magnitude = math.log10(base) + steps * math.log10(growth)\n",
		"\tif magnitude < SMALL_LOG_LIMIT then\n",
		"\t\tlocal value = base * growth ^ steps\n",
		"\t\tif value < SMALL_LIMIT then\n",
		"\t\t\treturn if value == 0 then ZERO else make(value, 0)\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn BigNum.fromLog10(magnitude)\n",
		"end\n",
		"\n",
		"-- True only for a table that satisfies every BigNum invariant. Use on any value from outside the module.\n",
		"function BigNum.isValid(value: unknown): boolean\n",
		"\tif typeof(value) ~= \"table\" then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal candidate: any = value\n",
		"\tlocal m, e = candidate.m, candidate.e\n",
		"\tif not isFiniteNumber(m) or not isFiniteNumber(e) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tif e == 0 then\n",
		"\t\treturn m >= 0 and m < SMALL_LIMIT\n",
		"\tend\n",
		"\tif e % 1 ~= 0 or e < 15 or e > MAX_EXPONENT or m < 1 or m >= 10 then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\treturn e > 15 or m * 1e15 >= SMALL_LIMIT\n",
		"end\n",
		"\n",
		"---------------------------------------------------------------------------\n",
		"-- Comparison\n",
		"---------------------------------------------------------------------------\n",
		"\n",
		"-- Returns -1, 0 or 1.\n",
		"function BigNum.compare(a: BigNum, b: BigNum): number\n",
		"\tif a.e ~= b.e then\n",
		"\t\treturn if a.e < b.e then -1 else 1\n",
		"\tend\n",
		"\tif a.m < b.m then\n",
		"\t\treturn -1\n",
		"\telseif a.m > b.m then\n",
		"\t\treturn 1\n",
		"\tend\n",
		"\treturn 0\n",
		"end\n",
		"\n",
		"function BigNum.eq(a: BigNum, b: BigNum): boolean\n",
		"\treturn a.e == b.e and a.m == b.m\n",
		"end\n",
		"\n",
		"function BigNum.lt(a: BigNum, b: BigNum): boolean\n",
		"\treturn BigNum.compare(a, b) < 0\n",
		"end\n",
		"\n",
		"function BigNum.lte(a: BigNum, b: BigNum): boolean\n",
		"\treturn BigNum.compare(a, b) <= 0\n",
		"end\n",
		"\n",
		"function BigNum.gt(a: BigNum, b: BigNum): boolean\n",
		"\treturn BigNum.compare(a, b) > 0\n",
		"end\n",
		"\n",
		"function BigNum.gte(a: BigNum, b: BigNum): boolean\n",
		"\treturn BigNum.compare(a, b) >= 0\n",
		"end\n",
		"\n",
		"function BigNum.isZero(value: BigNum): boolean\n",
		"\treturn value.m == 0\n",
		"end\n",
		"\n",
		"function BigNum.max(a: BigNum, b: BigNum): BigNum\n",
		"\treturn if BigNum.compare(a, b) >= 0 then a else b\n",
		"end\n",
		"\n",
		"function BigNum.min(a: BigNum, b: BigNum): BigNum\n",
		"\treturn if BigNum.compare(a, b) <= 0 then a else b\n",
		"end\n",
		"\n",
		"---------------------------------------------------------------------------\n",
		"-- Arithmetic\n",
		"---------------------------------------------------------------------------\n",
		"\n",
		"function BigNum.add(a: BigNum, b: BigNum): BigNum\n",
		"\tif a.e == 0 and b.e == 0 then\n",
		"\t\tlocal sum = a.m + b.m -- exact while both operands and the result stay below 2^53\n",
		"\t\tif sum < SMALL_LIMIT then\n",
		"\t\t\treturn make(sum, 0)\n",
		"\t\tend\n",
		"\t\treturn normalize(sum, 0)\n",
		"\tend\n",
		"\tif a.m == 0 then\n",
		"\t\treturn b\n",
		"\tend\n",
		"\tif b.m == 0 then\n",
		"\t\treturn a\n",
		"\tend\n",
		"\tlocal larger, smaller = a, b\n",
		"\tif BigNum.compare(a, b) < 0 then\n",
		"\t\tlarger, smaller = b, a\n",
		"\tend\n",
		"\tlocal largeM, largeE = toScientific(larger)\n",
		"\tlocal smallM, smallE = toScientific(smaller)\n",
		"\tlocal gap = largeE - smallE\n",
		"\tif gap > IGNORE_GAP then\n",
		"\t\treturn larger\n",
		"\tend\n",
		"\treturn normalize(largeM + smallM / 10 ^ gap, largeE)\n",
		"end\n",
		"\n",
		"-- Saturating subtraction: returns zero when b >= a. Use trySub when going below zero must be refused.\n",
		"function BigNum.sub(a: BigNum, b: BigNum): BigNum\n",
		"\tif BigNum.compare(a, b) <= 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tif a.e == 0 then\n",
		"\t\treturn make(a.m - b.m, 0) -- both small: exact\n",
		"\tend\n",
		"\tif b.m == 0 then\n",
		"\t\treturn a\n",
		"\tend\n",
		"\t-- Scientific form loses the low digits here (2^53 - (2^53 - 1) came out as 1.776). Below 10^23\n",
		"\t-- (10^22 is the largest exact power of ten) both operands convert to doubles in one rounding,\n",
		"\t-- exactly below 10^16, so one correctly rounded subtraction is used instead. Doubles at or\n",
		"\t-- above 2^53 are whole numbers, so a result below 2^53 is exact.\n",
		"\tif a.e <= MAX_EXACT_POWER_OF_TEN then\n",
		"\t\tlocal difference = BigNum.toNumber(a) - BigNum.toNumber(b)\n",
		"\t\treturn if difference > 0 then BigNum.fromNumber(difference) else ZERO\n",
		"\tend\n",
		"\tlocal smallM, smallE = toScientific(b)\n",
		"\tlocal gap = a.e - smallE\n",
		"\tif gap > IGNORE_GAP then\n",
		"\t\treturn a\n",
		"\tend\n",
		"\treturn normalize(a.m - smallM / 10 ^ gap, a.e)\n",
		"end\n",
		"\n",
		"-- a - b, or nil when b > a. The building block for \"spend only if affordable\".\n",
		"function BigNum.trySub(a: BigNum, b: BigNum): BigNum?\n",
		"\tif BigNum.compare(a, b) < 0 then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn BigNum.sub(a, b)\n",
		"end\n",
		"\n",
		"function BigNum.mul(a: BigNum, b: BigNum): BigNum\n",
		"\tif a.m == 0 or b.m == 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tif a.e == 0 and b.e == 0 then\n",
		"\t\tlocal product = a.m * b.m\n",
		"\t\tif product < SMALL_LIMIT then\n",
		"\t\t\treturn make(product, 0)\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal aM, aE = toScientific(a)\n",
		"\tlocal bM, bE = toScientific(b)\n",
		"\treturn normalize(aM * bM, aE + bE)\n",
		"end\n",
		"\n",
		"-- Multiplies by a plain finite, non-negative number (for example an interval in seconds).\n",
		"function BigNum.mulNumber(a: BigNum, factor: number): BigNum\n",
		"\treturn BigNum.mul(a, BigNum.fromNumber(factor))\n",
		"end\n",
		"\n",
		"function BigNum.div(a: BigNum, b: BigNum): BigNum\n",
		"\tif b.m == 0 then\n",
		"\t\terror(\"BigNum.div: division by zero\", 2)\n",
		"\tend\n",
		"\tif a.m == 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\tif a.e == 0 and b.e == 0 then\n",
		"\t\tlocal quotient = a.m / b.m\n",
		"\t\tif quotient < SMALL_LIMIT then\n",
		"\t\t\treturn make(quotient, 0)\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal aM, aE = toScientific(a)\n",
		"\tlocal bM, bE = toScientific(b)\n",
		"\treturn normalize(aM / bM, aE - bE)\n",
		"end\n",
		"\n",
		"-- a / b as a plain number (for example a health bar fill). Can return math.huge for enormous ratios.\n",
		"function BigNum.ratio(a: BigNum, b: BigNum): number\n",
		"\tif b.m == 0 then\n",
		"\t\terror(\"BigNum.ratio: division by zero\", 2)\n",
		"\tend\n",
		"\tif a.m == 0 then\n",
		"\t\treturn 0\n",
		"\tend\n",
		"\tif a.e == 0 and b.e == 0 then\n",
		"\t\treturn a.m / b.m\n",
		"\tend\n",
		"\tlocal aM, aE = toScientific(a)\n",
		"\tlocal bM, bE = toScientific(b)\n",
		"\tlocal gap = aE - bE\n",
		"\tif gap > 308 then\n",
		"\t\treturn math.huge\n",
		"\tend\n",
		"\tif gap < -330 then\n",
		"\t\treturn 0\n",
		"\tend\n",
		"\treturn (aM / bM) * 10 ^ gap\n",
		"end\n",
		"\n",
		"-- Rounds down. Large values (>= 2^53) are already whole numbers at this precision.\n",
		"function BigNum.floor(value: BigNum): BigNum\n",
		"\tif value.e ~= 0 then\n",
		"\t\treturn value\n",
		"\tend\n",
		"\tlocal floored = math.floor(value.m)\n",
		"\tif floored == value.m then\n",
		"\t\treturn value\n",
		"\tend\n",
		"\treturn make(floored, 0)\n",
		"end\n",
		"\n",
		"-- log10 of the value; -math.huge for zero.\n",
		"function BigNum.log10(value: BigNum): number\n",
		"\tif value.m == 0 then\n",
		"\t\treturn -math.huge\n",
		"\tend\n",
		"\tif value.e == 0 then\n",
		"\t\treturn math.log10(value.m)\n",
		"\tend\n",
		"\treturn math.log10(value.m) + value.e\n",
		"end\n",
		"\n",
		"-- The value as a plain number. Returns math.huge beyond about 1.8e308; meant for display math only.\n",
		"function BigNum.toNumber(value: BigNum): number\n",
		"\tif value.e == 0 then\n",
		"\t\treturn value.m\n",
		"\tend\n",
		"\tif value.e > 308 then\n",
		"\t\treturn math.huge\n",
		"\tend\n",
		"\treturn value.m * 10 ^ value.e\n",
		"end\n",
		"\n",
		"---------------------------------------------------------------------------\n",
		"-- Text\n",
		"---------------------------------------------------------------------------\n",
		"\n",
		"--[[\n",
		"\tCanonical text used for saving and networking. parse(toString(x)) always equals x.\n",
		"\n",
		"\tDEFECT-001B: Roblox Studio's string.format printed \"0\" for the subnormal 5e-324 with\n",
		"\t\"%.17g\", so its canonical text read back as zero. Positive subnormals therefore use Luau's\n",
		"\ttostring, the shortest decimal text that reads back as exactly the same double (\"5e-324\"),\n",
		"\twhich Studio printed correctly. Zero, normal values and large values keep the \"%.17g\" text.\n",
		"]]\n",
		"function BigNum.toString(value: BigNum): string\n",
		"\tif value.e == 0 then\n",
		"\t\tlocal m = value.m\n",
		"\t\tif m > 0 and m < MIN_NORMAL then\n",
		"\t\t\treturn tostring(m)\n",
		"\t\tend\n",
		"\t\treturn string.format(\"%.17g\", m)\n",
		"\tend\n",
		"\treturn string.format(\"%.17ge%.0f\", value.m, value.e)\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tReads canonical text (and other plain decimal or \"<digits>e<exponent>\"\n",
		"\tforms). Returns nil for anything malformed, negative, non-finite, longer\n",
		"\tthan 64 characters, or with an exponent beyond 2^53 - 1. Never errors.\n",
		"\tR2-1: the range check uses the decimal digits as written, so an\n",
		"\tout-of-range decimal is rejected even if it would round into range.\n",
		"\tA value can still read as nil when rounding carries it past the top of\n",
		"\tthe range (within one rounding step of 10^(2^53)).\n",
		"]]\n",
		"function BigNum.parse(text: unknown): BigNum?\n",
		"\tif typeof(text) ~= \"string\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif #text == 0 or #text > MAX_TEXT_LENGTH then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal mantissaText, exponentText = string.match(text, \"^(%d+%.?%d*)[eE]([%+%-]?%d+)$\")\n",
		"\tif mantissaText == nil then\n",
		"\t\tmantissaText = string.match(text, \"^(%d+%.?%d*)$\")\n",
		"\t\tif mantissaText == nil then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal mantissa = tonumber(mantissaText)\n",
		"\tif mantissa == nil or not isFiniteNumber(mantissa) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal exponent = 0\n",
		"\tif exponentText ~= nil then\n",
		"\t\tlocal parsedExponent = tonumber(exponentText)\n",
		"\t\tif parsedExponent == nil or parsedExponent % 1 ~= 0 or math.abs(parsedExponent) > MAX_EXPONENT then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\texponent = parsedExponent\n",
		"\tend\n",
		"\tif mantissa == 0 then\n",
		"\t\treturn ZERO\n",
		"\tend\n",
		"\t-- R2-1: the written value is at least 10^(leading + exponent), where leading is the decimal\n",
		"\t-- exponent of its first nonzero digit. Rejecting before any rounding means the text\n",
		"\t-- \"1\" + 23 zeros + \"e9007199254740969\" (= 10^(2^53)) cannot round down into range.\n",
		"\tlocal integerDigits = string.match(mantissaText :: string, \"^0*(%d*)\")\n",
		"\tlocal leading = #(integerDigits :: string) - 1\n",
		"\tif leading > 0 and exponent > MAX_EXPONENT - leading then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\t-- Anything that fits a double below 2^53 is read in one step, so \"1.1e1\" is exactly 11.\n",
		"\tlocal whole = tonumber(text)\n",
		"\tif whole ~= nil and isFiniteNumber(whole) and whole < SMALL_LIMIT then\n",
		"\t\treturn if whole == 0 then ZERO else make(whole, 0)\n",
		"\tend\n",
		"\t-- The normalized exponent can still exceed 2^53 - 1 (\"10e9007199254740991\"): nil, not an error.\n",
		"\treturn tryNormalize(mantissa, exponent)\n",
		"end\n",
		"\n",
		"-- Player-facing text: \"999\", \"1.23K\", \"5.6M\" ... \"1.2Dc\", then \"1.23e456\".\n",
		"function BigNum.format(value: BigNum): string\n",
		"\tif value.e == 0 and value.m < 1000 then\n",
		"\t\treturn tostring(math.floor(value.m))\n",
		"\tend\n",
		"\tlocal mantissa, exponent = toScientific(value)\n",
		"\tlocal tier = math.floor(exponent / 3)\n",
		"\tif tier < #SUFFIXES then\n",
		"\t\tlocal scaled = mantissa * 10 ^ (exponent - tier * 3)\n",
		"\t\tlocal text = string.format(\"%.2f\", scaled)\n",
		"\t\tif (tonumber(text) :: number) >= 1000 then -- rounding reached the next tier (999.995 -> 1000.00)\n",
		"\t\t\ttier += 1\n",
		"\t\t\ttext = string.format(\"%.2f\", scaled / 1000)\n",
		"\t\tend\n",
		"\t\tif tier < #SUFFIXES then\n",
		"\t\t\treturn trimZeros(text) .. SUFFIXES[tier + 1]\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal text = string.format(\"%.2f\", mantissa)\n",
		"\tif text == \"10.00\" then\n",
		"\t\ttext = \"1.00\"\n",
		"\t\texponent += 1\n",
		"\tend\n",
		"\treturn trimZeros(text) .. \"e\" .. string.format(\"%.0f\", exponent)\n",
		"end\n",
		"\n",
		"return table.freeze(BigNum)\n",
	},
}
FILES[2] = {
	path = "ReplicatedStorage/Shared/GameConfig",
	className = "ModuleScript",
	bytes = 5838,
	lines = 153,
	adler32 = 2137704413,
	sha256 = "ff9d9f69635f413d5b91cd52a19b6621ea59ae4bc3efadc0b2e67f917b38ab02",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tGameConfig\n",
		"\tLocation: ReplicatedStorage > Shared > GameConfig (ModuleScript)\n",
		"\n",
		"\tSingle source of truth for combat balancing values, scaling formulas and the\n",
		"\tclient/server network contract. The server uses these values for all\n",
		"\tauthoritative math; the client only uses them for display and for\n",
		"\tthrottling its own requests.\n",
		"\n",
		"\tMilestone 2: the scaling formulas return BigNum values, and every large\n",
		"\tvalue crosses the network as a canonical BigNum string.\n",
		"]]\n",
		"\n",
		"local BigNum = require(script.Parent:WaitForChild(\"BigNum\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"-- Where a hit came from. Future systems (hero DPS) add their own source here.\n",
		"export type DamageSource = \"Tap\"\n",
		"\n",
		"-- Everything the client needs to render the current combat state.\n",
		"-- Text fields hold canonical BigNum strings (BigNum.toString / BigNum.parse).\n",
		"export type CombatSnapshot = {\n",
		"\tstage: number,\n",
		"\ttapDamage: string,\n",
		"\tenemyId: number, -- increments every time a new enemy spawns\n",
		"\tenemyName: string,\n",
		"\tenemyHp: string,\n",
		"\tenemyMaxHp: string,\n",
		"}\n",
		"\n",
		"-- \"Stats\" means a combat stat (tap damage) changed without a hit.\n",
		"export type CombatUpdateKind = \"Sync\" | \"Hit\" | \"Defeated\" | \"Stats\"\n",
		"\n",
		"-- Payload of the CombatUpdate RemoteEvent (server -> one client).\n",
		"export type CombatUpdate = {\n",
		"\tkind: CombatUpdateKind,\n",
		"\tsnapshot: CombatSnapshot, -- always the full, authoritative state after the change\n",
		"\tdamage: string?, -- damage applied by this hit (\"Hit\" and \"Defeated\")\n",
		"\tsource: DamageSource?,\n",
		"\tgoldAwarded: string?, -- only on \"Defeated\"\n",
		"}\n",
		"\n",
		"-- Payload of the CurrencyUpdate RemoteEvent: every balance the player has, as BigNum strings.\n",
		"export type CurrencyUpdate = {\n",
		"\tbalances: { [string]: string },\n",
		"}\n",
		"\n",
		"-- One upgrade as the client sees it. Values are BigNum strings; next fields are nil at max level.\n",
		"export type UpgradeView = {\n",
		"\tupgradeId: string,\n",
		"\tlevel: number,\n",
		"\tmaxLevel: number,\n",
		"\tcurrencyId: string,\n",
		"\tcurrentValue: string,\n",
		"\tnextValue: string?,\n",
		"\tnextCost: string?,\n",
		"}\n",
		"\n",
		"-- EffectFailed (M2.1): the upgrade's new stat could not be applied, so nothing was charged. The client shows \"Purchase failed\".\n",
		"export type PurchaseReason = \"Ok\" | \"InsufficientFunds\" | \"MaxLevel\" | \"EffectFailed\"\n",
		"\n",
		"export type PurchaseResult = {\n",
		"\trequestId: number,\n",
		"\tupgradeId: string,\n",
		"\tsuccess: boolean,\n",
		"\treason: PurchaseReason,\n",
		"}\n",
		"\n",
		"export type UpgradeUpdateKind = \"Sync\" | \"PurchaseResult\"\n",
		"\n",
		"-- Payload of the UpgradeUpdate RemoteEvent (server -> one client).\n",
		"export type UpgradeUpdate = {\n",
		"\tkind: UpgradeUpdateKind,\n",
		"\tupgrades: { [string]: UpgradeView },\n",
		"\tresult: PurchaseResult?,\n",
		"}\n",
		"\n",
		"local GameConfig = {}\n",
		"\n",
		"GameConfig.Combat = table.freeze({\n",
		"\tStartingStage = 1,\n",
		"\tStartingGold = 0,\n",
		"\tStartingTapDamage = 1,\n",
		"\n",
		"\tStartingEnemyHp = 10,\n",
		"\tEnemyHpMultiplier = 1.18, -- per stage\n",
		"\n",
		"\tStartingGoldReward = 5,\n",
		"\tGoldRewardMultiplier = 1.12, -- per stage\n",
		"\n",
		"\tTapCooldown = 0.07, -- seconds between accepted taps (enforced by the server)\n",
		"\n",
		"\tDefaultEnemyName = \"Forest Slime\",\n",
		"})\n",
		"\n",
		"GameConfig.Network = table.freeze({\n",
		"\tRemotesFolderName = \"Remotes\",\n",
		"\tRequestAttack = \"RequestAttack\", -- client -> server, no arguments\n",
		"\tClientReady = \"ClientReady\", -- client -> server, no arguments\n",
		"\tCombatUpdate = \"CombatUpdate\", -- server -> client, CombatUpdate payload\n",
		"\tRequestUpgrade = \"RequestUpgrade\", -- client -> server, (upgradeId: string, requestId: number)\n",
		"\tUpgradeUpdate = \"UpgradeUpdate\", -- server -> client, UpgradeUpdate payload\n",
		"\tCurrencyUpdate = \"CurrencyUpdate\", -- server -> client, CurrencyUpdate payload\n",
		"\tClientReadyCooldown = 1, -- seconds; limits how often a client can request a full sync\n",
		"\tUpgradeRequestBurst = 10, -- upgrade requests a player may send back to back\n",
		"\tUpgradeRequestsPerSecond = 8, -- sustained upgrade request rate per player\n",
		"})\n",
		"\n",
		"GameConfig.Debug = table.freeze({\n",
		"\tLogPlayerLifecycle = true, -- prints when combat state is created/removed (useful while prototyping)\n",
		"\tLogEconomy = false, -- prints every Gold grant and spend\n",
		"})\n",
		"\n",
		"-- EnemyMaxHP(stage) = floor(10 * 1.18^(stage - 1)); never overflows, and matches Milestone 1 below 2^53.\n",
		"function GameConfig.GetEnemyMaxHp(stage: number): BigNum\n",
		"\tlocal combat = GameConfig.Combat\n",
		"\tlocal hp = BigNum.scaledPower(combat.StartingEnemyHp, combat.EnemyHpMultiplier, math.max(stage - 1, 0))\n",
		"\treturn BigNum.max(BigNum.floor(hp), BigNum.one)\n",
		"end\n",
		"\n",
		"-- GoldReward(stage) = floor(5 * 1.12^(stage - 1)); never overflows, and matches Milestone 1 below 2^53.\n",
		"function GameConfig.GetGoldReward(stage: number): BigNum\n",
		"\tlocal combat = GameConfig.Combat\n",
		"\treturn BigNum.floor(BigNum.scaledPower(combat.StartingGoldReward, combat.GoldRewardMultiplier, math.max(stage - 1, 0)))\n",
		"end\n",
		"\n",
		"-- Only one enemy type exists so far. Later milestones can vary this by stage.\n",
		"function GameConfig.GetEnemyName(_stage: number): string\n",
		"\treturn GameConfig.Combat.DefaultEnemyName\n",
		"end\n",
		"\n",
		"-- Fail fast on obviously broken balancing edits instead of producing silent bugs.\n",
		"local function validate()\n",
		"\tlocal combat = GameConfig.Combat\n",
		"\tassert(combat.StartingStage >= 1 and combat.StartingStage % 1 == 0, \"GameConfig: StartingStage must be a whole number >= 1\")\n",
		"\tassert(combat.StartingGold >= 0, \"GameConfig: StartingGold must be >= 0\")\n",
		"\tassert(combat.StartingTapDamage > 0, \"GameConfig: StartingTapDamage must be > 0\")\n",
		"\tassert(combat.StartingEnemyHp >= 1, \"GameConfig: StartingEnemyHp must be >= 1\")\n",
		"\tassert(combat.EnemyHpMultiplier > 0, \"GameConfig: EnemyHpMultiplier must be > 0\")\n",
		"\tassert(combat.StartingGoldReward >= 0, \"GameConfig: StartingGoldReward must be >= 0\")\n",
		"\tassert(combat.GoldRewardMultiplier > 0, \"GameConfig: GoldRewardMultiplier must be > 0\")\n",
		"\tassert(combat.TapCooldown >= 0, \"GameConfig: TapCooldown must be >= 0\")\n",
		"\n",
		"\tlocal network = GameConfig.Network\n",
		"\tassert(network.UpgradeRequestBurst >= 1, \"GameConfig: UpgradeRequestBurst must be >= 1\")\n",
		"\tassert(network.UpgradeRequestsPerSecond > 0, \"GameConfig: UpgradeRequestsPerSecond must be > 0\")\n",
		"end\n",
		"\n",
		"validate()\n",
		"\n",
		"return table.freeze(GameConfig)\n",
	},
}
FILES[3] = {
	path = "ReplicatedStorage/Shared/ProgressionConfig",
	className = "ModuleScript",
	bytes = 6935,
	lines = 167,
	adler32 = 359691214,
	sha256 = "a77402b854f9b7fad40a37d5a17ff9863b5622f0c5e2e2d66f9fb57f4890f163",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tProgressionConfig\n",
		"\tLocation: ReplicatedStorage > Shared > ProgressionConfig (ModuleScript)\n",
		"\n",
		"\tCurrencies and upgrade curves. Every price and upgrade value comes from\n",
		"\there; services never hardcode them. The numbers are temporary balancing\n",
		"\tvalues and can be changed without touching service code.\n",
		"\n",
		"\tGacha compatibility: Gold is one currency id among others. Future summon\n",
		"\tcurrencies (earned tickets, premium currency) are added to the currency\n",
		"\tlist as separate ids. Nothing in the economy converts one currency into\n",
		"\tanother.\n",
		"]]\n",
		"\n",
		"local BigNum = require(script.Parent:WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(script.Parent:WaitForChild(\"GameConfig\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"export type CurrencyDefinition = {\n",
		"\tid: string,\n",
		"\tdisplayName: string,\n",
		"\tstartingBalance: number,\n",
		"\tkind: \"BigNum\" | \"Whole\",\n",
		"\tmaxBalance: number?,\n",
		"}\n",
		"\n",
		"export type UpgradeDefinition = {\n",
		"\tid: string,\n",
		"\tdisplayName: string,\n",
		"\tcurrencyId: string,\n",
		"\tstartingLevel: number,\n",
		"\tmaxLevel: number,\n",
		"\tbaseValue: number, -- value at level 1 before milestone bonuses\n",
		"\tmilestoneInterval: number, -- a milestone is reached every this many levels\n",
		"\tmilestoneMultiplier: number, -- the value is multiplied by this at each milestone\n",
		"\tbaseCost: number, -- price of the first purchase (startingLevel -> startingLevel + 1)\n",
		"\tcostGrowth: number, -- each further level costs this much more (1.07 = +7%)\n",
		"}\n",
		"\n",
		"local ProgressionConfig = {}\n",
		"\n",
		"ProgressionConfig.GoldCurrencyId = \"Gold\"\n",
		"ProgressionConfig.GemCurrencyId = \"Gems\"\n",
		"ProgressionConfig.CrownCurrencyId = \"Crowns\"\n",
		"\n",
		"local gold: CurrencyDefinition = {\n",
		"\tid = ProgressionConfig.GoldCurrencyId,\n",
		"\tdisplayName = \"Gold\",\n",
		"\tstartingBalance = GameConfig.Combat.StartingGold,\n",
		"\tkind = \"BigNum\",\n",
		"}\n",
		"\n",
		"ProgressionConfig.Currencies = table.freeze({ table.freeze(gold) }) :: { CurrencyDefinition }\n",
		"\n",
		"-- Saved wallet definitions. The active currency list above controls gameplay and sync.\n",
		"-- Gems and Crowns become active in M6 and M8 respectively.\n",
		"ProgressionConfig.CurrencyDefinitions = table.freeze({\n",
		"\tgold,\n",
		"\ttable.freeze({ id = \"Gems\", displayName = \"Gems\", startingBalance = 0, kind = \"Whole\", maxBalance = 9007199254740991 }),\n",
		"\ttable.freeze({ id = \"Crowns\", displayName = \"Crowns\", startingBalance = 0, kind = \"Whole\", maxBalance = 9007199254740991 }),\n",
		"}) :: { CurrencyDefinition }\n",
		"\n",
		"local tapDamage: UpgradeDefinition = {\n",
		"\tid = \"TapDamage\",\n",
		"\tdisplayName = \"Tap Damage\",\n",
		"\tcurrencyId = ProgressionConfig.GoldCurrencyId,\n",
		"\tstartingLevel = 1,\n",
		"\tmaxLevel = 100000,\n",
		"\tbaseValue = GameConfig.Combat.StartingTapDamage, -- level 1 deals Milestone 1's starting damage\n",
		"\tmilestoneInterval = 25,\n",
		"\tmilestoneMultiplier = 3,\n",
		"\tbaseCost = 5,\n",
		"\tcostGrowth = 1.07,\n",
		"}\n",
		"\n",
		"ProgressionConfig.TapDamageUpgrade = table.freeze(tapDamage) :: UpgradeDefinition\n",
		"ProgressionConfig.Upgrades = table.freeze({ ProgressionConfig.TapDamageUpgrade }) :: { UpgradeDefinition }\n",
		"\n",
		"local function checkLevel(definition: UpgradeDefinition, level: number)\n",
		"\tif typeof(level) ~= \"number\" or level % 1 ~= 0 or level < definition.startingLevel or level > definition.maxLevel then\n",
		"\t\terror(`ProgressionConfig: invalid level {level} for {definition.id}`, 3)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function ProgressionConfig.GetCurrency(currencyId: string): CurrencyDefinition?\n",
		"\tfor _, currency in ProgressionConfig.CurrencyDefinitions do\n",
		"\t\tif currency.id == currencyId then\n",
		"\t\t\treturn currency\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn nil\n",
		"end\n",
		"\n",
		"-- Balances and amounts share the same kind/range checks; callers decide whether zero is allowed.\n",
		"function ProgressionConfig.IsCurrencyValue(currencyId: string, value: BigNum): boolean\n",
		"\tif not BigNum.isValid(value) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal definition = ProgressionConfig.GetCurrency(currencyId)\n",
		"\tif definition == nil then\n",
		"\t\treturn true -- Wallet also supports caller-defined currencies, as it did in M2.\n",
		"\tend\n",
		"\tif definition.kind == \"Whole\" and not BigNum.eq(BigNum.floor(value), value) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\treturn definition.maxBalance == nil or BigNum.lte(value, BigNum.fromNumber(definition.maxBalance))\n",
		"end\n",
		"\n",
		"function ProgressionConfig.GetUpgrade(upgradeId: string): UpgradeDefinition?\n",
		"\tfor _, upgrade in ProgressionConfig.Upgrades do\n",
		"\t\tif upgrade.id == upgradeId then\n",
		"\t\t\treturn upgrade\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn nil\n",
		"end\n",
		"\n",
		"-- Value(level) = floor(baseValue * level * milestoneMultiplier^floor(level / milestoneInterval))\n",
		"function ProgressionConfig.GetUpgradeValue(definition: UpgradeDefinition, level: number): BigNum\n",
		"\tcheckLevel(definition, level)\n",
		"\tlocal milestones = math.floor(level / definition.milestoneInterval)\n",
		"\treturn BigNum.floor(BigNum.scaledPower(definition.baseValue * level, definition.milestoneMultiplier, milestones))\n",
		"end\n",
		"\n",
		"-- Cost(level) = floor(baseCost * costGrowth^(level - startingLevel)): the price of going from level to level + 1.\n",
		"function ProgressionConfig.GetUpgradeCost(definition: UpgradeDefinition, level: number): BigNum\n",
		"\tcheckLevel(definition, level)\n",
		"\treturn BigNum.floor(BigNum.scaledPower(definition.baseCost, definition.costGrowth, level - definition.startingLevel))\n",
		"end\n",
		"\n",
		"-- Fail fast on broken balancing edits.\n",
		"local function validate()\n",
		"\tlocal seenCurrencies: { [string]: boolean } = {}\n",
		"\tfor _, currency in ProgressionConfig.Currencies do\n",
		"\t\tassert(not seenCurrencies[currency.id], `ProgressionConfig: duplicate currency id {currency.id}`)\n",
		"\t\tassert(currency.startingBalance >= 0, `ProgressionConfig: {currency.id} starting balance must be >= 0`)\n",
		"\t\tseenCurrencies[currency.id] = true\n",
		"\tend\n",
		"\n",
		"\tlocal seenUpgrades: { [string]: boolean } = {}\n",
		"\tfor _, upgrade in ProgressionConfig.Upgrades do\n",
		"\t\tlocal id = upgrade.id\n",
		"\t\tassert(not seenUpgrades[id], `ProgressionConfig: duplicate upgrade id {id}`)\n",
		"\t\tseenUpgrades[id] = true\n",
		"\t\tassert(seenCurrencies[upgrade.currencyId], `ProgressionConfig: {id} uses unknown currency {upgrade.currencyId}`)\n",
		"\t\tassert(upgrade.startingLevel >= 1 and upgrade.startingLevel % 1 == 0, `ProgressionConfig: {id} startingLevel must be a whole number >= 1`)\n",
		"\t\tassert(upgrade.maxLevel >= upgrade.startingLevel and upgrade.maxLevel % 1 == 0, `ProgressionConfig: {id} maxLevel must be a whole number >= startingLevel`)\n",
		"\t\tassert(upgrade.baseValue > 0, `ProgressionConfig: {id} baseValue must be > 0`)\n",
		"\t\tassert(upgrade.milestoneInterval >= 1 and upgrade.milestoneInterval % 1 == 0, `ProgressionConfig: {id} milestoneInterval must be a whole number >= 1`)\n",
		"\t\tassert(upgrade.milestoneMultiplier >= 1, `ProgressionConfig: {id} milestoneMultiplier must be >= 1`)\n",
		"\t\tassert(upgrade.baseCost >= 1, `ProgressionConfig: {id} baseCost must be >= 1`)\n",
		"\t\tassert(upgrade.costGrowth >= 1, `ProgressionConfig: {id} costGrowth must be >= 1`)\n",
		"\tend\n",
		"\n",
		"\t-- Level 1 tap damage must equal Milestone 1's starting tap damage.\n",
		"\tlocal tap = ProgressionConfig.TapDamageUpgrade\n",
		"\tassert(\n",
		"\t\tBigNum.eq(ProgressionConfig.GetUpgradeValue(tap, tap.startingLevel), BigNum.fromNumber(GameConfig.Combat.StartingTapDamage)),\n",
		"\t\t\"ProgressionConfig: TapDamage at its starting level must equal GameConfig.Combat.StartingTapDamage\"\n",
		"\t)\n",
		"end\n",
		"\n",
		"validate()\n",
		"\n",
		"return table.freeze(ProgressionConfig)\n",
	},
}
FILES[4] = {
	path = "ServerScriptService/CombatRules",
	className = "ModuleScript",
	bytes = 2920,
	lines = 91,
	adler32 = 833873800,
	sha256 = "ecd41a70f93c1f506f8fe50f722c6a57e5d54e77c513d01fcd189be22601ff9b",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatRules\n",
		"\tLocation: ServerScriptService > CombatRules (ModuleScript)\n",
		"\n",
		"\tPure combat rules for one player's state: enemy spawning, applying a hit,\n",
		"\tdefeat, reward and stage advance. No Roblox services, no networking, no\n",
		"\tyields, so the Milestone 1 guarantees can be unit-tested directly.\n",
		"\tCombatService owns one state per player and does the networking and Gold.\n",
		"\n",
		"\tExactly-once defeat: resolveHit never yields. When HP reaches zero it\n",
		"\tcomputes the reward, advances the stage and spawns the next enemy (full HP)\n",
		"\tin the same step, so the next hit can only damage the new enemy.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"export type CombatState = {\n",
		"\tstage: number,\n",
		"\ttapDamage: BigNum,\n",
		"\tenemyId: number, -- increments every time a new enemy spawns\n",
		"\tenemyName: string,\n",
		"\tenemyHp: BigNum,\n",
		"\tenemyMaxHp: BigNum,\n",
		"}\n",
		"\n",
		"export type HitOutcome = {\n",
		"\tappliedDamage: BigNum, -- never more than the HP the enemy had\n",
		"\tdefeated: boolean,\n",
		"\tdefeatedStage: number, -- the stage the hit happened on\n",
		"\tgoldAwarded: BigNum, -- zero unless defeated\n",
		"}\n",
		"\n",
		"local CombatRules = {}\n",
		"\n",
		"-- Replaces the current enemy with a fresh one for the state's current stage.\n",
		"function CombatRules.spawnEnemy(state: CombatState)\n",
		"\tstate.enemyId += 1\n",
		"\tstate.enemyName = GameConfig.GetEnemyName(state.stage)\n",
		"\tstate.enemyMaxHp = GameConfig.GetEnemyMaxHp(state.stage)\n",
		"\tstate.enemyHp = state.enemyMaxHp\n",
		"end\n",
		"\n",
		"-- Milestone 1 starting state: stage 1, tap damage 1, a full-HP Forest Slime.\n",
		"-- A saved stage (Milestone 3, already validated by ProfileSchema) starts there with a fresh enemy.\n",
		"function CombatRules.newState(stage: number?): CombatState\n",
		"\tlocal state: CombatState = {\n",
		"\t\tstage = stage or GameConfig.Combat.StartingStage,\n",
		"\t\ttapDamage = BigNum.fromNumber(GameConfig.Combat.StartingTapDamage),\n",
		"\t\tenemyId = 0,\n",
		"\t\tenemyName = \"\",\n",
		"\t\tenemyHp = BigNum.zero,\n",
		"\t\tenemyMaxHp = BigNum.zero,\n",
		"\t}\n",
		"\tCombatRules.spawnEnemy(state)\n",
		"\treturn state\n",
		"end\n",
		"\n",
		"-- Applies a validated, positive damage amount. Overkill does not carry over to the next enemy.\n",
		"function CombatRules.resolveHit(state: CombatState, damage: BigNum): HitOutcome\n",
		"\tlocal appliedDamage = BigNum.min(damage, state.enemyHp)\n",
		"\tstate.enemyHp = BigNum.sub(state.enemyHp, appliedDamage)\n",
		"\n",
		"\tif not BigNum.isZero(state.enemyHp) then\n",
		"\t\treturn {\n",
		"\t\t\tappliedDamage = appliedDamage,\n",
		"\t\t\tdefeated = false,\n",
		"\t\t\tdefeatedStage = state.stage,\n",
		"\t\t\tgoldAwarded = BigNum.zero,\n",
		"\t\t}\n",
		"\tend\n",
		"\n",
		"\tlocal defeatedStage = state.stage\n",
		"\tlocal goldAwarded = GameConfig.GetGoldReward(defeatedStage)\n",
		"\tstate.stage += 1\n",
		"\tCombatRules.spawnEnemy(state)\n",
		"\n",
		"\treturn {\n",
		"\t\tappliedDamage = appliedDamage,\n",
		"\t\tdefeated = true,\n",
		"\t\tdefeatedStage = defeatedStage,\n",
		"\t\tgoldAwarded = goldAwarded,\n",
		"\t}\n",
		"end\n",
		"\n",
		"return table.freeze(CombatRules)\n",
	},
}
FILES[5] = {
	path = "ServerScriptService/CombatService",
	className = "ModuleScript",
	bytes = 8719,
	lines = 263,
	adler32 = 1066130401,
	sha256 = "3759efdd10b4cc1307e37f236316b6cf126f2c29853627041b59318c48ab0984",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatService\n",
		"\tLocation: ServerScriptService > CombatService (ModuleScript)\n",
		"\n",
		"\tServer-authoritative combat for every player:\n",
		"\t  - owns each player's combat state (stage, tap damage, enemy HP)\n",
		"\t  - validates and rate-limits attack requests\n",
		"\t  - applies all damage through ONE function (ApplyDamage), so future damage\n",
		"\t    sources (hero DPS) share the exact same death/reward/stage logic\n",
		"\t  - sends authoritative updates only to the player they belong to\n",
		"\n",
		"\tMilestone 2 changes:\n",
		"\t  - HP and damage are BigNums (finite precision: tested early-game values exact, large values approximate)\n",
		"\t  - the enemy rules live in CombatRules (pure, unit-tested)\n",
		"\t  - Gold lives in CurrencyService; a defeat calls CurrencyService.Grant\n",
		"\t  - SetTapDamage lets UpgradeService change tap damage\n",
		"\t  - the ClientReady handshake moved to PlayerSessionService\n",
		"\n",
		"\tThe client never sends numbers. RequestAttack carries no arguments, and\n",
		"\tanything an exploiter adds to it is ignored.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local CombatRules = require(ServerScriptService:WaitForChild(\"CombatRules\"))\n",
		"local CurrencyService = require(ServerScriptService:WaitForChild(\"CurrencyService\"))\n",
		"local PlayerDataService = require(ServerScriptService:WaitForChild(\"PlayerDataService\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"type CombatState = CombatRules.CombatState\n",
		"type CombatSnapshot = GameConfig.CombatSnapshot\n",
		"type CombatUpdate = GameConfig.CombatUpdate\n",
		"type DamageSource = GameConfig.DamageSource\n",
		"\n",
		"type PlayerCombatState = {\n",
		"\tcombat: CombatState,\n",
		"\trunHighestStage: number,\n",
		"\tlifetimeHighestStage: number,\n",
		"\tlastTapAt: number, -- os.clock() of the last ACCEPTED tap\n",
		"\tsynced: boolean, -- false until the client's first full sync; no partial updates before that\n",
		"}\n",
		"\n",
		"local REMOTE_WAIT_TIMEOUT = 10\n",
		"\n",
		"local remotesFolder = ReplicatedStorage:WaitForChild(GameConfig.Network.RemotesFolderName)\n",
		"\n",
		"local function getRemoteEvent(remoteName: string): RemoteEvent\n",
		"\tlocal instance = remotesFolder:WaitForChild(remoteName, REMOTE_WAIT_TIMEOUT)\n",
		"\tif instance and instance:IsA(\"RemoteEvent\") then\n",
		"\t\treturn instance\n",
		"\tend\n",
		"\terror(`[CombatService] Missing RemoteEvent ReplicatedStorage.{GameConfig.Network.RemotesFolderName}.{remoteName}`)\n",
		"end\n",
		"\n",
		"local requestAttackRemote = getRemoteEvent(GameConfig.Network.RequestAttack)\n",
		"local combatUpdateRemote = getRemoteEvent(GameConfig.Network.CombatUpdate)\n",
		"\n",
		"local playerStates: { [Player]: PlayerCombatState } = {}\n",
		"local started = false\n",
		"\n",
		"local CombatService = {}\n",
		"\n",
		"local function countTrackedPlayers(): number\n",
		"\tlocal count = 0\n",
		"\tfor _ in playerStates do\n",
		"\t\tcount += 1\n",
		"\tend\n",
		"\treturn count\n",
		"end\n",
		"\n",
		"local function logLifecycle(message: string)\n",
		"\tif GameConfig.Debug.LogPlayerLifecycle then\n",
		"\t\tprint(`[CombatService] {message} (tracked players: {countTrackedPlayers()})`)\n",
		"\tend\n",
		"end\n",
		"\n",
		"local function buildSnapshot(combat: CombatState): CombatSnapshot\n",
		"\treturn {\n",
		"\t\tstage = combat.stage,\n",
		"\t\ttapDamage = BigNum.toString(combat.tapDamage),\n",
		"\t\tenemyId = combat.enemyId,\n",
		"\t\tenemyName = combat.enemyName,\n",
		"\t\tenemyHp = BigNum.toString(combat.enemyHp),\n",
		"\t\tenemyMaxHp = BigNum.toString(combat.enemyMaxHp),\n",
		"\t}\n",
		"end\n",
		"\n",
		"-- FireClient targets exactly one player, so updates are never broadcast.\n",
		"local function sendUpdate(player: Player, state: PlayerCombatState, update: CombatUpdate)\n",
		"\tif not state.synced or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tcombatUpdateRemote:FireClient(player, update)\n",
		"end\n",
		"\n",
		"-- Accepts a BigNum or a plain number (Milestone 1 call shape); nil for anything invalid or not positive.\n",
		"local function toDamage(amount: BigNum | number): BigNum?\n",
		"\tif typeof(amount) == \"number\" then\n",
		"\t\tif amount ~= amount or amount <= 0 or amount == math.huge then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\treturn BigNum.fromNumber(amount)\n",
		"\tend\n",
		"\tif not BigNum.isValid(amount) or BigNum.isZero(amount) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn amount\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tThe ONLY place damage is applied. Taps call it today; hero DPS can call it later.\n",
		"\tIt never yields: the hit, any defeat, the Gold grant and the next spawn\n",
		"\thappen as one uninterrupted step, so an enemy is rewarded exactly once.\n",
		"]]\n",
		"function CombatService.ApplyDamage(player: Player, amount: BigNum | number, source: DamageSource): boolean\n",
		"\tlocal state = playerStates[player]\n",
		"\tif not state or not PlayerDataService.CanMutate(player) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal damage = toDamage(amount)\n",
		"\tif damage == nil then\n",
		"\t\twarn(`[CombatService] Rejected invalid damage amount for {player.Name}`)\n",
		"\t\treturn false\n",
		"\tend\n",
		"\n",
		"\tlocal clearedStage = state.combat.stage\n",
		"\tlocal outcome = CombatRules.resolveHit(state.combat, damage)\n",
		"\n",
		"\tif not outcome.defeated then\n",
		"\t\tsendUpdate(player, state, {\n",
		"\t\t\tkind = \"Hit\",\n",
		"\t\t\tsnapshot = buildSnapshot(state.combat),\n",
		"\t\t\tdamage = BigNum.toString(outcome.appliedDamage),\n",
		"\t\t\tsource = source,\n",
		"\t\t})\n",
		"\t\treturn true\n",
		"\tend\n",
		"\tstate.runHighestStage = math.max(state.runHighestStage, clearedStage)\n",
		"\tstate.lifetimeHighestStage = math.max(state.lifetimeHighestStage, clearedStage)\n",
		"\tPlayerDataService.MarkDirty(player)\n",
		"\n",
		"\tif not BigNum.isZero(outcome.goldAwarded) then\n",
		"\t\tCurrencyService.Grant(player, ProgressionConfig.GoldCurrencyId, outcome.goldAwarded, \"EnemyDefeated\")\n",
		"\tend\n",
		"\n",
		"\tsendUpdate(player, state, {\n",
		"\t\tkind = \"Defeated\",\n",
		"\t\tsnapshot = buildSnapshot(state.combat),\n",
		"\t\tdamage = BigNum.toString(outcome.appliedDamage),\n",
		"\t\tsource = source,\n",
		"\t\tgoldAwarded = BigNum.toString(outcome.goldAwarded),\n",
		"\t})\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Sets the damage each accepted tap deals. Called by UpgradeService.\n",
		"function CombatService.SetTapDamage(player: Player, amount: BigNum): boolean\n",
		"\tlocal state = playerStates[player]\n",
		"\tif not state or not BigNum.isValid(amount) or BigNum.isZero(amount) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tstate.combat.tapDamage = amount\n",
		"\tsendUpdate(player, state, {\n",
		"\t\tkind = \"Stats\",\n",
		"\t\tsnapshot = buildSnapshot(state.combat),\n",
		"\t})\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"local function handleTapRequest(player: Player)\n",
		"\tlocal state = playerStates[player]\n",
		"\tif not state or not state.synced then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal now = os.clock()\n",
		"\tif now - state.lastTapAt < GameConfig.Combat.TapCooldown then\n",
		"\t\treturn -- too soon: silently drop (no reply, so spam costs the server almost nothing)\n",
		"\tend\n",
		"\tstate.lastTapAt = now\n",
		"\n",
		"\t-- Damage comes from server state, never from the client.\n",
		"\tif CombatService.ApplyDamage(player, state.combat.tapDamage, \"Tap\") then\n",
		"\t\tPlayerDataService.RecordActivity(player)\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- stage: the saved stage from the player's profile (nil for the starting stage).\n",
		"function CombatService.AddPlayer(player: Player, stage: number?, runHighestStage: number?, lifetimeHighestStage: number?)\n",
		"\tif playerStates[player] or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal combat = CombatRules.newState(stage)\n",
		"\tlocal highest = runHighestStage or math.max(0, combat.stage - 1)\n",
		"\tplayerStates[player] = {\n",
		"\t\tcombat = combat,\n",
		"\t\trunHighestStage = highest,\n",
		"\t\tlifetimeHighestStage = lifetimeHighestStage or highest,\n",
		"\t\tlastTapAt = -math.huge,\n",
		"\t\tsynced = false,\n",
		"\t}\n",
		"\tlogLifecycle(`Created combat state for {player.Name}`)\n",
		"end\n",
		"\n",
		"function CombatService.RemovePlayer(player: Player)\n",
		"\tif playerStates[player] then\n",
		"\t\tplayerStates[player] = nil\n",
		"\t\tlogLifecycle(`Removed combat state for {player.Name}`)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function CombatService.HasPlayer(player: Player): boolean\n",
		"\treturn playerStates[player] ~= nil\n",
		"end\n",
		"\n",
		"-- The player's current stage, for saving.\n",
		"function CombatService.GetStage(player: Player): number?\n",
		"\tlocal state = playerStates[player]\n",
		"\treturn if state then state.combat.stage else nil\n",
		"end\n",
		"\n",
		"function CombatService.GetHighestStages(player: Player): (number?, number?)\n",
		"\tlocal state = playerStates[player]\n",
		"\tif state == nil then\n",
		"\t\treturn nil, nil\n",
		"\tend\n",
		"\treturn state.runHighestStage, state.lifetimeHighestStage\n",
		"end\n",
		"\n",
		"-- Sends the full combat state and allows hit/stat updates from now on.\n",
		"function CombatService.SyncPlayer(player: Player)\n",
		"\tlocal state = playerStates[player]\n",
		"\tif not state then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstate.synced = true\n",
		"\tsendUpdate(player, state, {\n",
		"\t\tkind = \"Sync\",\n",
		"\t\tsnapshot = buildSnapshot(state.combat),\n",
		"\t})\n",
		"end\n",
		"\n",
		"-- Connects the attack remote. Safe to call once; repeated calls are ignored.\n",
		"function CombatService.Start()\n",
		"\tif started then\n",
		"\t\twarn(\"[CombatService] Start() was called more than once; ignoring.\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstarted = true\n",
		"\n",
		"\t-- Extra arguments sent by a client are deliberately not read.\n",
		"\trequestAttackRemote.OnServerEvent:Connect(function(player: Player)\n",
		"\t\thandleTapRequest(player)\n",
		"\tend)\n",
		"end\n",
		"\n",
		"return CombatService\n",
	},
}
FILES[6] = {
	path = "ServerScriptService/CurrencyService",
	className = "ModuleScript",
	bytes = 5702,
	lines = 165,
	adler32 = 2447495618,
	sha256 = "45d89129043abcb92f1917efd43a416eb3a06dee58c592c4599e46615b03eec5",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCurrencyService\n",
		"\tLocation: ServerScriptService > CurrencyService (ModuleScript)\n",
		"\n",
		"\tOwns every player's balances (one Wallet each) and sends the owning client\n",
		"\tits balances after each change. Gold is earned in CombatService and spent\n",
		"\tin UpgradeService; both go through Grant / TrySpend here.\n",
		"\n",
		"\tGacha compatibility: currencies are ids from ProgressionConfig. Future\n",
		"\tsummon currencies are added there and handled here unchanged. There is no\n",
		"\tfunction that converts one currency into another.\n",
		"\n",
		"\tMilestone 3: AddPlayer accepts the balances loaded by PlayerDataService.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local Wallet = require(ServerScriptService:WaitForChild(\"Wallet\"))\n",
		"local PlayerDataService = require(ServerScriptService:WaitForChild(\"PlayerDataService\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"type Wallet = Wallet.Wallet\n",
		"type CurrencyUpdate = GameConfig.CurrencyUpdate\n",
		"\n",
		"type CurrencyState = {\n",
		"\twallet: Wallet,\n",
		"\tsynced: boolean, -- false until the client's first full sync; no partial updates before that\n",
		"}\n",
		"\n",
		"local REMOTE_WAIT_TIMEOUT = 10\n",
		"\n",
		"local remotesFolder = ReplicatedStorage:WaitForChild(GameConfig.Network.RemotesFolderName)\n",
		"\n",
		"local function getRemoteEvent(remoteName: string): RemoteEvent\n",
		"\tlocal instance = remotesFolder:WaitForChild(remoteName, REMOTE_WAIT_TIMEOUT)\n",
		"\tif instance and instance:IsA(\"RemoteEvent\") then\n",
		"\t\treturn instance\n",
		"\tend\n",
		"\terror(`[CurrencyService] Missing RemoteEvent ReplicatedStorage.{GameConfig.Network.RemotesFolderName}.{remoteName}`)\n",
		"end\n",
		"\n",
		"local currencyUpdateRemote = getRemoteEvent(GameConfig.Network.CurrencyUpdate)\n",
		"\n",
		"local states: { [Player]: CurrencyState } = {}\n",
		"\n",
		"local CurrencyService = {}\n",
		"\n",
		"local function startingBalances(): { [string]: BigNum }\n",
		"\tlocal balances: { [string]: BigNum } = {}\n",
		"\tfor _, currency in ProgressionConfig.Currencies do\n",
		"\t\tbalances[currency.id] = BigNum.fromNumber(currency.startingBalance)\n",
		"\tend\n",
		"\treturn balances\n",
		"end\n",
		"\n",
		"local function sendBalances(player: Player, state: CurrencyState)\n",
		"\tif not state.synced or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal update: CurrencyUpdate = { balances = Wallet.snapshot(state.wallet) }\n",
		"\tcurrencyUpdateRemote:FireClient(player, update)\n",
		"end\n",
		"\n",
		"local function logEconomy(message: string)\n",
		"\tif GameConfig.Debug.LogEconomy then\n",
		"\t\tprint(`[CurrencyService] {message}`)\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- saved: balances from the player's profile, already validated by ProfileSchema (nil for a new player).\n",
		"function CurrencyService.AddPlayer(player: Player, saved: { [string]: BigNum }?)\n",
		"\tif states[player] or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal balances = startingBalances()\n",
		"\tif saved then\n",
		"\t\tfor currencyId in balances do\n",
		"\t\t\tlocal balance = saved[currencyId]\n",
		"\t\t\tif balance ~= nil and BigNum.isValid(balance) then\n",
		"\t\t\t\tbalances[currencyId] = balance\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\tend\n",
		"\tstates[player] = {\n",
		"\t\twallet = Wallet.new(balances),\n",
		"\t\tsynced = false,\n",
		"\t}\n",
		"end\n",
		"\n",
		"function CurrencyService.RemovePlayer(player: Player)\n",
		"\tstates[player] = nil\n",
		"end\n",
		"\n",
		"function CurrencyService.HasPlayer(player: Player): boolean\n",
		"\treturn states[player] ~= nil\n",
		"end\n",
		"\n",
		"function CurrencyService.GetBalance(player: Player, currencyId: string): BigNum?\n",
		"\tlocal state = states[player]\n",
		"\tif not state or not Wallet.has(state.wallet, currencyId) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn Wallet.get(state.wallet, currencyId)\n",
		"end\n",
		"\n",
		"-- Adds a positive amount. `reason` describes the source (for logs and future analytics).\n",
		"function CurrencyService.Grant(player: Player, currencyId: string, amount: BigNum, reason: string, recordTransaction: boolean?): boolean\n",
		"\tlocal state = states[player]\n",
		"\tif not state or not PlayerDataService.CanMutate(player) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tif not Wallet.grant(state.wallet, currencyId, amount) then\n",
		"\t\twarn(`[CurrencyService] Rejected {currencyId} grant for {player.Name} ({reason})`)\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tif recordTransaction ~= false then\n",
		"\t\tPlayerDataService.RecordTransaction(player, {\n",
		"\t\t\tkind = \"Grant\", currencyId = currencyId, amount = BigNum.toString(amount),\n",
		"\t\t\treason = if reason == \"\" then nil else string.sub(reason, 1, 128),\n",
		"\t\t})\n",
		"\tend\n",
		"\tPlayerDataService.MarkDirty(player)\n",
		"\tlogEconomy(`+{BigNum.toString(amount)} {currencyId} for {player.Name} ({reason})`)\n",
		"\tsendBalances(player, state)\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Spends the whole amount only if the player can afford it. Never yields, never goes negative.\n",
		"function CurrencyService.TrySpend(player: Player, currencyId: string, amount: BigNum, reason: string, recordTransaction: boolean?): boolean\n",
		"\tlocal state = states[player]\n",
		"\tif not state or not PlayerDataService.CanMutate(player) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tif not Wallet.trySpend(state.wallet, currencyId, amount) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tif recordTransaction ~= false then\n",
		"\t\tPlayerDataService.RecordTransaction(player, {\n",
		"\t\t\tkind = \"Spend\", currencyId = currencyId, amount = BigNum.toString(amount),\n",
		"\t\t\treason = if reason == \"\" then nil else string.sub(reason, 1, 128),\n",
		"\t\t})\n",
		"\tend\n",
		"\tPlayerDataService.MarkDirty(player)\n",
		"\tlogEconomy(`-{BigNum.toString(amount)} {currencyId} for {player.Name} ({reason})`)\n",
		"\tsendBalances(player, state)\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Sends the full balances and allows change updates from now on.\n",
		"function CurrencyService.SyncPlayer(player: Player)\n",
		"\tlocal state = states[player]\n",
		"\tif not state then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstate.synced = true\n",
		"\tsendBalances(player, state)\n",
		"end\n",
		"\n",
		"return CurrencyService\n",
	},
}
FILES[7] = {
	path = "ServerScriptService/PlayerDataService",
	className = "ModuleScript",
	bytes = 12643,
	lines = 373,
	adler32 = 2998784157,
	sha256 = "1a8f879f631d80a3e9cf4c48ef9c3d4574039160a34a8e125a17b6b7c64c9448",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tPlayerDataService\n",
		"\tLocation: ServerScriptService > PlayerDataService (ModuleScript)\n",
		"\n",
		"\tLoads, autosaves and releases each player's versioned profile (ProfileSchema)\n",
		"\tthrough ProfileStore's session lock. PlayerSessionService calls Load before the\n",
		"\tgameplay services add the player, and Release when the player leaves.\n",
		"\n",
		"\t  - Load failures never fall back to defaults: Load returns nil and a message,\n",
		"\t    and the player is asked to rejoin. Their stored record is left untouched.\n",
		"\t  - A session that loses its lock (another server took over a stale lock) stops\n",
		"\t    saving, so two servers never write the same profile.\n",
		"\t  - Autosave runs every AUTOSAVE_INTERVAL seconds, which also keeps the lock live.\n",
		"\t    Shutdown (BindToClose) releases every remaining session.\n",
		"\t  - Studio: an unpublished place, or one without Studio API access, uses an\n",
		"\t    in-memory store, so saves last only for that test session. Live servers\n",
		"\t    always use the DataStore.\n",
		"]]\n",
		"\n",
		"local DataStoreService = game:GetService(\"DataStoreService\")\n",
		"local HttpService = game:GetService(\"HttpService\")\n",
		"local Players = game:GetService(\"Players\")\n",
		"local RunService = game:GetService(\"RunService\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local ProfileStore = require(ServerScriptService:WaitForChild(\"ProfileStore\"))\n",
		"\n",
		"type Profile = ProfileSchema.Profile\n",
		"\n",
		"type Entry = {\n",
		"\tsession: string,\n",
		"\tuserId: number,\n",
		"\tprofile: Profile,\n",
		"\trevision: number,\n",
		"\tsavedRevision: number,\n",
		"\tactivityUntil: number,\n",
		"\tlastCountedAt: number,\n",
		"\tsaving: boolean,\n",
		"\tstate: \"Active\" | \"Releasing\" | \"Released\" | \"LockLost\",\n",
		"}\n",
		"\n",
		"local STORE_NAME = \"EmberboundProfiles\" -- the schema version is inside each record, not in the store name\n",
		"local AUTOSAVE_INTERVAL = 60\n",
		"local ACTIVE_IDLE_WINDOW = 10 -- accepted taps and successful purchases extend this window\n",
		"local LOCK_TIMEOUT = 300 -- five missed autosaves before another server may take over the lock\n",
		"local LOAD_FAILED_MESSAGE = \"Emberbound could not load your save. Your progress is safe; please rejoin.\"\n",
		"local LOCKED_MESSAGE = \"Your save is still open on another server. Please wait a moment and rejoin.\"\n",
		"local NEWER_MESSAGE = \"This server is out of date for your save. Please rejoin to join a newer server.\"\n",
		"local LOCK_LOST_MESSAGE = \"Your save was opened on another server. Please rejoin.\"\n",
		"local SHUTDOWN_WAIT = 25 -- seconds BindToClose waits for releases (Roblox allows 30)\n",
		"\n",
		"local entries: { [Player]: Entry } = {}\n",
		"local releasing: { [number]: number } = {} -- userId -> releases in flight on this server\n",
		"local options: ProfileStore.Options? = nil\n",
		"local initializingOptions = false\n",
		"local snapshotProvider: ((Player) -> Profile?)? = nil\n",
		"local started = false\n",
		"\n",
		"local PlayerDataService = {}\n",
		"\n",
		"local function memoryStore(): ProfileStore.Store\n",
		"\tlocal records: { [string]: string } = {}\n",
		"\treturn {\n",
		"\t\tupdate = function(key: string, transform: (unknown) -> unknown?, _userId: number)\n",
		"\t\t\tlocal stored = records[key]\n",
		"\t\t\tlocal old = if stored ~= nil then HttpService:JSONDecode(stored) else nil\n",
		"\t\t\tlocal new = transform(old)\n",
		"\t\t\tif new ~= nil then\n",
		"\t\t\t\trecords[key] = HttpService:JSONEncode(new) -- the same JSON round trip a DataStore applies\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function dataStore(store: DataStore): ProfileStore.Store\n",
		"\treturn {\n",
		"\t\tupdate = function(key: string, transform: (unknown) -> unknown?, userId: number)\n",
		"\t\t\tstore:UpdateAsync(key, function(old: unknown): (unknown?, { number }?)\n",
		"\t\t\t\tlocal new = transform(old)\n",
		"\t\t\t\tif new == nil then\n",
		"\t\t\t\t\treturn nil, nil -- cancels the write\n",
		"\t\t\t\tend\n",
		"\t\t\t\treturn new, { userId } -- tags the key with the player for erasure requests\n",
		"\t\t\tend)\n",
		"\t\tend,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function chooseStore(): ProfileStore.Store\n",
		"\tif not RunService:IsStudio() then\n",
		"\t\treturn dataStore(DataStoreService:GetDataStore(STORE_NAME))\n",
		"\tend\n",
		"\tif game.PlaceId ~= 0 then\n",
		"\t\tlocal ok = pcall(function()\n",
		"\t\t\tlocal store = DataStoreService:GetDataStore(STORE_NAME)\n",
		"\t\t\tstore:GetAsync(\"studio_access_check\")\n",
		"\t\tend)\n",
		"\t\tif ok then\n",
		"\t\t\tprint(\"[PlayerDataService] Studio is using the place's DataStore: saves persist.\")\n",
		"\t\t\treturn dataStore(DataStoreService:GetDataStore(STORE_NAME))\n",
		"\t\tend\n",
		"\tend\n",
		"\tprint(\"[PlayerDataService] Studio without DataStore access: saves are kept in memory for this test session only.\")\n",
		"\treturn memoryStore()\n",
		"end\n",
		"\n",
		"local function getOptions(): ProfileStore.Options\n",
		"\twhile initializingOptions do\n",
		"\t\ttask.wait(0.1)\n",
		"\tend\n",
		"\tif options == nil then\n",
		"\t\tinitializingOptions = true\n",
		"\t\tlocal ok, selected = pcall(chooseStore)\n",
		"\t\tinitializingOptions = false\n",
		"\t\tif not ok then\n",
		"\t\t\terror(selected)\n",
		"\t\tend\n",
		"\t\toptions = {\n",
		"\t\t\tstore = selected,\n",
		"\t\t\tjob = game.JobId,\n",
		"\t\t\tnow = function(): number\n",
		"\t\t\t\treturn os.time()\n",
		"\t\t\tend,\n",
		"\t\t\twait = function(seconds: number)\n",
		"\t\t\t\ttask.wait(seconds)\n",
		"\t\t\tend,\n",
		"\t\t\tlockTimeout = LOCK_TIMEOUT,\n",
		"\t\t\tattempts = 4,\n",
		"\t\t\tlockedRetries = 6,\n",
		"\t\t\tlockedRetryDelay = 5,\n",
		"\t\t}\n",
		"\tend\n",
		"\treturn options :: ProfileStore.Options\n",
		"end\n",
		"\n",
		"local function failureMessage(result: ProfileStore.LoadResult): string\n",
		"\tif result.status == \"Locked\" then\n",
		"\t\treturn LOCKED_MESSAGE\n",
		"\tend\n",
		"\tif result.status == \"Invalid\" and result.detail ~= nil and string.find(result.detail, \"newer\", 1, true) then\n",
		"\t\treturn NEWER_MESSAGE\n",
		"\tend\n",
		"\treturn LOAD_FAILED_MESSAGE\n",
		"end\n",
		"\n",
		"local function save(player: Player, entry: Entry, profile: Profile?, release: boolean): ProfileStore.SaveStatus\n",
		"\twhile entry.saving do\n",
		"\t\ttask.wait(0.1) -- one write per player at a time; a release waits for an autosave in flight\n",
		"\tend\n",
		"\tif entry.state == \"LockLost\" or entry.state == \"Released\" then\n",
		"\t\treturn if entry.state == \"Released\" then \"Saved\" else \"LockLost\"\n",
		"\tend\n",
		"\tentry.saving = true\n",
		"\tlocal revision = entry.revision\n",
		"\tlocal ok, status, detail = pcall(function()\n",
		"\t\treturn ProfileStore.save(getOptions(), entry.userId, entry.session, profile, release)\n",
		"\tend)\n",
		"\tentry.saving = false\n",
		"\tif not ok then\n",
		"\t\twarn(`[PlayerDataService] Save for {player.Name} raised an error: {status}`)\n",
		"\t\treturn \"Error\"\n",
		"\tend\n",
		"\tif status == \"LockLost\" then\n",
		"\t\tentry.state = \"LockLost\"\n",
		"\t\twarn(`[PlayerDataService] {player.Name}'s save was taken over by another server; this server stops saving it.`)\n",
		"\t\tif player.Parent == Players then\n",
		"\t\t\tplayer:Kick(LOCK_LOST_MESSAGE)\n",
		"\t\tend\n",
		"\telseif status == \"Error\" then\n",
		"\t\twarn(`[PlayerDataService] Could not save {player.Name}: {detail}`)\n",
		"\telseif release then\n",
		"\t\tentry.state = \"Released\"\n",
		"\tend\n",
		"\tif status == \"Saved\" then\n",
		"\t\tentry.savedRevision = revision\n",
		"\tend\n",
		"\treturn status\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tLoads and claims the player's profile. Yields. Returns the profile, or nil and the message\n",
		"\tto show when the player must rejoin. isWanted() lets the caller cancel (the player left).\n",
		"]]\n",
		"function PlayerDataService.Load(player: Player, isWanted: () -> boolean): (Profile?, string?)\n",
		"\tlocal userId = player.UserId\n",
		"\tlocal waited = 0\n",
		"\twhile (releasing[userId] or 0) > 0 and waited < SHUTDOWN_WAIT and isWanted() do\n",
		"\t\ttask.wait(0.25) -- the same player's previous session on this server is still saving\n",
		"\t\twaited += 0.25\n",
		"\tend\n",
		"\tif not isWanted() then\n",
		"\t\treturn nil, LOAD_FAILED_MESSAGE\n",
		"\tend\n",
		"\tif (releasing[userId] or 0) > 0 then\n",
		"\t\treturn nil, LOCKED_MESSAGE\n",
		"\tend\n",
		"\tlocal session = HttpService:GenerateGUID(false)\n",
		"\tlocal ok, result = pcall(function()\n",
		"\t\treturn ProfileStore.load(getOptions(), userId, session, isWanted)\n",
		"\tend)\n",
		"\tif not ok then\n",
		"\t\twarn(`[PlayerDataService] Loading {player.Name}'s profile raised an error: {result}`)\n",
		"\t\treturn nil, LOAD_FAILED_MESSAGE\n",
		"\tend\n",
		"\tlocal loaded = result :: ProfileStore.LoadResult\n",
		"\tif loaded.status ~= \"Loaded\" or loaded.profile == nil then\n",
		"\t\tif loaded.status ~= \"Cancelled\" then\n",
		"\t\t\twarn(`[PlayerDataService] Could not load {player.Name}'s profile ({loaded.status}): {loaded.detail or \"no detail\"}`)\n",
		"\t\tend\n",
		"\t\treturn nil, failureMessage(loaded)\n",
		"\tend\n",
		"\tentries[player] = {\n",
		"\t\tsession = session,\n",
		"\t\tuserId = userId,\n",
		"\t\tprofile = loaded.profile,\n",
		"\t\trevision = 0,\n",
		"\t\tsavedRevision = 0,\n",
		"\t\tactivityUntil = os.clock(),\n",
		"\t\tlastCountedAt = os.clock(),\n",
		"\t\tsaving = false,\n",
		"\t\tstate = \"Active\",\n",
		"\t}\n",
		"\treturn loaded.profile, nil\n",
		"end\n",
		"\n",
		"-- Saves the final profile (nil keeps the stored one) and releases the lock. Does not yield.\n",
		"function PlayerDataService.Release(player: Player, profile: Profile?)\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry == nil then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tentries[player] = nil\n",
		"\tif entry.state ~= \"Active\" then\n",
		"\t\treturn -- the lock was lost: nothing may be written\n",
		"\tend\n",
		"\tentry.state = \"Releasing\"\n",
		"\treleasing[entry.userId] = (releasing[entry.userId] or 0) + 1\n",
		"\tlocal function finishRelease()\n",
		"\t\tif save(player, entry, profile, true) == \"Error\" then\n",
		"\t\t\ttask.delay(5, finishRelease)\n",
		"\t\t\treturn\n",
		"\t\tend\n",
		"\t\tlocal remaining = (releasing[entry.userId] or 1) - 1\n",
		"\t\treleasing[entry.userId] = if remaining > 0 then remaining else nil\n",
		"\tend\n",
		"\ttask.spawn(finishRelease)\n",
		"end\n",
		"\n",
		"function PlayerDataService.HasProfile(player: Player): boolean\n",
		"\treturn entries[player] ~= nil\n",
		"end\n",
		"\n",
		"function PlayerDataService.MarkDirty(player: Player)\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry ~= nil and entry.state == \"Active\" then\n",
		"\t\tentry.revision += 1\n",
		"\tend\n",
		"end\n",
		"\n",
		"function PlayerDataService.IsDirty(player: Player): boolean\n",
		"\tlocal entry = entries[player]\n",
		"\treturn entry ~= nil and entry.revision ~= entry.savedRevision\n",
		"end\n",
		"\n",
		"function PlayerDataService.CanMutate(player: Player): boolean\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry == nil then\n",
		"\t\treturn not started -- standalone service callers remain supported before sessions start\n",
		"\tend\n",
		"\treturn entry.state == \"Active\" and entry.profile.pendingTransaction == nil\n",
		"\t\tand entry.profile.transactionId < ProfileSchema.MaxInteger\n",
		"end\n",
		"\n",
		"-- Complete in-memory operations are checkpointed with their balances/levels. The high-water\n",
		"-- id survives history pruning; external retryable operations use ProfileTransactions.prepare.\n",
		"function PlayerDataService.RecordTransaction(player: Player, raw: { [string]: any }): boolean\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry == nil or not PlayerDataService.CanMutate(player) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal payload = table.clone(raw)\n",
		"\tpayload.id = entry.profile.transactionId + 1\n",
		"\tlocal transaction = ProfileSchema.readTransaction(payload)\n",
		"\tif transaction == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tentry.profile.transactionId = transaction.id\n",
		"\ttable.insert(entry.profile.transactions, transaction)\n",
		"\tif #entry.profile.transactions > ProfileSchema.HistoryLimit then\n",
		"\t\ttable.remove(entry.profile.transactions, 1)\n",
		"\tend\n",
		"\tPlayerDataService.MarkDirty(player)\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"local function countActiveTime(player: Player, entry: Entry, now: number)\n",
		"\tif now <= entry.lastCountedAt then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal seconds = math.max(0, math.min(now, entry.activityUntil) - entry.lastCountedAt)\n",
		"\tentry.lastCountedAt = now\n",
		"\tif seconds > 0 then\n",
		"\t\tentry.profile.activeSeconds = math.min(ProfileSchema.MaxInteger, entry.profile.activeSeconds + seconds)\n",
		"\t\tPlayerDataService.MarkDirty(player)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function PlayerDataService.RecordActivity(player: Player)\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry == nil or entry.state ~= \"Active\" then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal now = os.clock()\n",
		"\tcountActiveTime(player, entry, now)\n",
		"\tentry.activityUntil = math.max(entry.activityUntil, now + ACTIVE_IDLE_WINDOW)\n",
		"end\n",
		"\n",
		"-- Saved metadata is retained when the session snapshots the live gameplay services.\n",
		"function PlayerDataService.CopyMetadata(player: Player): Profile?\n",
		"\tlocal entry = entries[player]\n",
		"\tif entry == nil or entry.state ~= \"Active\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tcountActiveTime(player, entry, os.clock())\n",
		"\treturn ProfileSchema.copy(entry.profile)\n",
		"end\n",
		"\n",
		"function PlayerDataService.GetProfile(player: Player): Profile?\n",
		"\tlocal provider = snapshotProvider\n",
		"\treturn if provider then provider(player) else PlayerDataService.CopyMetadata(player)\n",
		"end\n",
		"\n",
		"local function autosave()\n",
		"\tlocal provider = snapshotProvider\n",
		"\tif provider ~= nil then\n",
		"\t\tfor player, entry in entries do\n",
		"\t\t\tif entry.state == \"Active\" and not entry.saving then\n",
		"\t\t\t\tlocal profile = provider(player)\n",
		"\t\t\t\tif profile ~= nil then\n",
		"\t\t\t\t\ttask.spawn(save, player, entry, profile, false)\n",
		"\t\t\t\tend\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\tend\n",
		"\ttask.delay(AUTOSAVE_INTERVAL, autosave)\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tStarts autosave and the shutdown save. provider(player) returns the player's current\n",
		"\tprofile, read from the gameplay services in one non-yielding step (nil if not ready).\n",
		"]]\n",
		"function PlayerDataService.Start(provider: (Player) -> Profile?)\n",
		"\tif started then\n",
		"\t\twarn(\"[PlayerDataService] Start() was called more than once; ignoring.\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstarted = true\n",
		"\tsnapshotProvider = provider\n",
		"\ttask.delay(AUTOSAVE_INTERVAL, autosave)\n",
		"\tgame:BindToClose(function()\n",
		"\t\tfor player in entries do\n",
		"\t\t\tPlayerDataService.Release(player, provider(player))\n",
		"\t\tend\n",
		"\t\tlocal deadline = os.clock() + SHUTDOWN_WAIT\n",
		"\t\twhile next(releasing) ~= nil and os.clock() < deadline do\n",
		"\t\t\ttask.wait(0.25)\n",
		"\t\tend\n",
		"\tend)\n",
		"end\n",
		"\n",
		"return PlayerDataService\n",
	},
}
FILES[8] = {
	path = "ServerScriptService/PlayerSessionService",
	className = "ModuleScript",
	bytes = 7672,
	lines = 223,
	adler32 = 962820468,
	sha256 = "a421ecade796ff1b730f63d1e69b61da7b0ecced28b65b967e0bca3fbc618e2b",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tPlayerSessionService\n",
		"\tLocation: ServerScriptService > PlayerSessionService (ModuleScript)\n",
		"\n",
		"\tThe single place that controls each player's lifecycle across services:\n",
		"\t  join  -> PlayerDataService loads and locks the profile (this yields), then\n",
		"\t           CurrencyService, CombatService, StatService, UpgradeService add the\n",
		"\t           player from it (in that order, without yielding)\n",
		"\t  ready -> the client's ClientReady triggers one full sync from every service\n",
		"\t  leave -> the current state is read in one step and handed to\n",
		"\t           PlayerDataService.Release, then the services remove the player in\n",
		"\t           reverse order\n",
		"\n",
		"\tStartup order never matters: players already in the game are added on\n",
		"\tStart(), and a ClientReady that arrives before a player is added (or while\n",
		"\tthe profile load is running) is remembered and answered when ready.\n",
		"\n",
		"\tA failed load never starts the player on default data: the player is asked\n",
		"\tto rejoin, and their stored profile is left untouched. HeroService and\n",
		"\tSummonService later join the same add / sync / remove sequence.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local CombatService = require(ServerScriptService:WaitForChild(\"CombatService\"))\n",
		"local CurrencyService = require(ServerScriptService:WaitForChild(\"CurrencyService\"))\n",
		"local PlayerDataService = require(ServerScriptService:WaitForChild(\"PlayerDataService\"))\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local StatService = require(ServerScriptService:WaitForChild(\"StatService\"))\n",
		"local UpgradeService = require(ServerScriptService:WaitForChild(\"UpgradeService\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"\n",
		"type Profile = ProfileSchema.Profile\n",
		"\n",
		"type Session = {\n",
		"\tready: boolean,\n",
		"\tfailed: boolean, -- the profile could not be loaded; the player has been asked to rejoin\n",
		"\tsyncRequested: boolean,\n",
		"\tlastSyncAt: number,\n",
		"}\n",
		"\n",
		"local REMOTE_WAIT_TIMEOUT = 10\n",
		"\n",
		"local remotesFolder = ReplicatedStorage:WaitForChild(GameConfig.Network.RemotesFolderName)\n",
		"\n",
		"local function getRemoteEvent(remoteName: string): RemoteEvent\n",
		"\tlocal instance = remotesFolder:WaitForChild(remoteName, REMOTE_WAIT_TIMEOUT)\n",
		"\tif instance and instance:IsA(\"RemoteEvent\") then\n",
		"\t\treturn instance\n",
		"\tend\n",
		"\terror(`[PlayerSessionService] Missing RemoteEvent ReplicatedStorage.{GameConfig.Network.RemotesFolderName}.{remoteName}`)\n",
		"end\n",
		"\n",
		"local clientReadyRemote = getRemoteEvent(GameConfig.Network.ClientReady)\n",
		"\n",
		"local sessions: { [Player]: Session } = {}\n",
		"local started = false\n",
		"\n",
		"local PlayerSessionService = {}\n",
		"\n",
		"-- Economy first and combat last: the combat sync is what lets the client start tapping.\n",
		"local function syncPlayer(player: Player)\n",
		"\tCurrencyService.SyncPlayer(player)\n",
		"\tUpgradeService.SyncPlayer(player)\n",
		"\tCombatService.SyncPlayer(player)\n",
		"end\n",
		"\n",
		"-- The player's current profile, read from the services in one step (no yields), so Gold,\n",
		"-- stage and levels are always saved as one consistent set. nil if any service lacks the player.\n",
		"local function buildProfile(player: Player): Profile?\n",
		"\tlocal session = sessions[player]\n",
		"\tif session == nil or not session.ready then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal profile = PlayerDataService.CopyMetadata(player)\n",
		"\tif profile == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tfor _, currency in ProgressionConfig.Currencies do\n",
		"\t\tlocal balance = CurrencyService.GetBalance(player, currency.id)\n",
		"\t\tif balance == nil then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\tprofile.currencies[currency.id] = balance\n",
		"\tend\n",
		"\tlocal stage = CombatService.GetStage(player)\n",
		"\tif stage == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tprofile.stage = stage\n",
		"\tlocal runHighest, lifetimeHighest = CombatService.GetHighestStages(player)\n",
		"\tif runHighest == nil or lifetimeHighest == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tprofile.runHighestStage = runHighest\n",
		"\tprofile.lifetimeHighestStage = lifetimeHighest\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tlocal level = UpgradeService.GetLevel(player, definition.id)\n",
		"\t\tif level == nil then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\tprofile.upgrades[definition.id] = level\n",
		"\tend\n",
		"\treturn profile\n",
		"end\n",
		"\n",
		"local function removePlayer(player: Player)\n",
		"\tlocal session = sessions[player]\n",
		"\tif session == nil then\n",
		"\t\treturn\n",
		"\tend\n",
		"\t-- Read the final state before the services forget the player. A load still in flight\n",
		"\t-- releases its own lock when it finishes (see addPlayer).\n",
		"\tPlayerDataService.Release(player, buildProfile(player))\n",
		"\tsessions[player] = nil\n",
		"\tUpgradeService.RemovePlayer(player)\n",
		"\tStatService.RemovePlayer(player)\n",
		"\tCombatService.RemovePlayer(player)\n",
		"\tCurrencyService.RemovePlayer(player)\n",
		"end\n",
		"\n",
		"local function addPlayer(player: Player)\n",
		"\tif sessions[player] or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal session: Session = {\n",
		"\t\tready = false,\n",
		"\t\tfailed = false,\n",
		"\t\tsyncRequested = false,\n",
		"\t\tlastSyncAt = -math.huge,\n",
		"\t}\n",
		"\tsessions[player] = session\n",
		"\n",
		"\tlocal profile, message = PlayerDataService.Load(player, function(): boolean\n",
		"\t\treturn sessions[player] == session and player.Parent == Players\n",
		"\tend)\n",
		"\tif sessions[player] ~= session or player.Parent ~= Players then\n",
		"\t\tPlayerDataService.Release(player, nil) -- left while loading: unlock, keep the stored profile\n",
		"\t\tif sessions[player] == session then\n",
		"\t\t\tsessions[player] = nil\n",
		"\t\tend\n",
		"\t\treturn\n",
		"\tend\n",
		"\tif profile == nil then\n",
		"\t\tsession.failed = true\n",
		"\t\tplayer:Kick(message)\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal loaded = profile :: Profile\n",
		"\n",
		"\tlocal success, problem = pcall(function()\n",
		"\t\tCurrencyService.AddPlayer(player, loaded.currencies)\n",
		"\t\tCombatService.AddPlayer(player, loaded.stage, loaded.runHighestStage, loaded.lifetimeHighestStage)\n",
		"\t\tStatService.AddPlayer(player) -- needs CombatService; UpgradeService then reports the base tap damage\n",
		"\t\tUpgradeService.AddPlayer(player, loaded.upgrades)\n",
		"\tend)\n",
		"\tif not success then\n",
		"\t\twarn(`[PlayerSessionService] Could not start a session for {player.Name}: {problem}`)\n",
		"\t\tremovePlayer(player) -- not ready, so the stored profile is kept; the client's ClientReady retry tries again\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tsession.ready = true\n",
		"\tif session.syncRequested then\n",
		"\t\tsession.syncRequested = false\n",
		"\t\tsession.lastSyncAt = os.clock()\n",
		"\t\tsyncPlayer(player)\n",
		"\tend\n",
		"end\n",
		"\n",
		"local function onClientReady(player: Player)\n",
		"\tif sessions[player] == nil then\n",
		"\t\taddPlayer(player) -- the handshake arrived before PlayerAdded was processed\n",
		"\tend\n",
		"\tlocal session = sessions[player]\n",
		"\tif session == nil or session.failed then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal now = os.clock()\n",
		"\tif now - session.lastSyncAt < GameConfig.Network.ClientReadyCooldown then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tif not session.ready then\n",
		"\t\tsession.syncRequested = true\n",
		"\t\treturn\n",
		"\tend\n",
		"\tsession.lastSyncAt = now\n",
		"\tsyncPlayer(player)\n",
		"end\n",
		"\n",
		"function PlayerSessionService.IsReady(player: Player): boolean\n",
		"\tlocal session = sessions[player]\n",
		"\treturn session ~= nil and session.ready\n",
		"end\n",
		"\n",
		"-- Connects the player lifecycle and the handshake, then adds players already in the game.\n",
		"function PlayerSessionService.Start()\n",
		"\tif started then\n",
		"\t\twarn(\"[PlayerSessionService] Start() was called more than once; ignoring.\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstarted = true\n",
		"\n",
		"\tPlayerDataService.Start(buildProfile)\n",
		"\tPlayers.PlayerAdded:Connect(addPlayer)\n",
		"\tPlayers.PlayerRemoving:Connect(removePlayer)\n",
		"\tclientReadyRemote.OnServerEvent:Connect(function(player: Player)\n",
		"\t\tonClientReady(player)\n",
		"\tend)\n",
		"\n",
		"\t-- addPlayer is idempotent, so a player caught by both PlayerAdded and this loop is handled once.\n",
		"\t-- Each load yields, so every player already in the game loads in parallel.\n",
		"\tfor _, player in Players:GetPlayers() do\n",
		"\t\ttask.spawn(addPlayer, player)\n",
		"\tend\n",
		"end\n",
		"\n",
		"return PlayerSessionService\n",
	},
}
FILES[9] = {
	path = "ServerScriptService/ProfileSchema",
	className = "ModuleScript",
	bytes = 12189,
	lines = 346,
	adler32 = 1031035281,
	sha256 = "762f6b7ab739c1ffdb6f98b7e0562e751ac399c710bdde912aa0613bbfcd9dbe",
	text = {
		"--!strict\n",
		"-- Versioned player data and validation. Currency/upgrade definitions remain the source of defaults.\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local Shared = ReplicatedStorage:WaitForChild(\"Shared\")\n",
		"local BigNum = require(Shared:WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(Shared:WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(Shared:WaitForChild(\"ProgressionConfig\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"export type Transaction = {\n",
		"\tid: number,\n",
		"\tkind: \"Grant\" | \"Spend\" | \"Upgrade\" | \"Prestige\",\n",
		"\tcurrencyId: string?,\n",
		"\tamount: string?,\n",
		"\tupgradeId: string?,\n",
		"\tfromLevel: number?,\n",
		"\ttoLevel: number?,\n",
		"\tclaimId: string?,\n",
		"\treason: string?,\n",
		"\trunId: number?,\n",
		"\trunHighestStage: number?,\n",
		"\tcalculatedGain: string?,\n",
		"\tgainCurveVersion: string?,\n",
		"}\n",
		"\n",
		"export type Prestige = {\n",
		"\tcount: number,\n",
		"\tmultiplier: BigNum,\n",
		"\trunId: number,\n",
		"}\n",
		"\n",
		"export type Profile = {\n",
		"\tcurrencies: { [string]: BigNum },\n",
		"\tstage: number,\n",
		"\tupgrades: { [string]: number },\n",
		"\tactiveSeconds: number,\n",
		"\tlifetimeHighestStage: number,\n",
		"\trunHighestStage: number,\n",
		"\tprestige: Prestige,\n",
		"\tclaimedMilestones: { [string]: boolean },\n",
		"\ttransactionId: number,\n",
		"\tpendingTransaction: Transaction?,\n",
		"\ttransactions: { Transaction },\n",
		"}\n",
		"\n",
		"export type Stored = {\n",
		"\tv: number,\n",
		"\tcurrencies: { [string]: string },\n",
		"\tstage: number,\n",
		"\tupgrades: { [string]: number },\n",
		"\tactiveSeconds: number,\n",
		"\tlifetimeHighestStage: number,\n",
		"\trunHighestStage: number,\n",
		"\tprestige: { count: number, multiplier: string, runId: number },\n",
		"\tclaimedMilestones: { [string]: boolean },\n",
		"\ttransactionId: number,\n",
		"\tpendingTransaction: Transaction?,\n",
		"\ttransactions: { Transaction },\n",
		"}\n",
		"\n",
		"local MAX_INTEGER = 9007199254740991\n",
		"local ProfileSchema = {}\n",
		"ProfileSchema.Version = 2\n",
		"ProfileSchema.MaxInteger = MAX_INTEGER\n",
		"ProfileSchema.HistoryLimit = 50\n",
		"\n",
		"local function isWholeNumber(value: unknown, minimum: number, maximum: number): boolean\n",
		"\treturn typeof(value) == \"number\" and value % 1 == 0 and value >= minimum and value <= maximum\n",
		"end\n",
		"\n",
		"local function isText(value: unknown, maximum: number): boolean\n",
		"\treturn typeof(value) == \"string\" and #value > 0 and #value <= maximum\n",
		"end\n",
		"\n",
		"local function copyTransactions(transactions: { Transaction }): { Transaction }\n",
		"\tlocal result: { Transaction } = {}\n",
		"\tfor _, transaction in transactions do\n",
		"\t\ttable.insert(result, table.clone(transaction))\n",
		"\tend\n",
		"\treturn result\n",
		"end\n",
		"\n",
		"function ProfileSchema.new(): Profile\n",
		"\tlocal currencies: { [string]: BigNum } = {}\n",
		"\tfor _, currency in ProgressionConfig.CurrencyDefinitions do\n",
		"\t\tcurrencies[currency.id] = BigNum.fromNumber(currency.startingBalance)\n",
		"\tend\n",
		"\tlocal upgrades: { [string]: number } = {}\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tupgrades[definition.id] = definition.startingLevel\n",
		"\tend\n",
		"\treturn {\n",
		"\t\tcurrencies = currencies,\n",
		"\t\tstage = GameConfig.Combat.StartingStage,\n",
		"\t\tupgrades = upgrades,\n",
		"\t\tactiveSeconds = 0,\n",
		"\t\tlifetimeHighestStage = 0,\n",
		"\t\trunHighestStage = 0,\n",
		"\t\tprestige = { count = 0, multiplier = BigNum.one, runId = 1 },\n",
		"\t\tclaimedMilestones = {},\n",
		"\t\ttransactionId = 0,\n",
		"\t\tpendingTransaction = nil,\n",
		"\t\ttransactions = {},\n",
		"\t}\n",
		"end\n",
		"\n",
		"-- BigNums are immutable. Copy every mutable container so a failed operation cannot leak changes.\n",
		"function ProfileSchema.copy(profile: Profile): Profile\n",
		"\treturn {\n",
		"\t\tcurrencies = table.clone(profile.currencies),\n",
		"\t\tstage = profile.stage,\n",
		"\t\tupgrades = table.clone(profile.upgrades),\n",
		"\t\tactiveSeconds = profile.activeSeconds,\n",
		"\t\tlifetimeHighestStage = profile.lifetimeHighestStage,\n",
		"\t\trunHighestStage = profile.runHighestStage,\n",
		"\t\tprestige = table.clone(profile.prestige),\n",
		"\t\tclaimedMilestones = table.clone(profile.claimedMilestones),\n",
		"\t\ttransactionId = profile.transactionId,\n",
		"\t\tpendingTransaction = if profile.pendingTransaction then table.clone(profile.pendingTransaction) else nil,\n",
		"\t\ttransactions = copyTransactions(profile.transactions),\n",
		"\t}\n",
		"end\n",
		"\n",
		"-- Validate journal payloads independently of current prices or the current prestige gain curve.\n",
		"function ProfileSchema.readTransaction(raw: unknown): (Transaction?, string?)\n",
		"\tif typeof(raw) ~= \"table\" then\n",
		"\t\treturn nil, \"the transaction is not a table\"\n",
		"\tend\n",
		"\tlocal fields = raw :: { [string]: any }\n",
		"\tif not isWholeNumber(fields.id, 1, MAX_INTEGER) then\n",
		"\t\treturn nil, \"the transaction id is invalid\"\n",
		"\tend\n",
		"\tlocal kind = fields.kind\n",
		"\tif kind ~= \"Grant\" and kind ~= \"Spend\" and kind ~= \"Upgrade\" and kind ~= \"Prestige\" then\n",
		"\t\treturn nil, \"the transaction kind is invalid\"\n",
		"\tend\n",
		"\tlocal transaction: Transaction = { id = fields.id, kind = kind }\n",
		"\tif fields.reason ~= nil then\n",
		"\t\tif not isText(fields.reason, 128) then\n",
		"\t\t\treturn nil, \"the transaction reason is invalid\"\n",
		"\t\tend\n",
		"\t\ttransaction.reason = fields.reason\n",
		"\tend\n",
		"\tif kind == \"Prestige\" then\n",
		"\t\tlocal gain = BigNum.parse(fields.calculatedGain)\n",
		"\t\tif gain == nil or BigNum.isZero(gain) or not isText(fields.gainCurveVersion, 64)\n",
		"\t\t\tor not isWholeNumber(fields.runId, 1, MAX_INTEGER)\n",
		"\t\t\tor not isWholeNumber(fields.runHighestStage, 0, MAX_INTEGER) then\n",
		"\t\t\treturn nil, \"the saved prestige reward is invalid\"\n",
		"\t\tend\n",
		"\t\ttransaction.calculatedGain = BigNum.toString(gain)\n",
		"\t\ttransaction.gainCurveVersion = fields.gainCurveVersion\n",
		"\t\ttransaction.runId = fields.runId\n",
		"\t\ttransaction.runHighestStage = fields.runHighestStage\n",
		"\t\treturn transaction, nil\n",
		"\tend\n",
		"\n",
		"\tlocal currencyId = fields.currencyId\n",
		"\tlocal amount = BigNum.parse(fields.amount)\n",
		"\tif typeof(currencyId) ~= \"string\" or ProgressionConfig.GetCurrency(currencyId) == nil\n",
		"\t\tor amount == nil or BigNum.isZero(amount) or not ProgressionConfig.IsCurrencyValue(currencyId, amount) then\n",
		"\t\treturn nil, \"the saved currency operation is invalid\"\n",
		"\tend\n",
		"\ttransaction.currencyId = currencyId\n",
		"\ttransaction.amount = BigNum.toString(amount)\n",
		"\tif kind == \"Upgrade\" then\n",
		"\t\tlocal definition = if typeof(fields.upgradeId) == \"string\" then ProgressionConfig.GetUpgrade(fields.upgradeId) else nil\n",
		"\t\tif definition == nil or definition.currencyId ~= currencyId\n",
		"\t\t\tor not isWholeNumber(fields.fromLevel, definition.startingLevel, definition.maxLevel - 1)\n",
		"\t\t\tor fields.toLevel ~= fields.fromLevel + 1 then\n",
		"\t\t\treturn nil, \"the saved upgrade operation is invalid\"\n",
		"\t\tend\n",
		"\t\ttransaction.upgradeId = fields.upgradeId\n",
		"\t\ttransaction.fromLevel = fields.fromLevel\n",
		"\t\ttransaction.toLevel = fields.toLevel\n",
		"\tend\n",
		"\tif fields.claimId ~= nil then\n",
		"\t\tif kind ~= \"Grant\" or not isText(fields.claimId, 128) then\n",
		"\t\t\treturn nil, \"the milestone claim id is invalid\"\n",
		"\t\tend\n",
		"\t\ttransaction.claimId = fields.claimId\n",
		"\tend\n",
		"\treturn transaction, nil\n",
		"end\n",
		"\n",
		"function ProfileSchema.encode(profile: Profile): Stored\n",
		"\tlocal currencies: { [string]: string } = {}\n",
		"\tfor currencyId, balance in profile.currencies do\n",
		"\t\tcurrencies[currencyId] = BigNum.toString(balance)\n",
		"\tend\n",
		"\treturn {\n",
		"\t\tv = ProfileSchema.Version,\n",
		"\t\tcurrencies = currencies,\n",
		"\t\tstage = profile.stage,\n",
		"\t\tupgrades = table.clone(profile.upgrades),\n",
		"\t\tactiveSeconds = profile.activeSeconds,\n",
		"\t\tlifetimeHighestStage = profile.lifetimeHighestStage,\n",
		"\t\trunHighestStage = profile.runHighestStage,\n",
		"\t\tprestige = {\n",
		"\t\t\tcount = profile.prestige.count,\n",
		"\t\t\tmultiplier = BigNum.toString(profile.prestige.multiplier),\n",
		"\t\t\trunId = profile.prestige.runId,\n",
		"\t\t},\n",
		"\t\tclaimedMilestones = table.clone(profile.claimedMilestones),\n",
		"\t\ttransactionId = profile.transactionId,\n",
		"\t\tpendingTransaction = if profile.pendingTransaction then table.clone(profile.pendingTransaction) else nil,\n",
		"\t\ttransactions = copyTransactions(profile.transactions),\n",
		"\t}\n",
		"end\n",
		"\n",
		"function ProfileSchema.decode(raw: unknown): (Profile?, string?)\n",
		"\tif typeof(raw) ~= \"table\" then\n",
		"\t\treturn nil, \"the profile is not a table\"\n",
		"\tend\n",
		"\tlocal record = raw :: { [string]: any }\n",
		"\tif not isWholeNumber(record.v, 1, MAX_INTEGER) then\n",
		"\t\treturn nil, \"the profile version is missing or invalid\"\n",
		"\tend\n",
		"\tif record.v > ProfileSchema.Version then\n",
		"\t\treturn nil, \"the profile version is newer than this server\"\n",
		"\tend\n",
		"\n",
		"\tlocal profile = ProfileSchema.new()\n",
		"\tif typeof(record.currencies) ~= \"table\" then\n",
		"\t\treturn nil, \"currencies is not a table\"\n",
		"\tend\n",
		"\tfor _, currency in ProgressionConfig.CurrencyDefinitions do\n",
		"\t\tlocal text = record.currencies[currency.id]\n",
		"\t\tif text == nil and record.v == ProfileSchema.Version then\n",
		"\t\t\treturn nil, \"the \" .. currency.id .. \" balance is missing\"\n",
		"\t\tend\n",
		"\t\tif text ~= nil then\n",
		"\t\t\tlocal balance = BigNum.parse(text)\n",
		"\t\t\tif balance == nil or not ProgressionConfig.IsCurrencyValue(currency.id, balance) then\n",
		"\t\t\t\treturn nil, \"the \" .. currency.id .. \" balance is invalid\"\n",
		"\t\t\tend\n",
		"\t\t\tprofile.currencies[currency.id] = balance\n",
		"\t\tend\n",
		"\tend\n",
		"\tif not isWholeNumber(record.stage, GameConfig.Combat.StartingStage, MAX_INTEGER) then\n",
		"\t\treturn nil, \"the stage is invalid\"\n",
		"\tend\n",
		"\tprofile.stage = record.stage\n",
		"\n",
		"\tif typeof(record.upgrades) ~= \"table\" then\n",
		"\t\treturn nil, \"upgrades is not a table\"\n",
		"\tend\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tlocal level = record.upgrades[definition.id]\n",
		"\t\tif level == nil and record.v == ProfileSchema.Version then\n",
		"\t\t\treturn nil, \"the \" .. definition.id .. \" level is missing\"\n",
		"\t\tend\n",
		"\t\tif level ~= nil then\n",
		"\t\t\tif not isWholeNumber(level, definition.startingLevel, definition.maxLevel) then\n",
		"\t\t\t\treturn nil, \"the \" .. definition.id .. \" level is invalid\"\n",
		"\t\t\tend\n",
		"\t\t\tprofile.upgrades[definition.id] = level\n",
		"\t\tend\n",
		"\tend\n",
		"\tif record.activeSeconds == nil and record.v == ProfileSchema.Version then\n",
		"\t\treturn nil, \"activeSeconds is missing\"\n",
		"\tend\n",
		"\tif record.activeSeconds ~= nil then\n",
		"\t\tlocal seconds = record.activeSeconds\n",
		"\t\tif typeof(seconds) ~= \"number\" or seconds ~= seconds or seconds < 0 or seconds > MAX_INTEGER then\n",
		"\t\t\treturn nil, \"activeSeconds is invalid\"\n",
		"\t\tend\n",
		"\t\tprofile.activeSeconds = seconds\n",
		"\tend\n",
		"\n",
		"\t-- V1 had sequential stages and no prestige. Upgrade its history conservatively.\n",
		"\tif record.v == 1 then\n",
		"\t\tprofile.runHighestStage = math.max(0, profile.stage - 1)\n",
		"\t\tprofile.lifetimeHighestStage = profile.runHighestStage\n",
		"\t\treturn profile, nil\n",
		"\tend\n",
		"\n",
		"\tif not isWholeNumber(record.runHighestStage, profile.stage - 1, MAX_INTEGER)\n",
		"\t\tor not isWholeNumber(record.lifetimeHighestStage, record.runHighestStage, MAX_INTEGER) then\n",
		"\t\treturn nil, \"the highest-cleared stage records are invalid\"\n",
		"\tend\n",
		"\tprofile.runHighestStage = record.runHighestStage\n",
		"\tprofile.lifetimeHighestStage = record.lifetimeHighestStage\n",
		"\n",
		"\tlocal prestige = record.prestige\n",
		"\tif typeof(prestige) ~= \"table\" or not isWholeNumber(prestige.count, 0, MAX_INTEGER)\n",
		"\t\tor not isWholeNumber(prestige.runId, 1, MAX_INTEGER) then\n",
		"\t\treturn nil, \"the prestige record is invalid\"\n",
		"\tend\n",
		"\tlocal multiplier = BigNum.parse(prestige.multiplier)\n",
		"\tif multiplier == nil or BigNum.lt(multiplier, BigNum.one) then\n",
		"\t\treturn nil, \"the prestige multiplier is invalid\"\n",
		"\tend\n",
		"\tprofile.prestige = { count = prestige.count, multiplier = multiplier, runId = prestige.runId }\n",
		"\n",
		"\tif typeof(record.claimedMilestones) ~= \"table\" then\n",
		"\t\treturn nil, \"the milestone claim records are invalid\"\n",
		"\tend\n",
		"\tfor claimId, claimed in record.claimedMilestones do\n",
		"\t\tif not isText(claimId, 128) or claimed ~= true then\n",
		"\t\t\treturn nil, \"the milestone claim records are invalid\"\n",
		"\t\tend\n",
		"\t\tprofile.claimedMilestones[claimId] = true\n",
		"\tend\n",
		"\tif not isWholeNumber(record.transactionId, 0, MAX_INTEGER) or typeof(record.transactions) ~= \"table\" then\n",
		"\t\treturn nil, \"the transaction history is invalid\"\n",
		"\tend\n",
		"\tprofile.transactionId = record.transactionId\n",
		"\tlocal history = record.transactions\n",
		"\tlocal count = 0\n",
		"\tfor index in history do\n",
		"\t\tif not isWholeNumber(index, 1, ProfileSchema.HistoryLimit) then\n",
		"\t\t\treturn nil, \"the transaction history is invalid\"\n",
		"\t\tend\n",
		"\t\tcount += 1\n",
		"\tend\n",
		"\tif count ~= #history then\n",
		"\t\treturn nil, \"the transaction history is not a sequence\"\n",
		"\tend\n",
		"\tlocal lastId = 0\n",
		"\tfor _, rawTransaction in history do\n",
		"\t\tlocal transaction, reason = ProfileSchema.readTransaction(rawTransaction)\n",
		"\t\tif transaction == nil then\n",
		"\t\t\treturn nil, reason\n",
		"\t\tend\n",
		"\t\tif transaction.id <= lastId or transaction.id > profile.transactionId then\n",
		"\t\t\treturn nil, \"the transaction history is out of order\"\n",
		"\t\tend\n",
		"\t\tlastId = transaction.id\n",
		"\t\ttable.insert(profile.transactions, transaction)\n",
		"\tend\n",
		"\tif record.pendingTransaction ~= nil then\n",
		"\t\tlocal transaction, reason = ProfileSchema.readTransaction(record.pendingTransaction)\n",
		"\t\tif transaction == nil then\n",
		"\t\t\treturn nil, reason\n",
		"\t\tend\n",
		"\t\tif transaction.id > profile.transactionId + 1 then\n",
		"\t\t\treturn nil, \"the pending transaction skips an operation id\"\n",
		"\t\tend\n",
		"\t\tprofile.pendingTransaction = transaction\n",
		"\tend\n",
		"\treturn profile, nil\n",
		"end\n",
		"\n",
		"return ProfileSchema\n",
	},
}
FILES[10] = {
	path = "ServerScriptService/ProfileStore",
	className = "ModuleScript",
	bytes = 6800,
	lines = 194,
	adler32 = 286192177,
	sha256 = "d411b207b6ead1774814e2f657c0433348051a203f06cdcd4b420388b4e9d186",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tProfileStore\n",
		"\tLocation: ServerScriptService > ProfileStore (ModuleScript)\n",
		"\n",
		"\tSession-locked load and save of one profile record per player. It runs on any\n",
		"\tstore with UpdateAsync-style semantics, where a transform returning nil cancels\n",
		"\tthe write. PlayerDataService passes in a DataStore, or an in-memory store for\n",
		"\tunpublished Studio places. No Roblox services are used here: the store, clock,\n",
		"\twait and ids are passed in, so the rules are unit-tested offline.\n",
		"\n",
		"\tRecord: { profile = ProfileSchema.Stored, lock = { session, job, at }? }\n",
		"\t  load    claims the lock unless another live session holds it. A lock is live\n",
		"\t          until LockTimeout seconds after its last save, so a crashed server's\n",
		"\t          lock expires. A record that fails ProfileSchema.decode is neither\n",
		"\t          claimed nor overwritten.\n",
		"\t  save    writes only while this session still holds the lock (\"LockLost\"\n",
		"\t          otherwise, and nothing is written); release also clears the lock.\n",
		"\tStore errors are retried with doubling waits. Every session keeps its own lock,\n",
		"\tincluding when a later session joins the same server.\n",
		"]]\n",
		"\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local ProfileTransactions = require(ServerScriptService:WaitForChild(\"ProfileTransactions\"))\n",
		"\n",
		"type Profile = ProfileSchema.Profile\n",
		"\n",
		"-- update(key, transform, userId) runs transform(oldValue) and writes its result unless it is nil.\n",
		"export type Store = {\n",
		"\tupdate: (key: string, transform: (unknown) -> unknown?, userId: number) -> (),\n",
		"}\n",
		"\n",
		"export type Options = {\n",
		"\tstore: Store,\n",
		"\tjob: string, -- game.JobId (\"\" in Studio, where it is never used to claim a lock)\n",
		"\tnow: () -> number, -- seconds, comparable across servers (os.time)\n",
		"\twait: (seconds: number) -> (),\n",
		"\tlockTimeout: number,\n",
		"\tattempts: number, -- store calls per operation before giving up\n",
		"\tlockedRetries: number, -- extra load rounds while another server still holds the lock\n",
		"\tlockedRetryDelay: number,\n",
		"}\n",
		"\n",
		"export type LoadStatus = \"Loaded\" | \"Locked\" | \"Invalid\" | \"Error\" | \"Cancelled\"\n",
		"export type SaveStatus = \"Saved\" | \"LockLost\" | \"Error\"\n",
		"\n",
		"export type LoadResult = {\n",
		"\tstatus: LoadStatus,\n",
		"\tprofile: Profile?,\n",
		"\tdetail: string?,\n",
		"}\n",
		"\n",
		"local ProfileStore = {}\n",
		"\n",
		"local function lockFor(options: Options, session: string): { [string]: unknown }\n",
		"\treturn { session = session, job = options.job, at = options.now() }\n",
		"end\n",
		"\n",
		"local function canClaim(options: Options, lock: unknown, session: string): boolean\n",
		"\tif typeof(lock) ~= \"table\" then\n",
		"\t\treturn true -- no lock (or an unreadable one): the profile itself is still validated\n",
		"\tend\n",
		"\tlocal fields = lock :: { [string]: unknown }\n",
		"\tif fields.session == session then\n",
		"\t\treturn true\n",
		"\tend\n",
		"\tlocal at = fields.at\n",
		"\tif typeof(at) ~= \"number\" then\n",
		"\t\treturn true\n",
		"\tend\n",
		"\treturn options.now() - (at :: number) >= options.lockTimeout\n",
		"end\n",
		"\n",
		"-- Runs one update with retries. Returns false and the last error if every attempt failed.\n",
		"local function update(options: Options, key: string, userId: number, transform: (unknown) -> unknown?): (boolean, string?)\n",
		"\tlocal delay = 1\n",
		"\tlocal lastProblem: string? = nil\n",
		"\tfor attempt = 1, options.attempts do\n",
		"\t\tlocal ok, problem = pcall(options.store.update, key, transform, userId)\n",
		"\t\tif ok then\n",
		"\t\t\treturn true, nil\n",
		"\t\tend\n",
		"\t\tlastProblem = tostring(problem)\n",
		"\t\tif attempt < options.attempts then\n",
		"\t\t\toptions.wait(delay)\n",
		"\t\t\tdelay *= 2\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn false, lastProblem\n",
		"end\n",
		"\n",
		"function ProfileStore.keyFor(userId: number): string\n",
		"\treturn `player_{userId}`\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tLoads and claims a player's profile. A missing record becomes a new profile.\n",
		"\tisWanted() is checked between rounds; when it returns false the load stops\n",
		"\t(\"Cancelled\") without claiming anything new.\n",
		"]]\n",
		"function ProfileStore.load(options: Options, userId: number, session: string, isWanted: () -> boolean): LoadResult\n",
		"\tlocal key = ProfileStore.keyFor(userId)\n",
		"\tfor round = 1, options.lockedRetries + 1 do\n",
		"\t\tif not isWanted() then\n",
		"\t\t\treturn { status = \"Cancelled\" }\n",
		"\t\tend\n",
		"\t\tlocal status: LoadStatus = \"Error\"\n",
		"\t\tlocal profile: Profile? = nil\n",
		"\t\tlocal detail: string? = nil\n",
		"\t\tlocal ok, problem = update(options, key, userId, function(old: unknown): unknown?\n",
		"\t\t\tprofile, detail = nil, nil -- the transform can run more than once\n",
		"\t\t\tif old == nil then\n",
		"\t\t\t\tlocal fresh = ProfileSchema.new()\n",
		"\t\t\t\tstatus, profile = \"Loaded\", fresh\n",
		"\t\t\t\treturn { profile = ProfileSchema.encode(fresh), lock = lockFor(options, session) }\n",
		"\t\t\tend\n",
		"\t\t\tif typeof(old) ~= \"table\" then\n",
		"\t\t\t\tstatus, detail = \"Invalid\", \"the record is not a table\"\n",
		"\t\t\t\treturn nil\n",
		"\t\t\tend\n",
		"\t\t\tlocal record = old :: { [string]: unknown }\n",
		"\t\t\tif not canClaim(options, record.lock, session) then\n",
		"\t\t\t\tstatus = \"Locked\"\n",
		"\t\t\t\treturn nil\n",
		"\t\t\tend\n",
		"\t\t\tlocal decoded, reason = ProfileSchema.decode(record.profile)\n",
		"\t\t\tif decoded == nil then\n",
		"\t\t\t\tstatus, detail = \"Invalid\", reason\n",
		"\t\t\t\treturn nil\n",
		"\t\t\tend\n",
		"\t\t\tlocal recovered, recoveryProblem = ProfileTransactions.recover(decoded)\n",
		"\t\t\tif recovered == nil then\n",
		"\t\t\t\tstatus, detail = \"Invalid\", recoveryProblem\n",
		"\t\t\t\treturn nil\n",
		"\t\t\tend\n",
		"\t\t\tstatus, profile = \"Loaded\", recovered\n",
		"\t\t\trecord.profile = ProfileSchema.encode(recovered)\n",
		"\t\t\trecord.lock = lockFor(options, session)\n",
		"\t\t\treturn record\n",
		"\t\tend)\n",
		"\t\tif not ok then\n",
		"\t\t\treturn { status = \"Error\", detail = problem }\n",
		"\t\tend\n",
		"\t\tif status ~= \"Locked\" then\n",
		"\t\t\treturn { status = status, profile = profile, detail = detail }\n",
		"\t\tend\n",
		"\t\tif round <= options.lockedRetries then\n",
		"\t\t\toptions.wait(options.lockedRetryDelay)\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn { status = \"Locked\", detail = \"another server still holds this profile\" }\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tSaves the profile while this session holds the lock. release = true also clears the\n",
		"\tlock. profile = nil keeps the stored profile as it is (used to release a session\n",
		"\twhose state could not be read).\n",
		"]]\n",
		"function ProfileStore.save(options: Options, userId: number, session: string, profile: Profile?, release: boolean): (SaveStatus, string?)\n",
		"\tlocal encoded = if profile then ProfileSchema.encode(profile) else nil\n",
		"\tif encoded ~= nil then\n",
		"\t\tlocal validated, reason = ProfileSchema.decode(encoded)\n",
		"\t\tif validated == nil then\n",
		"\t\t\treturn \"Error\", reason\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal status: SaveStatus = \"Error\"\n",
		"\tlocal ok, problem = update(options, ProfileStore.keyFor(userId), userId, function(old: unknown): unknown?\n",
		"\t\tif typeof(old) ~= \"table\" then\n",
		"\t\t\tstatus = \"LockLost\"\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\tlocal record = old :: { [string]: unknown }\n",
		"\t\tlocal lock = record.lock\n",
		"\t\tif typeof(lock) ~= \"table\" or (lock :: { [string]: unknown }).session ~= session then\n",
		"\t\t\tstatus = \"LockLost\"\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\t\tif encoded ~= nil then\n",
		"\t\t\trecord.profile = encoded\n",
		"\t\tend\n",
		"\t\trecord.lock = if release then nil else lockFor(options, session)\n",
		"\t\tstatus = \"Saved\"\n",
		"\t\treturn record\n",
		"\tend)\n",
		"\tif not ok then\n",
		"\t\treturn \"Error\", problem\n",
		"\tend\n",
		"\treturn status, nil\n",
		"end\n",
		"\n",
		"return ProfileStore\n",
	},
}
FILES[11] = {
	path = "ServerScriptService/ProfileTransactions",
	className = "ModuleScript",
	bytes = 4689,
	lines = 117,
	adler32 = 3421469007,
	sha256 = "406e891cd5c5beea1daab04865d42bddc00a7a648134ca6c8cb784da40ea7f9a",
	text = {
		"--!strict\n",
		"-- Pure journal operations. A caller persists prepare() before acknowledging a durable operation.\n",
		"-- ProfileStore.load completes a saved pending operation while claiming the session lock.\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"local Shared = ReplicatedStorage:WaitForChild(\"Shared\")\n",
		"local BigNum = require(Shared:WaitForChild(\"BigNum\"))\n",
		"local ProgressionConfig = require(Shared:WaitForChild(\"ProgressionConfig\"))\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local Wallet = require(ServerScriptService:WaitForChild(\"Wallet\"))\n",
		"\n",
		"type Profile = ProfileSchema.Profile\n",
		"type Transaction = ProfileSchema.Transaction\n",
		"\n",
		"local ProfileTransactions = {}\n",
		"\n",
		"local function apply(profile: Profile, transaction: Transaction): (boolean, string?)\n",
		"\tif transaction.kind == \"Prestige\" then\n",
		"\t\tif transaction.runId ~= profile.prestige.runId or transaction.runHighestStage ~= profile.runHighestStage then\n",
		"\t\t\treturn false, \"the prestige operation belongs to a different run\"\n",
		"\t\tend\n",
		"\t\tif profile.prestige.count >= ProfileSchema.MaxInteger or profile.prestige.runId >= ProfileSchema.MaxInteger then\n",
		"\t\t\treturn false, \"the prestige counter is full\"\n",
		"\t\tend\n",
		"\t\t-- The gain was calculated before preparation. Recovery never consults a gain curve.\n",
		"\t\tlocal gain = BigNum.parse(transaction.calculatedGain) :: BigNum.BigNum\n",
		"\t\tprofile.prestige.multiplier = BigNum.add(profile.prestige.multiplier, gain)\n",
		"\t\tprofile.prestige.count += 1\n",
		"\t\tprofile.prestige.runId += 1\n",
		"\t\tprofile.stage = 1\n",
		"\t\tprofile.runHighestStage = 0\n",
		"\t\tprofile.currencies[ProgressionConfig.GoldCurrencyId] = BigNum.zero\n",
		"\t\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\t\tprofile.upgrades[definition.id] = definition.startingLevel\n",
		"\t\tend\n",
		"\t\treturn true, nil\n",
		"\tend\n",
		"\n",
		"\tlocal currencyId = transaction.currencyId :: string\n",
		"\tlocal amount = BigNum.parse(transaction.amount) :: BigNum.BigNum\n",
		"\tif transaction.claimId ~= nil and profile.claimedMilestones[transaction.claimId] then\n",
		"\t\treturn false, \"the milestone reward was already claimed\"\n",
		"\tend\n",
		"\tif transaction.kind == \"Upgrade\" and profile.upgrades[transaction.upgradeId :: string] ~= transaction.fromLevel then\n",
		"\t\treturn false, \"the upgrade operation has an unexpected starting level\"\n",
		"\tend\n",
		"\tlocal wallet = Wallet.new(profile.currencies)\n",
		"\tlocal changed = if transaction.kind == \"Grant\" then Wallet.grant(wallet, currencyId, amount) else Wallet.trySpend(wallet, currencyId, amount)\n",
		"\tif not changed then\n",
		"\t\treturn false, \"the currency operation cannot be applied\"\n",
		"\tend\n",
		"\tprofile.currencies = wallet.balances\n",
		"\tif transaction.kind == \"Upgrade\" then\n",
		"\t\tprofile.upgrades[transaction.upgradeId :: string] = transaction.toLevel :: number\n",
		"\tend\n",
		"\tif transaction.claimId ~= nil then\n",
		"\t\tprofile.claimedMilestones[transaction.claimId] = true\n",
		"\tend\n",
		"\treturn true, nil\n",
		"end\n",
		"\n",
		"function ProfileTransactions.recover(profile: Profile): (Profile?, string?)\n",
		"\tlocal result = ProfileSchema.copy(profile)\n",
		"\tlocal pending = result.pendingTransaction\n",
		"\tif pending == nil then\n",
		"\t\treturn result, nil\n",
		"\tend\n",
		"\tlocal transaction, reason = ProfileSchema.readTransaction(pending)\n",
		"\tif transaction == nil then\n",
		"\t\treturn nil, reason\n",
		"\tend\n",
		"\tif transaction.id <= result.transactionId then\n",
		"\t\tresult.pendingTransaction = nil\n",
		"\t\treturn result, nil\n",
		"\tend\n",
		"\tif transaction.id ~= result.transactionId + 1 then\n",
		"\t\treturn nil, \"the operation id is out of sequence\"\n",
		"\tend\n",
		"\tlocal ok, applied, problem = pcall(apply, result, transaction)\n",
		"\tif not ok then\n",
		"\t\treturn nil, tostring(applied)\n",
		"\tend\n",
		"\tif not applied then\n",
		"\t\treturn nil, problem\n",
		"\tend\n",
		"\tresult.transactionId = transaction.id\n",
		"\tresult.pendingTransaction = nil\n",
		"\ttable.insert(result.transactions, transaction)\n",
		"\tif #result.transactions > ProfileSchema.HistoryLimit then\n",
		"\t\ttable.remove(result.transactions, 1)\n",
		"\tend\n",
		"\treturn result, nil\n",
		"end\n",
		"\n",
		"-- The returned profile contains the original balances and a validated pending operation.\n",
		"-- Persist this profile before applying/recovering it. Operation ids increase within the saved profile.\n",
		"function ProfileTransactions.prepare(profile: Profile, raw: unknown): (Profile?, string?)\n",
		"\tif profile.pendingTransaction ~= nil then\n",
		"\t\treturn nil, \"a transaction is already pending\"\n",
		"\tend\n",
		"\tlocal transaction, reason = ProfileSchema.readTransaction(raw)\n",
		"\tif transaction == nil then\n",
		"\t\treturn nil, reason\n",
		"\tend\n",
		"\tif transaction.id <= profile.transactionId then\n",
		"\t\treturn nil, \"the operation was already applied\"\n",
		"\tend\n",
		"\tlocal prepared = ProfileSchema.copy(profile)\n",
		"\tprepared.pendingTransaction = transaction\n",
		"\tlocal checked, problem = ProfileTransactions.recover(prepared)\n",
		"\tif checked == nil then\n",
		"\t\treturn nil, problem\n",
		"\tend\n",
		"\treturn prepared, nil\n",
		"end\n",
		"\n",
		"return table.freeze(ProfileTransactions)\n",
	},
}
FILES[12] = {
	path = "ServerScriptService/RateLimiter",
	className = "ModuleScript",
	bytes = 1886,
	lines = 66,
	adler32 = 2585428194,
	sha256 = "493d3758fd52adb6cca7a9bbb6e61831219fce75c4c9ee45e3ce1d3cf2a3e296",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tRateLimiter\n",
		"\tLocation: ServerScriptService > RateLimiter (ModuleScript)\n",
		"\n",
		"\tToken bucket per key (usually a Player): a key may make `capacity` requests\n",
		"\tback to back, then `refillPerSecond` requests per second. Tokens refill\n",
		"\tlazily when a request arrives, so there are no loops or timers. The clock\n",
		"\tcan be injected so tests are deterministic. Reusable by future remotes\n",
		"\t(summons, hero actions).\n",
		"]]\n",
		"\n",
		"type Bucket = {\n",
		"\ttokens: number,\n",
		"\tupdatedAt: number,\n",
		"}\n",
		"\n",
		"local RateLimiter = {}\n",
		"RateLimiter.__index = RateLimiter\n",
		"\n",
		"export type RateLimiter = typeof(setmetatable(\n",
		"\t{} :: {\n",
		"\t\tcapacity: number,\n",
		"\t\trefillPerSecond: number,\n",
		"\t\tclock: () -> number,\n",
		"\t\tbuckets: { [any]: Bucket },\n",
		"\t},\n",
		"\tRateLimiter\n",
		"))\n",
		"\n",
		"function RateLimiter.new(capacity: number, refillPerSecond: number, clock: (() -> number)?): RateLimiter\n",
		"\tassert(capacity >= 1, \"RateLimiter: capacity must be >= 1\")\n",
		"\tassert(refillPerSecond > 0, \"RateLimiter: refillPerSecond must be > 0\")\n",
		"\treturn setmetatable({\n",
		"\t\tcapacity = capacity,\n",
		"\t\trefillPerSecond = refillPerSecond,\n",
		"\t\tclock = clock or os.clock,\n",
		"\t\tbuckets = {},\n",
		"\t}, RateLimiter)\n",
		"end\n",
		"\n",
		"-- Consumes one token for this key. Returns false (consuming nothing) when the key is over its limit.\n",
		"function RateLimiter.allow(self: RateLimiter, key: any): boolean\n",
		"\tlocal now = self.clock()\n",
		"\tlocal bucket = self.buckets[key]\n",
		"\tif bucket == nil then\n",
		"\t\tbucket = { tokens = self.capacity, updatedAt = now }\n",
		"\t\tself.buckets[key] = bucket\n",
		"\telse\n",
		"\t\tlocal elapsed = math.max(now - bucket.updatedAt, 0)\n",
		"\t\tbucket.tokens = math.min(self.capacity, bucket.tokens + elapsed * self.refillPerSecond)\n",
		"\t\tbucket.updatedAt = now\n",
		"\tend\n",
		"\tif bucket.tokens < 1 then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tbucket.tokens -= 1\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Forgets a key (call when a player leaves) so the table never grows without bound.\n",
		"function RateLimiter.remove(self: RateLimiter, key: any)\n",
		"\tself.buckets[key] = nil\n",
		"end\n",
		"\n",
		"return RateLimiter\n",
	},
}
FILES[13] = {
	path = "ServerScriptService/ServerInit",
	className = "Script",
	bytes = 1105,
	lines = 27,
	adler32 = 852134481,
	sha256 = "cdc062557c5b3e3a796058c343b5622c8974dfb3727323809aafbf88156b7f98",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tServerInit\n",
		"\tLocation: ServerScriptService > ServerInit (Script)\n",
		"\n",
		"\tServer entry point. Starts the services' remote handlers, then the player\n",
		"\tlifecycle. PlayerSessionService picks up players who joined before this\n",
		"\tscript ran, so startup order never matters.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local CombatService = require(ServerScriptService:WaitForChild(\"CombatService\"))\n",
		"local UpgradeService = require(ServerScriptService:WaitForChild(\"UpgradeService\"))\n",
		"local PlayerSessionService = require(ServerScriptService:WaitForChild(\"PlayerSessionService\"))\n",
		"\n",
		"-- The prototype has no avatar. This is also set in Studio; the runtime check is a safety net.\n",
		"if Players.CharacterAutoLoads then\n",
		"\twarn(\"[ServerInit] Players.CharacterAutoLoads should be false (see setup guide). Disabling it at runtime.\")\n",
		"\tPlayers.CharacterAutoLoads = false\n",
		"end\n",
		"\n",
		"-- Remote handlers first, then the lifecycle (which may immediately add players already in the game).\n",
		"CombatService.Start()\n",
		"UpgradeService.Start()\n",
		"PlayerSessionService.Start()\n",
	},
}
FILES[14] = {
	path = "ServerScriptService/StatRules",
	className = "ModuleScript",
	bytes = 7759,
	lines = 235,
	adler32 = 3881779502,
	sha256 = "a4fe30899a540046945d4e10214cee0efdb7a5283820cbc57131127183268947",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tStatRules\n",
		"\tLocation: ServerScriptService > StatRules (ModuleScript)\n",
		"\n",
		"\tPure stat math for StatService (Milestone 2.1, DECISIONS.md decision 1). No Roblox\n",
		"\tservices, no networking and no yields, so it is unit-tested directly (StatRulesTests).\n",
		"\n",
		"\tA sheet holds one player's base stats and the modifiers on top of them, grouped by\n",
		"\tsource (\"upgrade\", \"hero\", \"equipment\", \"perk\") and keyed by an id within that source.\n",
		"\tSetting a modifier with the same source and id replaces it; it never stacks with itself.\n",
		"\n",
		"\tCombined value of a stat (decision 1's proposed stacking; the final rule is an M5\n",
		"\tbalancing decision):\n",
		"\n",
		"\t\tfloor((base + sum of flat bonuses) * (1 + sum of percentage bonuses) * product of multipliers)\n",
		"\n",
		"\tThe percentage factor and the multipliers are combined into one factor first, and the sum\n",
		"\tis multiplied by it once, so an intermediate step can never overflow when the final result\n",
		"\tfits (a x2 and a x0.5 cancel out at any magnitude).\n",
		"\tIt is rounded down ONCE, at the end, and is never below the stat's minimum (tap damage 1,\n",
		"\tbecause CombatService only accepts a positive tap damage). Modifiers are combined in a\n",
		"\tfixed order (source order above, then modifier id), so the result never depends on the\n",
		"\torder in which they were added. With no modifiers the combined value is exactly the base,\n",
		"\tthe same BigNum value Milestone 2 applied directly.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"export type Source = \"upgrade\" | \"hero\" | \"equipment\" | \"perk\"\n",
		"\n",
		"-- Any field may be omitted; at least one must be present.\n",
		"export type Modifier = {\n",
		"\tflat: BigNum?, -- added to the base\n",
		"\tpercent: number?, -- 0.25 = +25%; percentages from all sources are summed, not compounded\n",
		"\tmultiplier: number?, -- 2 = x2; multipliers from all sources are multiplied together\n",
		"}\n",
		"\n",
		"export type Sheet = {\n",
		"\tbase: { [string]: BigNum },\n",
		"\tmodifiers: { [string]: { [string]: { [string]: Modifier } } }, -- stat -> source -> modifier id -> modifier\n",
		"}\n",
		"\n",
		"local StatRules = {}\n",
		"\n",
		"StatRules.Stats = table.freeze({\n",
		"\tTapDamage = \"TapDamage\",\n",
		"})\n",
		"\n",
		"-- Combination order of the sources.\n",
		"StatRules.Sources = table.freeze({ \"upgrade\", \"hero\", \"equipment\", \"perk\" }) :: { Source }\n",
		"\n",
		"local MINIMUM: { [string]: BigNum } = {\n",
		"\tTapDamage = BigNum.one,\n",
		"}\n",
		"\n",
		"local function isStat(statId: unknown): boolean\n",
		"\treturn typeof(statId) == \"string\" and MINIMUM[statId :: string] ~= nil\n",
		"end\n",
		"\n",
		"local function isSource(source: unknown): boolean\n",
		"\treturn typeof(source) == \"string\" and table.find(StatRules.Sources, source :: Source) ~= nil\n",
		"end\n",
		"\n",
		"local function isFinite(value: number): boolean\n",
		"\treturn value == value and value ~= math.huge and value ~= -math.huge\n",
		"end\n",
		"\n",
		"-- A frozen copy of a valid modifier, or nil for anything invalid.\n",
		"local function copyModifier(modifier: unknown): Modifier?\n",
		"\tif typeof(modifier) ~= \"table\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal raw = modifier :: { [any]: any }\n",
		"\tfor key in raw do\n",
		"\t\tif key ~= \"flat\" and key ~= \"percent\" and key ~= \"multiplier\" then\n",
		"\t\t\treturn nil\n",
		"\t\tend\n",
		"\tend\n",
		"\tlocal flat, percent, multiplier = raw.flat, raw.percent, raw.multiplier\n",
		"\tif flat == nil and percent == nil and multiplier == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif flat ~= nil and not BigNum.isValid(flat) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif percent ~= nil and (typeof(percent) ~= \"number\" or not isFinite(percent) or percent < 0) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif multiplier ~= nil and (typeof(multiplier) ~= \"number\" or not isFinite(multiplier) or multiplier <= 0) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal copy: Modifier = { flat = flat, percent = percent, multiplier = multiplier }\n",
		"\ttable.freeze(copy :: any)\n",
		"\treturn copy\n",
		"end\n",
		"\n",
		"function StatRules.newSheet(): Sheet\n",
		"\treturn { base = {}, modifiers = {} }\n",
		"end\n",
		"\n",
		"-- An independent copy of a sheet (modifier records are frozen, so they are shared). StatService changes a copy and keeps it only if it can be applied.\n",
		"function StatRules.copySheet(sheet: Sheet): Sheet\n",
		"\tlocal copy = StatRules.newSheet()\n",
		"\tfor statId, value in sheet.base do\n",
		"\t\tcopy.base[statId] = value\n",
		"\tend\n",
		"\tfor statId, bySource in sheet.modifiers do\n",
		"\t\tlocal sources: { [string]: { [string]: Modifier } } = {}\n",
		"\t\tfor source, entries in bySource do\n",
		"\t\t\tsources[source] = table.clone(entries)\n",
		"\t\tend\n",
		"\t\tcopy.modifiers[statId] = sources\n",
		"\tend\n",
		"\treturn copy\n",
		"end\n",
		"\n",
		"-- Sets a stat's base value (for tap damage: the Tap Damage upgrade's value). False if invalid.\n",
		"function StatRules.setBase(sheet: Sheet, statId: string, value: BigNum): boolean\n",
		"\tif not isStat(statId) or not BigNum.isValid(value) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tsheet.base[statId] = value\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Adds or replaces the modifier `modifierId` from `source`. False (and no change) if anything is invalid.\n",
		"function StatRules.setModifier(sheet: Sheet, statId: string, source: Source, modifierId: string, modifier: Modifier): boolean\n",
		"\tif not isStat(statId) or not isSource(source) or typeof(modifierId) ~= \"string\" or modifierId == \"\" then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal copy = copyModifier(modifier)\n",
		"\tif copy == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal bySource = sheet.modifiers[statId]\n",
		"\tif bySource == nil then\n",
		"\t\tbySource = {}\n",
		"\t\tsheet.modifiers[statId] = bySource\n",
		"\tend\n",
		"\tlocal entries = bySource[source]\n",
		"\tif entries == nil then\n",
		"\t\tentries = {}\n",
		"\t\tbySource[source] = entries\n",
		"\tend\n",
		"\tentries[modifierId] = copy\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Removes a modifier. True if it existed.\n",
		"function StatRules.removeModifier(sheet: Sheet, statId: string, source: Source, modifierId: string): boolean\n",
		"\tlocal bySource = sheet.modifiers[statId]\n",
		"\tif bySource == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal entries = bySource[source]\n",
		"\tif entries == nil or entries[modifierId] == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tentries[modifierId] = nil\n",
		"\tif next(entries) == nil then\n",
		"\t\tbySource[source] = nil -- empty groups are dropped, so a stat without modifiers takes the exact path again\n",
		"\tend\n",
		"\tif next(bySource) == nil then\n",
		"\t\tsheet.modifiers[statId] = nil\n",
		"\tend\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Number of modifiers on a stat (all sources).\n",
		"function StatRules.countModifiers(sheet: Sheet, statId: string): number\n",
		"\tlocal count = 0\n",
		"\tfor _, entries in sheet.modifiers[statId] or {} do\n",
		"\t\tfor _ in entries do\n",
		"\t\t\tcount += 1\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn count\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tThe combined value of a stat, or nil if its base was never set. Can raise BigNum's\n",
		"\toverflow error only if a result would exceed the largest exponent (2^53 - 1);\n",
		"\tStatService guards that call.\n",
		"]]\n",
		"function StatRules.combine(sheet: Sheet, statId: string): BigNum?\n",
		"\tlocal base = sheet.base[statId]\n",
		"\tif base == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal minimum = MINIMUM[statId]\n",
		"\tlocal bySource = sheet.modifiers[statId]\n",
		"\tif bySource == nil then\n",
		"\t\treturn BigNum.max(BigNum.floor(base), minimum) -- no modifiers: exactly the base (Milestone 2)\n",
		"\tend\n",
		"\n",
		"\tlocal total = base\n",
		"\tlocal percentTotal = BigNum.zero\n",
		"\tlocal factor = BigNum.one\n",
		"\tfor _, source in StatRules.Sources do\n",
		"\t\tlocal entries = bySource[source]\n",
		"\t\tif entries ~= nil then\n",
		"\t\t\tlocal ids: { string } = {}\n",
		"\t\t\tfor id in entries do\n",
		"\t\t\t\ttable.insert(ids, id)\n",
		"\t\t\tend\n",
		"\t\t\ttable.sort(ids)\n",
		"\t\t\tfor _, id in ids do\n",
		"\t\t\t\tlocal modifier = entries[id]\n",
		"\t\t\t\tif modifier.flat ~= nil then\n",
		"\t\t\t\t\ttotal = BigNum.add(total, modifier.flat)\n",
		"\t\t\t\tend\n",
		"\t\t\t\tif modifier.percent ~= nil and modifier.percent > 0 then\n",
		"\t\t\t\t\tpercentTotal = BigNum.add(percentTotal, BigNum.fromNumber(modifier.percent))\n",
		"\t\t\t\tend\n",
		"\t\t\t\tif modifier.multiplier ~= nil and modifier.multiplier ~= 1 then\n",
		"\t\t\t\t\tfactor = BigNum.mulNumber(factor, modifier.multiplier)\n",
		"\t\t\t\tend\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\tend\n",
		"\tif not BigNum.isZero(percentTotal) then\n",
		"\t\tfactor = BigNum.mul(BigNum.add(BigNum.one, percentTotal), factor)\n",
		"\tend\n",
		"\tif not BigNum.eq(factor, BigNum.one) then\n",
		"\t\ttotal = BigNum.mul(total, factor)\n",
		"\tend\n",
		"\treturn BigNum.max(BigNum.floor(total), minimum)\n",
		"end\n",
		"\n",
		"return table.freeze(StatRules)\n",
	},
}
FILES[15] = {
	path = "ServerScriptService/StatService",
	className = "ModuleScript",
	bytes = 7706,
	lines = 187,
	adler32 = 1444841730,
	sha256 = "3d7db26a3a882ce739c63f43d3c90e3ef534abeff10c03125ca7561cfe4bc94d",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tStatService\n",
		"\tLocation: ServerScriptService > StatService (ModuleScript)\n",
		"\n",
		"\tMilestone 2.1 (DECISIONS.md decision 1): the one place a player's combat stats are\n",
		"\tcombined. It keeps each player's base stats and modifiers grouped by source (upgrade,\n",
		"\thero, equipment, perk), combines them with StatRules (flat bonuses, then summed\n",
		"\tpercentage bonuses, then multipliers, rounded down once) and applies the result through\n",
		"\tCombatService.SetTapDamage.\n",
		"\n",
		"\tUpgradeService reports the Tap Damage upgrade's value here as the base tap damage\n",
		"\tinstead of setting tap damage itself. So upgrades and later hero, equipment or perk\n",
		"\tmodifiers no longer overwrite each other: a purchase changes only the base, and every\n",
		"\tmodifier still applies on top of it.\n",
		"\n",
		"\tEvery change is transactional and non-yielding. It is made on a copy of the player's\n",
		"\tsheet; the copy is combined; and it replaces the sheet only once CombatService has\n",
		"\taccepted the combined value. If combining fails (a BigNum exponent overflow) or the\n",
		"\tvalue cannot be applied, the previous sheet and the previous tap damage stay exactly as\n",
		"\tthey were. PrepareBase splits this in two, so UpgradeService can find a failure before\n",
		"\tany Gold moves and commit only after the spend.\n",
		"\n",
		"\tLifecycle (PlayerSessionService): added after CombatService and before UpgradeService,\n",
		"\tremoved in reverse order. It has no client sync of its own; the combined tap damage\n",
		"\treaches the client in CombatService's snapshot, exactly as in Milestone 2. Milestone 2\n",
		"\thas no modifier sources yet, so the combined tap damage always equals the upgrade value.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local CombatService = require(ServerScriptService:WaitForChild(\"CombatService\"))\n",
		"local StatRules = require(ServerScriptService:WaitForChild(\"StatRules\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"export type Source = StatRules.Source\n",
		"export type Modifier = StatRules.Modifier\n",
		"\n",
		"type Prepared = {\n",
		"\tplayer: Player,\n",
		"\tfrom: StatRules.Sheet, -- the sheet the change was prepared from; a commit requires it to still be current\n",
		"\tsheet: StatRules.Sheet, -- the changed copy\n",
		"\tstatId: string,\n",
		"\tvalue: BigNum?, -- combined value to apply; nil when the stat has no base yet\n",
		"}\n",
		"\n",
		"local sheets: { [Player]: StatRules.Sheet } = {}\n",
		"\n",
		"local StatService = {}\n",
		"\n",
		"StatService.Stats = StatRules.Stats\n",
		"StatService.Sources = StatRules.Sources\n",
		"\n",
		"-- The conditions CombatService.SetTapDamage checks, so a prepared change can always be committed.\n",
		"local function canApply(player: Player, statId: string, value: BigNum): boolean\n",
		"\treturn statId == StatRules.Stats.TapDamage and CombatService.HasPlayer(player) and BigNum.isValid(value) and not BigNum.isZero(value)\n",
		"end\n",
		"\n",
		"-- Makes `change` on a copy of the player's sheet and combines it. Nothing is changed; nil if the change is invalid or cannot be applied.\n",
		"local function prepare(player: Player, statId: string, change: (StatRules.Sheet) -> boolean): Prepared?\n",
		"\tlocal sheet = sheets[player]\n",
		"\tif sheet == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal candidate = StatRules.copySheet(sheet)\n",
		"\tif not change(candidate) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif candidate.base[statId] == nil then\n",
		"\t\treturn { player = player, from = sheet, sheet = candidate, statId = statId, value = nil }\n",
		"\tend\n",
		"\tlocal ok, combined = pcall(StatRules.combine, candidate, statId)\n",
		"\tif not ok then\n",
		"\t\twarn(`[StatService] Could not combine {statId} for {player.Name}; the change was not made: {combined}`)\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif combined == nil or not canApply(player, statId, combined) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn { player = player, from = sheet, sheet = candidate, statId = statId, value = combined }\n",
		"end\n",
		"\n",
		"-- Applies a prepared change: CombatService first, then the sheet. On any failure nothing changes.\n",
		"local function commit(prepared: Prepared): boolean\n",
		"\tif sheets[prepared.player] ~= prepared.from then\n",
		"\t\treturn false -- the player left, or the sheet changed since this was prepared\n",
		"\tend\n",
		"\tlocal value = prepared.value\n",
		"\tif value ~= nil and not CombatService.SetTapDamage(prepared.player, value) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tsheets[prepared.player] = prepared.sheet\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Requires CombatService.AddPlayer first; UpgradeService.AddPlayer then reports the starting base.\n",
		"function StatService.AddPlayer(player: Player)\n",
		"\tif sheets[player] or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tsheets[player] = StatRules.newSheet()\n",
		"end\n",
		"\n",
		"function StatService.RemovePlayer(player: Player)\n",
		"\tsheets[player] = nil\n",
		"end\n",
		"\n",
		"function StatService.HasPlayer(player: Player): boolean\n",
		"\treturn sheets[player] ~= nil\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tPrepares a new base value without changing anything. Returns the function that applies\n",
		"\tit (true on success), or nil if the value is invalid or the combined result cannot be\n",
		"\tapplied (for example a BigNum overflow). Call the returned function in the same\n",
		"\tnon-yielding step: it refuses to apply if the sheet changed in between.\n",
		"]]\n",
		"function StatService.PrepareBase(player: Player, statId: string, value: BigNum): (() -> boolean)?\n",
		"\tlocal prepared = prepare(player, statId, function(candidate: StatRules.Sheet): boolean\n",
		"\t\treturn StatRules.setBase(candidate, statId, value)\n",
		"\tend)\n",
		"\tif prepared == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal ready = prepared\n",
		"\treturn function(): boolean\n",
		"\t\treturn commit(ready)\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- Sets a stat's base value and applies the combined result. False, with nothing changed, if it cannot be applied.\n",
		"function StatService.SetBase(player: Player, statId: string, value: BigNum): boolean\n",
		"\tlocal apply = StatService.PrepareBase(player, statId, value)\n",
		"\tif apply == nil then\n",
		"\t\tif sheets[player] ~= nil then\n",
		"\t\t\twarn(`[StatService] Base value for {statId} was not applied ({player.Name})`)\n",
		"\t\tend\n",
		"\t\treturn false\n",
		"\tend\n",
		"\treturn apply()\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tAdds or replaces one modifier (for later hero, equipment and perk sources) and applies\n",
		"\tthe combined result once the stat has a base. Returns false, with the previous sheet and\n",
		"\ttap damage unchanged, if the modifier is invalid, the player is unknown, or the combined\n",
		"\tresult cannot be applied. Before a base exists the modifier is only stored; a base that\n",
		"\tlater cannot be combined with it is refused the same way.\n",
		"]]\n",
		"function StatService.SetModifier(player: Player, statId: string, source: Source, modifierId: string, modifier: Modifier): boolean\n",
		"\tif sheets[player] == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal valid = true\n",
		"\tlocal prepared = prepare(player, statId, function(candidate: StatRules.Sheet): boolean\n",
		"\t\tvalid = StatRules.setModifier(candidate, statId, source, modifierId, modifier)\n",
		"\t\treturn valid\n",
		"\tend)\n",
		"\tif not valid then\n",
		"\t\twarn(`[StatService] Rejected modifier {tostring(source)}/{tostring(modifierId)} for {tostring(statId)} ({player.Name})`)\n",
		"\t\treturn false\n",
		"\tend\n",
		"\treturn prepared ~= nil and commit(prepared)\n",
		"end\n",
		"\n",
		"-- Removes one modifier and applies the combined result. False, with nothing changed, if it did not exist or the result cannot be applied.\n",
		"function StatService.RemoveModifier(player: Player, statId: string, source: Source, modifierId: string): boolean\n",
		"\tlocal prepared = prepare(player, statId, function(candidate: StatRules.Sheet): boolean\n",
		"\t\treturn StatRules.removeModifier(candidate, statId, source, modifierId)\n",
		"\tend)\n",
		"\treturn prepared ~= nil and commit(prepared)\n",
		"end\n",
		"\n",
		"-- The current combined value of a stat, or nil (unknown player, or no base yet).\n",
		"function StatService.GetValue(player: Player, statId: string): BigNum?\n",
		"\tlocal sheet = sheets[player]\n",
		"\tif sheet == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal ok, combined = pcall(StatRules.combine, sheet, statId)\n",
		"\treturn if ok then combined else nil\n",
		"end\n",
		"\n",
		"return StatService\n",
	},
}
FILES[16] = {
	path = "ServerScriptService/Tests/BigNumTests",
	className = "ModuleScript",
	bytes = 26869,
	lines = 671,
	adler32 = 1174686409,
	sha256 = "056542c915b8cf90abffa6f90eee42ab684f6e1b8fc79afa295d77359c1eb8a8",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tBigNumTests\n",
		"\tLocation: ServerScriptService > Tests > BigNumTests (ModuleScript)\n",
		"\n",
		"\tDeterministic BigNum unit tests. Exact-string expectations use values whose\n",
		"\tmantissas are exact in binary (1.5, 3, 7.25 ...) so results cannot vary by\n",
		"\tplatform; everything else is checked by comparison or round trip.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectNil = TestKit.expectNil\n",
		"local expectError = TestKit.expectError\n",
		"local expectNear = TestKit.expectNear\n",
		"\n",
		"local TWO_POW_53 = 9007199254740992\n",
		"\n",
		"local function n(value: number): BigNum\n",
		"\treturn BigNum.fromNumber(value)\n",
		"end\n",
		"\n",
		"local function p(text: string): BigNum\n",
		"\tlocal value = BigNum.parse(text)\n",
		"\tif value == nil then\n",
		"\t\terror(`test setup: could not parse \"{text}\"`, 2)\n",
		"\tend\n",
		"\treturn value\n",
		"end\n",
		"\n",
		"local function s(value: BigNum): string\n",
		"\treturn BigNum.toString(value)\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"small values keep their exact double\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(n(0)), \"0\")\n",
		"\t\t\texpectEqual(s(n(13)), \"13\")\n",
		"\t\t\texpectEqual(s(n(TWO_POW_53 - 1)), \"9007199254740991\")\n",
		"\t\t\texpectEqual(n(13).e, 0, \"13 stays in the small regime\")\n",
		"\t\t\texpectEqual(n(13).m, 13, \"13 is stored exactly\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"fromNumber rejects NaN, infinity and negatives\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tn(0 / 0)\n",
		"\t\t\tend, \"NaN\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tn(math.huge)\n",
		"\t\t\tend, \"+infinity\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tn(-math.huge)\n",
		"\t\t\tend, \"-infinity\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tn(-1)\n",
		"\t\t\tend, \"negative\")\n",
		"\t\t\texpectEqual(s(n(-0)), \"0\", \"negative zero becomes zero\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"addition is exact below 2^53 and switches regime above\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.add(n(9), n(1))), \"10\")\n",
		"\t\t\texpectEqual(s(BigNum.add(n(TWO_POW_53 - 2), n(1))), \"9007199254740991\")\n",
		"\t\t\tlocal crossed = BigNum.add(n(TWO_POW_53 - 1), n(1))\n",
		"\t\t\texpectEqual(crossed.e, 15, \"2^53 is stored in the large regime\")\n",
		"\t\t\texpectTrue(BigNum.gt(crossed, n(TWO_POW_53 - 1)), \"2^53 > 2^53 - 1\")\n",
		"\t\t\texpectEqual(s(BigNum.add(p(\"1.5e400\"), p(\"1.5e400\"))), \"3e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"subtraction saturates at zero and stays exact below 2^53\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectTrue(BigNum.isZero(BigNum.sub(n(5), n(7))), \"5 - 7 saturates to 0\")\n",
		"\t\t\tlocal hp = n(11)\n",
		"\t\t\tfor remaining = 10, 0, -1 do\n",
		"\t\t\t\thp = BigNum.sub(hp, n(1))\n",
		"\t\t\t\texpectEqual(s(hp), tostring(remaining), \"HP countdown\")\n",
		"\t\t\tend\n",
		"\t\t\texpectTrue(BigNum.isZero(hp), \"HP reaches exactly zero\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"1.5e400\"), p(\"5e399\"))), \"1e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"trySub refuses to go below zero\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectNil(BigNum.trySub(n(3), n(5)), \"3 - 5\")\n",
		"\t\t\tlocal equal = BigNum.trySub(n(5), n(5))\n",
		"\t\t\texpectTrue(equal ~= nil and BigNum.isZero(equal), \"5 - 5 is zero\")\n",
		"\t\t\tlocal smaller = BigNum.trySub(n(5), n(3))\n",
		"\t\t\texpectTrue(smaller ~= nil and s(smaller) == \"2\", \"5 - 3 is 2\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"multiplication and division\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.mul(n(6), n(7))), \"42\")\n",
		"\t\t\texpectEqual(s(BigNum.mul(n(1e10), n(1e10))), \"1e20\")\n",
		"\t\t\texpectEqual(s(BigNum.mul(p(\"3e200\"), p(\"5e200\"))), \"1.5e401\")\n",
		"\t\t\texpectEqual(s(BigNum.mulNumber(p(\"1.5e400\"), 2)), \"3e400\")\n",
		"\t\t\texpectTrue(BigNum.isZero(BigNum.mul(n(0), p(\"1.5e400\"))), \"anything times zero is zero\")\n",
		"\t\t\texpectEqual(s(BigNum.div(n(42), n(6))), \"7\")\n",
		"\t\t\texpectEqual(s(BigNum.div(p(\"3e400\"), p(\"1.5e200\"))), \"2e200\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tBigNum.div(n(1), BigNum.zero)\n",
		"\t\t\tend, \"division by zero\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"values beyond 10^308 stay finite and ordered\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal big = p(\"1.5e400\")\n",
		"\t\t\texpectTrue(BigNum.isValid(big), \"valid\")\n",
		"\t\t\texpectEqual(s(big), \"1.5e400\")\n",
		"\t\t\texpectTrue(BigNum.gt(big, p(\"1e308\")), \"1.5e400 > 1e308\")\n",
		"\t\t\texpectEqual(BigNum.toNumber(big), math.huge, \"toNumber saturates at infinity\")\n",
		"\t\t\texpectNear(BigNum.log10(big), 400 + math.log10(1.5), 1e-9, \"log10\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a much smaller operand does not change a large value\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.add(p(\"1.5e400\"), n(1))), \"1.5e400\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"1.5e400\"), n(1))), \"1.5e400\")\n",
		"\t\t\texpectEqual(s(BigNum.add(n(1), p(\"1.5e400\"))), \"1.5e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"comparison works across both regimes\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal justBelow = n(TWO_POW_53 - 1)\n",
		"\t\t\tlocal justAbove = BigNum.add(justBelow, n(1))\n",
		"\t\t\texpectEqual(BigNum.compare(justBelow, justAbove), -1)\n",
		"\t\t\texpectEqual(BigNum.compare(justAbove, justBelow), 1)\n",
		"\t\t\texpectEqual(BigNum.compare(n(13), p(\"13\")), 0)\n",
		"\t\t\texpectEqual(BigNum.compare(p(\"2e400\"), p(\"3e399\")), 1)\n",
		"\t\t\texpectEqual(BigNum.compare(BigNum.zero, n(0)), 0)\n",
		"\t\t\texpectTrue(BigNum.lte(n(5), n(5)) and BigNum.gte(n(5), n(5)), \"lte and gte on equal values\")\n",
		"\t\t\texpectTrue(BigNum.lt(n(4), n(5)) and not BigNum.lt(n(5), n(4)), \"lt\")\n",
		"\t\t\texpectEqual(s(BigNum.max(n(3), p(\"1e20\"))), \"1e20\")\n",
		"\t\t\texpectEqual(s(BigNum.min(n(3), p(\"1e20\"))), \"3\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"canonical strings round-trip exactly\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal texts = { \"0\", \"1\", \"13\", \"999\", \"1000000000000000\", \"9007199254740991\", \"0.5\", \"0.25\", \"2e16\", \"1.5e400\", \"7.25e1000\" }\n",
		"\t\t\tfor _, text in texts do\n",
		"\t\t\t\texpectEqual(s(p(text)), text, \"round trip\")\n",
		"\t\t\tend\n",
		"\t\t\t-- Seeded, so the same 200 values are checked on every run.\n",
		"\t\t\tlocal rng = Random.new(20261031)\n",
		"\t\t\tfor _ = 1, 200 do\n",
		"\t\t\t\tlocal mantissa = 1 + rng:NextInteger(0, 899999) / 100000\n",
		"\t\t\t\tlocal exponent = rng:NextInteger(16, 100000)\n",
		"\t\t\t\tlocal value = p(string.format(\"%.5fe%d\", mantissa, exponent))\n",
		"\t\t\t\tlocal again = p(s(value))\n",
		"\t\t\t\texpectTrue(BigNum.eq(value, again), `round trip of {s(value)}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decimal text with an exponent is read exactly\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(p(\"1.1e1\")), \"11\")\n",
		"\t\t\texpectEqual(s(p(\"25e-1\")), \"2.5\")\n",
		"\t\t\texpectEqual(s(p(\"007\")), \"7\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"parse rejects malformed and non-finite input\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal bad = { \"\", \" 1\", \"1 \", \"-1\", \"+1\", \"abc\", \"1e\", \"e5\", \".5\", \"1..2\", \"inf\", \"nan\", \"0x10\", \"1e9007199254740993\", \"1e99999999999999999999\", string.rep(\"1\", 65) }\n",
		"\t\t\tfor _, text in bad do\n",
		"\t\t\t\texpectNil(BigNum.parse(text), `parse(\"{text}\")`)\n",
		"\t\t\tend\n",
		"\t\t\texpectNil(BigNum.parse(12), \"number input\")\n",
		"\t\t\texpectNil(BigNum.parse(nil), \"nil input\")\n",
		"\t\t\texpectNil(BigNum.parse({}), \"table input\")\n",
		"\t\t\texpectNil(BigNum.parse(true), \"boolean input\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"isValid rejects malformed tables\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectTrue(BigNum.isValid(n(13)), \"13\")\n",
		"\t\t\texpectTrue(BigNum.isValid(p(\"1.5e16\")), \"1.5e16\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = 0 / 0, e = 0 }), \"NaN mantissa\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = math.huge, e = 0 }), \"infinite mantissa\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = -1, e = 0 }), \"negative\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = 11, e = 20 }), \"mantissa >= 10\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = 5, e = 15 }), \"large form for a small value\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = 1.5, e = 20.5 }), \"fractional exponent\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = TWO_POW_53, e = 0 }), \"small form at 2^53\")\n",
		"\t\t\texpectTrue(not BigNum.isValid({ m = \"1\", e = 0 }), \"string mantissa\")\n",
		"\t\t\texpectTrue(not BigNum.isValid(\"13\"), \"string\")\n",
		"\t\t\texpectTrue(not BigNum.isValid(nil), \"nil\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"floor\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.floor(n(12.7))), \"12\")\n",
		"\t\t\texpectEqual(s(BigNum.floor(n(0.5))), \"0\")\n",
		"\t\t\texpectEqual(s(BigNum.floor(p(\"1.5e400\"))), \"1.5e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"ratio for health bars\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(BigNum.ratio(n(5), n(10)), 0.5)\n",
		"\t\t\texpectEqual(BigNum.ratio(p(\"1.5e400\"), p(\"3e400\")), 0.5)\n",
		"\t\t\texpectEqual(BigNum.ratio(BigNum.zero, n(7)), 0)\n",
		"\t\t\texpectEqual(BigNum.ratio(n(1), p(\"1e500\")), 0)\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tBigNum.ratio(n(1), BigNum.zero)\n",
		"\t\t\tend, \"ratio by zero\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"format matches Milestone 1 style and continues past Dc\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(BigNum.format(n(999)), \"999\")\n",
		"\t\t\texpectEqual(BigNum.format(n(12.9)), \"12\")\n",
		"\t\t\texpectEqual(BigNum.format(n(1234)), \"1.23K\")\n",
		"\t\t\texpectEqual(BigNum.format(n(5600000)), \"5.6M\")\n",
		"\t\t\texpectEqual(BigNum.format(n(999999)), \"1M\")\n",
		"\t\t\texpectEqual(BigNum.format(p(\"1e33\")), \"1Dc\")\n",
		"\t\t\texpectEqual(BigNum.format(p(\"1.5e400\")), \"1.5e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"scaledPower equals the plain-double formula in the small range\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor steps = 0, 200 do\n",
		"\t\t\t\tlocal expected = 5 * 1.07 ^ steps\n",
		"\t\t\t\texpectTrue(BigNum.eq(BigNum.scaledPower(5, 1.07, steps), n(expected)), `5 * 1.07^{steps}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"scaledPower uses log space instead of overflowing\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal previous = BigNum.scaledPower(10, 1.18, 4990)\n",
		"\t\t\tfor steps = 4991, 5010 do\n",
		"\t\t\t\tlocal value = BigNum.scaledPower(10, 1.18, steps)\n",
		"\t\t\t\texpectTrue(BigNum.isValid(value), `valid at {steps}`)\n",
		"\t\t\t\texpectTrue(BigNum.gt(value, previous), `increasing at {steps}`)\n",
		"\t\t\t\tprevious = value\n",
		"\t\t\tend\n",
		"\t\t\tlocal value = BigNum.scaledPower(10, 1.18, 5000)\n",
		"\t\t\texpectTrue(value.e > 308, \"beyond a double's range\")\n",
		"\t\t\texpectNear(BigNum.log10(value), 1 + 5000 * math.log10(1.18), 1e-6, \"log10 of 10 * 1.18^5000\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"fromLog10\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.fromLog10(2)), \"100\")\n",
		"\t\t\tlocal value = BigNum.fromLog10(400.5)\n",
		"\t\t\texpectEqual(value.e, 400)\n",
		"\t\t\texpectNear(value.m, math.sqrt(10), 1e-9, \"mantissa of 10^400.5\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"overflow raises an error instead of producing infinity\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal huge = p(\"1e9000000000000000\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tBigNum.mul(huge, huge)\n",
		"\t\t\tend, \"exponent overflow\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"values are immutable\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal value: any = n(5)\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tvalue.m = 6\n",
		"\t\t\tend, \"writing to a frozen BigNum\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t-- Regression tests for the Milestone 2 Codex audit findings (F1, F2, F4).\n",
		"\t{\n",
		"\t\tname = \"subtraction that returns below 2^53 is exact\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- F1: scientific form made 2^53 - (2^53 - 1) come out as 1.7763568394002502.\n",
		"\t\t\tlocal twoPow53 = n(TWO_POW_53)\n",
		"\t\t\texpectEqual(twoPow53.e, 15, \"2^53 is stored in the large regime\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(twoPow53, n(TWO_POW_53 - 1))), \"1\", \"2^53 - (2^53 - 1)\")\n",
		"\t\t\tfor distance = 1, 64 do\n",
		"\t\t\t\tlocal difference = BigNum.sub(twoPow53, n(TWO_POW_53 - distance))\n",
		"\t\t\t\texpectEqual(s(difference), tostring(distance), `2^53 - (2^53 - {distance})`)\n",
		"\t\t\t\texpectEqual(difference.e, 0, \"the result is back in the exact small regime\")\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(s(BigNum.sub(twoPow53, n(1))), \"9007199254740991\", \"2^53 - 1\")\n",
		"\t\t\t-- 2^53 + 2000 is a whole double above 2^53, so coming back below it must be exact.\n",
		"\t\t\tlocal above = BigNum.add(n(TWO_POW_53 - 1000), n(3000))\n",
		"\t\t\texpectEqual(s(BigNum.sub(above, n(2500))), \"9007199254740492\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(above, n(TWO_POW_53 - 1000))), \"3000\")\n",
		"\t\t\t-- Two large operands whose difference is small give a whole number, not 3000000000000000.5.\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"1.5e16\"), p(\"1.2e16\"))), \"3000000000000000\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"1.0000000000000002e22\"), p(\"1e22\"))), \"2097152\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"subtraction with large results\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"3e16\"), p(\"1e16\"))), \"2e16\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"1e20\"), n(5))), \"1e20\")\n",
		"\t\t\texpectEqual(s(BigNum.sub(p(\"2e400\"), p(\"5e399\"))), \"1.5e400\")\n",
		"\t\t\texpectTrue(BigNum.isZero(BigNum.sub(n(TWO_POW_53), n(TWO_POW_53))), \"equal values give zero\")\n",
		"\t\t\t-- Below 10^16 the result is the correctly rounded double, for every pair (seeded).\n",
		"\t\t\tlocal rng = Random.new(53)\n",
		"\t\t\tfor _ = 1, 200 do\n",
		"\t\t\t\tlocal a = TWO_POW_53 + 2 * rng:NextInteger(0, 400000000) * 1000000\n",
		"\t\t\t\tlocal b = rng:NextInteger(0, 1000000)\n",
		"\t\t\t\texpectEqual(BigNum.toNumber(BigNum.sub(n(a), n(b))), a - b, `{a} - {b}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"parse returns nil instead of overflowing during normalization\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- F2: these raised \"BigNum overflow\" from inside parse.\n",
		"\t\t\tlocal overflowing = {\n",
		"\t\t\t\t\"10e9007199254740991\",\n",
		"\t\t\t\t\"100e9007199254740990\",\n",
		"\t\t\t\t\"99.5e9007199254740991\",\n",
		"\t\t\t\tstring.rep(\"9\", 40) .. \"e9007199254740980\",\n",
		"\t\t\t}\n",
		"\t\t\tfor _, text in overflowing do\n",
		"\t\t\t\tlocal ok, result = pcall(BigNum.parse, text)\n",
		"\t\t\t\texpectTrue(ok, `parse(\"{text}\") must not raise an error`)\n",
		"\t\t\t\texpectNil(result, `parse(\"{text}\")`)\n",
		"\t\t\tend\n",
		"\t\t\t-- The largest representable exponent still parses, however the text writes it.\n",
		"\t\t\tlocal top = p(\"1000e9007199254740988\")\n",
		"\t\t\texpectEqual(top.e, 9007199254740991, \"1000e(2^53 - 4) normalizes to exponent 2^53 - 1\")\n",
		"\t\t\texpectEqual(s(top), \"1e9007199254740991\")\n",
		"\t\t\texpectEqual(p(\"99e9007199254740990\").e, 9007199254740991)\n",
		"\t\t\texpectEqual(p(\"9.99e9007199254740991\").e, 9007199254740991)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"the smallest positive doubles work in arithmetic\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- F4: subnormal values made toScientific divide by an underflowed 10^-324.\n",
		"\t\t\tlocal tiny = n(5e-324) -- the smallest positive double\n",
		"\t\t\tlocal product = BigNum.mul(tiny, p(\"1e400\"))\n",
		"\t\t\texpectTrue(BigNum.isValid(product), \"5e-324 * 1e400 is valid\")\n",
		"\t\t\texpectNear(BigNum.log10(product), math.log10(5e-324) + 400, 1e-9, \"5e-324 * 1e400\")\n",
		"\t\t\texpectTrue(BigNum.eq(BigNum.div(product, p(\"1e400\")), tiny), \"dividing back gives 5e-324, not zero\")\n",
		"\t\t\texpectNear(BigNum.log10(BigNum.div(n(1), tiny)), -math.log10(5e-324), 1e-9, \"1 / 5e-324\")\n",
		"\t\t\tlocal smallestNormal = n(2.2250738585072014e-308)\n",
		"\t\t\texpectNear(\n",
		"\t\t\t\tBigNum.log10(BigNum.mul(smallestNormal, p(\"1e400\"))),\n",
		"\t\t\t\tmath.log10(2.2250738585072014e-308) + 400,\n",
		"\t\t\t\t1e-9,\n",
		"\t\t\t\t\"2.2250738585072014e-308 * 1e400\"\n",
		"\t\t\t)\n",
		"\t\t\texpectEqual(s(BigNum.add(tiny, p(\"1e400\"))), \"1e400\")\n",
		"\t\t\texpectTrue(BigNum.eq(p(s(tiny)), tiny), \"5e-324 round-trips through text\")\n",
		"\t\t\texpectTrue(BigNum.lt(tiny, n(1e-300)), \"ordered\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"--[[\n",
		"\tCandidate regression tests for DEFECT-001 (arithmetic) and DEFECT-001B (canonical text).\n",
		"\tThey are appended after the original list so the original assertions keep their line numbers\n",
		"\t(BigNumTests.luau:364 and :374 above), and each is its own test, so an arithmetic failure\n",
		"\tcannot hide a serialization failure.\n",
		"\n",
		"\tRoblox Studio runs with flush-to-zero: subnormal arithmetic results become 0 (subnormal\n",
		"\tinputs are kept), and its string.format printed \"0\" for 5e-324 with \"%.17g\". The subnormal\n",
		"\tfixtures are therefore built from IEEE-754 bit patterns, not computed. Expected values hold in\n",
		"\tboth floating-point modes (checked offline with FTZ on and off, and with the Studio formatter\n",
		"\tbehaviour modeled).\n",
		"]]\n",
		"\n",
		"type DivisionCase = {\n",
		"\tdividend: string,\n",
		"\tdivisor: string,\n",
		"\texpected: number,\n",
		"}\n",
		"\n",
		"type UnderflowCase = {\n",
		"\tdividend: string,\n",
		"\tdivisor: string,\n",
		"}\n",
		"\n",
		"type SerializationFixture = {\n",
		"\tlabel: string,\n",
		"\tvalue: BigNum,\n",
		"\tsubnormal: boolean,\n",
		"}\n",
		"\n",
		"local MIN_NORMAL = 2.2250738585072014e-308 -- smallest positive normal double\n",
		"\n",
		"-- The binary64 value with this IEEE-754 bit pattern (high and low 32-bit words). Only bytes are\n",
		"-- copied, with no floating-point arithmetic, so a flush-to-zero host cannot alter the value.\n",
		"local function fromBits(high: number, low: number): number\n",
		"\tlocal bytes = buffer.create(8)\n",
		"\tbuffer.writeu32(bytes, 0, low)\n",
		"\tbuffer.writeu32(bytes, 4, high)\n",
		"\treturn buffer.readf64(bytes, 0)\n",
		"end\n",
		"\n",
		"local SMALLEST_SUBNORMAL = fromBits(0x00000000, 0x00000001) -- 4.9406564584124654e-324\n",
		"local NEXT_SUBNORMAL = fromBits(0x00000000, 0x00000002) -- 9.8813129168249309e-324\n",
		"local SUBNORMAL_1E_320 = fromBits(0x00000000, 0x000007E8) -- nearest double to 1e-320\n",
		"local SUBNORMAL_1E_310 = fromBits(0x00001268, 0x8B70E62B) -- nearest double to 1e-310\n",
		"local LARGEST_SUBNORMAL = fromBits(0x000FFFFF, 0xFFFFFFFF) -- 2.2250738585072009e-308\n",
		"local SMALLEST_NORMAL = fromBits(0x00100000, 0x00000000) -- 2.2250738585072014e-308\n",
		"\n",
		"local function serializationFixtures(): { SerializationFixture }\n",
		"\treturn {\n",
		"\t\t{ label = \"smallest positive double (bits 0x1)\", value = n(SMALLEST_SUBNORMAL), subnormal = true },\n",
		"\t\t{ label = \"next subnormal (bits 0x2)\", value = n(NEXT_SUBNORMAL), subnormal = true },\n",
		"\t\t{ label = \"1e-320 (bits 0x7E8)\", value = n(SUBNORMAL_1E_320), subnormal = true },\n",
		"\t\t{ label = \"1e-310 (bits 0x000012688B70E62B)\", value = n(SUBNORMAL_1E_310), subnormal = true },\n",
		"\t\t{ label = \"largest subnormal (bits 0x000FFFFFFFFFFFFF)\", value = n(LARGEST_SUBNORMAL), subnormal = true },\n",
		"\t\t{ label = \"smallest normal (bits 0x0010000000000000)\", value = n(SMALLEST_NORMAL), subnormal = false },\n",
		"\t\t{ label = \"zero\", value = BigNum.zero, subnormal = false },\n",
		"\t\t{ label = \"zero from bits\", value = n(fromBits(0, 0)), subnormal = false },\n",
		"\t\t{ label = \"1e-300\", value = n(1e-300), subnormal = false },\n",
		"\t\t{ label = \"0.1\", value = n(0.1), subnormal = false },\n",
		"\t\t{ label = \"0.5\", value = n(0.5), subnormal = false },\n",
		"\t\t{ label = \"1\", value = n(1), subnormal = false },\n",
		"\t\t{ label = \"13\", value = n(13), subnormal = false },\n",
		"\t\t{ label = \"123456.789\", value = n(123456.789), subnormal = false },\n",
		"\t\t{ label = \"1e15\", value = n(1e15), subnormal = false },\n",
		"\t\t{ label = \"2^53 - 1\", value = n(TWO_POW_53 - 1), subnormal = false },\n",
		"\t\t{ label = \"2^53 (first large value)\", value = n(TWO_POW_53), subnormal = false },\n",
		"\t\t{ label = \"1e16\", value = p(\"1e16\"), subnormal = false },\n",
		"\t\t{ label = \"largest double\", value = n(fromBits(0x7FEFFFFF, 0xFFFFFFFF)), subnormal = false },\n",
		"\t\t{ label = \"1.5e400\", value = p(\"1.5e400\"), subnormal = false },\n",
		"\t\t{ label = \"7.25e1000\", value = p(\"7.25e1000\"), subnormal = false },\n",
		"\t\t{ label = \"1e9007199254740991 (largest exponent)\", value = p(\"1e9007199254740991\"), subnormal = false },\n",
		"\t}\n",
		"end\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"subnormal results rebuilt from scientific form are not flushed to zero\",\n",
		"\trun = function()\n",
		"\t\tlocal cases: { DivisionCase } = {\n",
		"\t\t\t{ dividend = \"5e-30\", divisor = \"1e294\", expected = 5e-324 }, -- the smallest positive double\n",
		"\t\t\t{ dividend = \"3e-30\", divisor = \"1e294\", expected = 5e-324 }, -- rounds up to it\n",
		"\t\t\t{ dividend = \"1e-29\", divisor = \"1e294\", expected = 1e-323 }, -- twice the smallest positive double\n",
		"\t\t\t{ dividend = \"1e-26\", divisor = \"1e294\", expected = 1e-320 },\n",
		"\t\t\t{ dividend = \"1.5e-23\", divisor = \"1e294\", expected = 1.5e-317 },\n",
		"\t\t\t{ dividend = \"1e-16\", divisor = \"1e294\", expected = 1e-310 },\n",
		"\t\t\t{ dividend = \"1.1125369292536007e-14\", divisor = \"1e294\", expected = 1.1125369292536007e-308 }, -- half the smallest normal\n",
		"\t\t\t{ dividend = \"1.5\", divisor = \"1e310\", expected = 1.5e-310 },\n",
		"\t\t\t{ dividend = \"3\", divisor = \"1e310\", expected = 3e-310 },\n",
		"\t\t}\n",
		"\t\tfor _, case in cases do\n",
		"\t\t\tlocal value = BigNum.div(p(case.dividend), p(case.divisor))\n",
		"\t\t\texpectTrue(BigNum.isValid(value) and not BigNum.isZero(value), `{case.dividend} / {case.divisor} is a positive BigNum`)\n",
		"\t\t\texpectTrue(BigNum.eq(value, n(case.expected)), `{case.dividend} / {case.divisor} equals {case.expected}`)\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"the normal boundary and genuine underflow are unchanged\",\n",
		"\trun = function()\n",
		"\t\tlocal smallestNormal = n(2.2250738585072014e-308)\n",
		"\t\texpectTrue(BigNum.eq(BigNum.div(p(\"2.2250738585072014e-14\"), p(\"1e294\")), smallestNormal), \"smallest normal\")\n",
		"\t\t-- Just below it, the floating-point mode decides the last step (bounded precision contract):\n",
		"\t\t-- the result is the largest subnormal or the smallest normal, and never zero.\n",
		"\t\tlocal largestSubnormal = BigNum.div(p(\"2.2250738585072009e-14\"), p(\"1e294\"))\n",
		"\t\texpectTrue(\n",
		"\t\t\tBigNum.eq(largestSubnormal, n(2.2250738585072009e-308)) or BigNum.eq(largestSubnormal, smallestNormal),\n",
		"\t\t\t\"largest subnormal stays within one step\"\n",
		"\t\t)\n",
		"\t\t-- Below half of 5e-324 the exact result rounds to zero in every mode.\n",
		"\t\tlocal underflows: { UnderflowCase } = {\n",
		"\t\t\t{ dividend = \"1e-30\", divisor = \"1e294\" },\n",
		"\t\t\t{ dividend = \"2e-30\", divisor = \"1e294\" },\n",
		"\t\t\t{ dividend = \"2.4e-30\", divisor = \"1e294\" },\n",
		"\t\t\t{ dividend = \"5\", divisor = \"1e330\" },\n",
		"\t\t\t{ dividend = \"1e-30\", divisor = \"1e400\" },\n",
		"\t\t}\n",
		"\t\tfor _, case in underflows do\n",
		"\t\t\tlocal value = BigNum.div(p(case.dividend), p(case.divisor))\n",
		"\t\t\texpectTrue(BigNum.isZero(value) and BigNum.eq(value, BigNum.zero), `{case.dividend} / {case.divisor} underflows to zero`)\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"subnormal fixtures built from IEEE-754 bits are the intended doubles\",\n",
		"\trun = function()\n",
		"\t\t-- A host that reads subnormal inputs as zero (DAZ) fails here, before any serialization check.\n",
		"\t\tlocal ordered = { SMALLEST_SUBNORMAL, NEXT_SUBNORMAL, SUBNORMAL_1E_320, SUBNORMAL_1E_310, LARGEST_SUBNORMAL }\n",
		"\t\tfor index, value in ordered do\n",
		"\t\t\texpectTrue(value > 0 and value < MIN_NORMAL, `subnormal fixture {index} is positive and below the smallest normal`)\n",
		"\t\t\tif index > 1 then\n",
		"\t\t\t\texpectTrue(value > ordered[index - 1], `subnormal fixture {index} is larger than fixture {index - 1}`)\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\t\texpectTrue(SMALLEST_NORMAL == MIN_NORMAL, \"bits 0x0010000000000000 are the smallest normal\")\n",
		"\t\texpectTrue(fromBits(0x3FF00000, 0) == 1, \"bits 0x3FF0000000000000 are 1\")\n",
		"\t\texpectTrue(fromBits(0, 0) == 0, \"bits 0 are zero\")\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"canonical text round-trips exactly for subnormal, boundary, ordinary and large values\",\n",
		"\trun = function()\n",
		"\t\t-- DEFECT-001B: Studio printed the smallest positive double as \"0\", so it read back as zero.\n",
		"\t\tfor _, fixture in serializationFixtures() do\n",
		"\t\t\tif fixture.subnormal then\n",
		"\t\t\t\texpectTrue(not BigNum.isZero(fixture.value), `{fixture.label}: the fixture BigNum is not zero`)\n",
		"\t\t\tend\n",
		"\t\t\tlocal text = s(fixture.value)\n",
		"\t\t\tlocal back = BigNum.parse(text)\n",
		"\t\t\texpectTrue(back ~= nil, `{fixture.label}: parse(\"{text}\") returns a BigNum`)\n",
		"\t\t\tlocal parsed = back :: BigNum\n",
		"\t\t\texpectTrue(BigNum.isValid(parsed), `{fixture.label}: parse(\"{text}\") is valid`)\n",
		"\t\t\texpectTrue(BigNum.eq(parsed, fixture.value), `{fixture.label}: parse(toString(x)) equals x (text \"{text}\")`)\n",
		"\t\t\texpectEqual(s(parsed), text, `{fixture.label}: toString(parse(toString(x))) is unchanged`)\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"canonical text of zero, normal and large values keeps its existing form\",\n",
		"\trun = function()\n",
		"\t\texpectEqual(s(BigNum.zero), \"0\")\n",
		"\t\texpectEqual(s(n(0.5)), \"0.5\")\n",
		"\t\texpectEqual(s(n(13)), \"13\")\n",
		"\t\texpectEqual(s(n(TWO_POW_53 - 1)), \"9007199254740991\")\n",
		"\t\texpectEqual(s(p(\"1.5e400\")), \"1.5e400\")\n",
		"\t\texpectEqual(s(p(\"7.25e1000\")), \"7.25e1000\")\n",
		"\t\texpectEqual(s(p(\"1e9007199254740991\")), \"1e9007199254740991\")\n",
		"\t\t-- Every non-subnormal value still uses the \"%.17g\" text, the smallest normal included.\n",
		"\t\tfor _, fixture in serializationFixtures() do\n",
		"\t\t\tif not fixture.subnormal then\n",
		"\t\t\t\tlocal value = fixture.value\n",
		"\t\t\t\tlocal expected = if value.e == 0\n",
		"\t\t\t\t\tthen string.format(\"%.17g\", value.m)\n",
		"\t\t\t\t\telse string.format(\"%.17ge%.0f\", value.m, value.e)\n",
		"\t\t\t\texpectEqual(s(value), expected, `{fixture.label}: canonical text`)\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"text below half the smallest positive double still reads as zero\",\n",
		"\trun = function()\n",
		"\t\tfor _, text in { \"2e-324\", \"2.4e-324\", \"1e-330\", \"1e-400\" } do\n",
		"\t\t\tlocal value = p(text)\n",
		"\t\t\texpectTrue(BigNum.isZero(value) and BigNum.eq(value, BigNum.zero), `\"{text}\" reads as zero`)\n",
		"\t\t\texpectEqual(s(value), \"0\", `\"{text}\" prints as zero`)\n",
		"\t\tend\n",
		"\t\texpectTrue(BigNum.eq(p(\"3e-324\"), n(SMALLEST_SUBNORMAL)), `\"3e-324\" rounds up to the smallest positive double`)\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"parse rejects out-of-range decimals that would round into range (R2-1)\",\n",
		"\trun = function()\n",
		"\t\t-- Each of these is at least 10^(2^53), above the largest BigNum; the first one used to\n",
		"\t\t-- parse as 9.9999999999999982e9007199254740991 and pass isValid.\n",
		"\t\tlocal outOfRange = {\n",
		"\t\t\t\"1\" .. string.rep(\"0\", 23) .. \"e9007199254740969\",\n",
		"\t\t\t\"0001\" .. string.rep(\"0\", 23) .. \"e9007199254740969\",\n",
		"\t\t\t\"1\" .. string.rep(\"0\", 23) .. \".000e9007199254740969\",\n",
		"\t\t\t\"1\" .. string.rep(\"0\", 23) .. \"E+9007199254740969\",\n",
		"\t\t\t\"1\" .. string.rep(\"0\", 40) .. \"e9007199254740952\",\n",
		"\t\t\t\"10.0000000000000000001e9007199254740991\",\n",
		"\t\t}\n",
		"\t\tfor _, text in outOfRange do\n",
		"\t\t\tlocal ok, result = pcall(BigNum.parse, text)\n",
		"\t\t\texpectTrue(ok, `parse(\"{text}\") must not raise an error`)\n",
		"\t\t\texpectNil(result, `parse(\"{text}\")`)\n",
		"\t\tend\n",
		"\t\t-- One decade lower is in range and still accepted, at the top exponent.\n",
		"\t\tlocal inRange = {\n",
		"\t\t\t\"1\" .. string.rep(\"0\", 22) .. \"e9007199254740969\",\n",
		"\t\t\tstring.rep(\"9\", 23) .. \"e9007199254740969\",\n",
		"\t\t\tstring.rep(\"0\", 24) .. \"1e9007199254740991\",\n",
		"\t\t\t\"0.1e9007199254740991\",\n",
		"\t\t\t\"10e9007199254740990\",\n",
		"\t\t}\n",
		"\t\tlocal expectedExponents = { 9007199254740991, 9007199254740991, 9007199254740991, 9007199254740990, 9007199254740991 }\n",
		"\t\tfor index, text in inRange do\n",
		"\t\t\tlocal value = BigNum.parse(text)\n",
		"\t\t\texpectTrue(value ~= nil and BigNum.isValid(value), `parse(\"{text}\") is a valid BigNum`)\n",
		"\t\t\texpectEqual((value :: BigNum).e, expectedExponents[index], `exponent of \"{text}\"`)\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"parse accepts only decimals below 10^(2^53), at every mantissa length (seeded)\",\n",
		"\trun = function()\n",
		"\t\t-- The digits as written decide the range: a value whose first digit sits at decimal\n",
		"\t\t-- exponent 2^53 - 1 or below may round past the top and read as nil, but a value at or\n",
		"\t\t-- above 10^(2^53) never parses, and anything a full decade below the top always does.\n",
		"\t\tlocal rng = Random.new(2021)\n",
		"\t\tfor _ = 1, 300 do\n",
		"\t\t\tlocal digits = rng:NextInteger(1, 40)\n",
		"\t\t\tlocal text = tostring(rng:NextInteger(1, 9))\n",
		"\t\t\tif rng:NextInteger(1, 3) == 1 then\n",
		"\t\t\t\t-- Exact powers of ten: 10^23 and others round down as doubles, which is the R2-1 case.\n",
		"\t\t\t\ttext = \"1\" .. string.rep(\"0\", digits - 1)\n",
		"\t\t\telse\n",
		"\t\t\t\tfor _ = 2, digits do\n",
		"\t\t\t\t\ttext ..= tostring(rng:NextInteger(0, 9))\n",
		"\t\t\t\tend\n",
		"\t\t\tend\n",
		"\t\t\t-- The exponent is 2^53 - 1 - leading + top, written as text so that no large number is\n",
		"\t\t\t-- formatted: 2^53 - 1 = 9007199254740991 and every exponent here is 90071992547409xx.\n",
		"\t\t\tlocal leading = digits - 1\n",
		"\t\t\tlocal top = rng:NextInteger(-2, 2)\n",
		"\t\t\tlocal written = `{text}e90071992547409{91 - leading + top}`\n",
		"\t\t\tlocal value = BigNum.parse(written)\n",
		"\t\t\tif top > 0 then\n",
		"\t\t\t\texpectNil(value, `parse(\"{written}\") is above the range`)\n",
		"\t\t\telseif top < 0 then\n",
		"\t\t\t\texpectTrue(value ~= nil and BigNum.isValid(value), `parse(\"{written}\") is in range`)\n",
		"\t\t\telse\n",
		"\t\t\t\texpectTrue(value == nil or BigNum.isValid(value), `parse(\"{written}\") is nil or valid`)\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"table.insert(tests, {\n",
		"\tname = \"canonical text round-trips at every scale up to the top exponent\",\n",
		"\trun = function()\n",
		"\t\tlocal values = {\n",
		"\t\t\tBigNum.zero,\n",
		"\t\t\tBigNum.one,\n",
		"\t\t\tn(TWO_POW_53 - 1),\n",
		"\t\t\tn(TWO_POW_53),\n",
		"\t\t\tp(\"1.5e16\"),\n",
		"\t\t\tp(\"7.25e300\"),\n",
		"\t\t\tp(\"3e9007199254740990\"),\n",
		"\t\t\tp(\"9.99e9007199254740991\"),\n",
		"\t\t\tp(\"1e9007199254740991\"),\n",
		"\t\t}\n",
		"\t\tfor _, value in values do\n",
		"\t\t\tlocal text = s(value)\n",
		"\t\t\tlocal again = BigNum.parse(text)\n",
		"\t\t\texpectTrue(again ~= nil and BigNum.eq(again, value), `\"{text}\" reads back as the same value`)\n",
		"\t\t\texpectEqual(s(again :: BigNum), text, `\"{text}\" prints the same after a round trip`)\n",
		"\t\tend\n",
		"\tend,\n",
		"})\n",
		"\n",
		"return {\n",
		"\tname = \"BigNumTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[17] = {
	path = "ServerScriptService/Tests/CombatFormulaTests",
	className = "ModuleScript",
	bytes = 3327,
	lines = 87,
	adler32 = 1867459093,
	sha256 = "91b557d4c31584050ef8589586439a04771279f34f25f842fd88b812311f56bb",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatFormulaTests\n",
		"\tLocation: ServerScriptService > Tests > CombatFormulaTests (ModuleScript)\n",
		"\n",
		"\tMilestone 1 regression: the BigNum versions of the enemy HP and gold reward\n",
		"\tformulas must equal Milestone 1's plain-double formulas wherever those were\n",
		"\texact (below 2^53), and keep working far beyond a double's range.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"\n",
		"local TWO_POW_53 = 9007199254740992\n",
		"local combat = GameConfig.Combat\n",
		"\n",
		"-- Exactly the expressions Milestone 1's GameConfig used.\n",
		"local function milestone1EnemyMaxHp(stage: number): number\n",
		"\treturn math.max(1, math.floor(combat.StartingEnemyHp * combat.EnemyHpMultiplier ^ math.max(stage - 1, 0)))\n",
		"end\n",
		"\n",
		"local function milestone1GoldReward(stage: number): number\n",
		"\treturn math.max(0, math.floor(combat.StartingGoldReward * combat.GoldRewardMultiplier ^ math.max(stage - 1, 0)))\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"enemy HP equals Milestone 1 for every stage below 2^53 (stages 1-209)\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor stage = 1, 209 do\n",
		"\t\t\t\tlocal expected = milestone1EnemyMaxHp(stage)\n",
		"\t\t\t\texpectTrue(expected < TWO_POW_53, `stage {stage} is in the exact range`)\n",
		"\t\t\t\texpectTrue(BigNum.eq(GameConfig.GetEnemyMaxHp(stage), BigNum.fromNumber(expected)), `HP at stage {stage}`)\n",
		"\t\t\tend\n",
		"\t\t\texpectTrue(GameConfig.GetEnemyMaxHp(210).e >= 15, \"stage 210 HP is above 2^53 and stored in the large regime\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"gold reward equals Milestone 1 for every stage below 2^53 (stages 1-310)\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor stage = 1, 310 do\n",
		"\t\t\t\tlocal expected = milestone1GoldReward(stage)\n",
		"\t\t\t\texpectTrue(expected < TWO_POW_53, `stage {stage} is in the exact range`)\n",
		"\t\t\t\texpectTrue(BigNum.eq(GameConfig.GetGoldReward(stage), BigNum.fromNumber(expected)), `gold at stage {stage}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"Milestone 1 stage table\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal hp = { \"10\", \"11\", \"13\", \"16\", \"19\", \"22\", \"26\", \"31\", \"37\", \"44\", \"52\" }\n",
		"\t\t\tlocal gold = { \"5\", \"5\", \"6\", \"7\", \"7\", \"8\", \"9\", \"11\", \"12\", \"13\" }\n",
		"\t\t\tfor stage, text in hp do\n",
		"\t\t\t\texpectEqual(BigNum.toString(GameConfig.GetEnemyMaxHp(stage)), text, `HP at stage {stage}`)\n",
		"\t\t\tend\n",
		"\t\t\tfor stage, text in gold do\n",
		"\t\t\t\texpectEqual(BigNum.toString(GameConfig.GetGoldReward(stage)), text, `gold at stage {stage}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"late stages stay valid, increasing and beyond 10^308\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal stages = { 1000, 4275, 4276, 5000, 100000 }\n",
		"\t\t\tlocal previous = GameConfig.GetEnemyMaxHp(999)\n",
		"\t\t\tfor _, stage in stages do\n",
		"\t\t\t\tlocal hp = GameConfig.GetEnemyMaxHp(stage)\n",
		"\t\t\t\texpectTrue(BigNum.isValid(hp), `valid HP at stage {stage}`)\n",
		"\t\t\t\texpectTrue(BigNum.gt(hp, previous), `HP increases by stage {stage}`)\n",
		"\t\t\t\tprevious = hp\n",
		"\t\t\tend\n",
		"\t\t\texpectTrue(BigNum.log10(GameConfig.GetEnemyMaxHp(4276)) > 308.25, \"stage 4276 HP is past a double's maximum\")\n",
		"\t\t\texpectTrue(BigNum.isValid(GameConfig.GetGoldReward(100000)), \"gold at stage 100000 is valid\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"CombatFormulaTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[18] = {
	path = "ServerScriptService/Tests/CombatRulesTests",
	className = "ModuleScript",
	bytes = 4399,
	lines = 118,
	adler32 = 839619764,
	sha256 = "5f2bd8ac8ce428334aefa5780760a86e96b3539f451dd4f34046c4be48900827",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatRulesTests\n",
		"\tLocation: ServerScriptService > Tests > CombatRulesTests (ModuleScript)\n",
		"\n",
		"\tMilestone 1 regression for the combat rules: starting state, exact HP\n",
		"\treduction, no overkill carry-over, and exactly one defeat and one reward\n",
		"\tper enemy even under a burst of hits.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local CombatRules = require(ServerScriptService:WaitForChild(\"CombatRules\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"\n",
		"local function s(value: BigNum.BigNum): string\n",
		"\treturn BigNum.toString(value)\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"new state matches Milestone 1\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal state = CombatRules.newState()\n",
		"\t\t\texpectEqual(state.stage, 1)\n",
		"\t\t\texpectEqual(state.enemyId, 1)\n",
		"\t\t\texpectEqual(state.enemyName, \"Forest Slime\")\n",
		"\t\t\texpectEqual(s(state.enemyHp), \"10\")\n",
		"\t\t\texpectEqual(s(state.enemyMaxHp), \"10\")\n",
		"\t\t\texpectEqual(s(state.tapDamage), \"1\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a hit removes exactly its damage\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal state = CombatRules.newState()\n",
		"\t\t\tlocal outcome = CombatRules.resolveHit(state, BigNum.one)\n",
		"\t\t\texpectEqual(s(outcome.appliedDamage), \"1\")\n",
		"\t\t\texpectTrue(not outcome.defeated, \"not defeated\")\n",
		"\t\t\texpectTrue(BigNum.isZero(outcome.goldAwarded), \"no gold for a hit\")\n",
		"\t\t\texpectEqual(s(state.enemyHp), \"9\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"overkill does not carry over to the next enemy\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal state = CombatRules.newState()\n",
		"\t\t\tlocal outcome = CombatRules.resolveHit(state, BigNum.fromNumber(1000))\n",
		"\t\t\texpectEqual(s(outcome.appliedDamage), \"10\", \"applied damage is capped at remaining HP\")\n",
		"\t\t\texpectTrue(outcome.defeated, \"defeated\")\n",
		"\t\t\texpectEqual(outcome.defeatedStage, 1)\n",
		"\t\t\texpectEqual(s(outcome.goldAwarded), \"5\")\n",
		"\t\t\texpectEqual(state.stage, 2)\n",
		"\t\t\texpectEqual(state.enemyId, 2)\n",
		"\t\t\texpectEqual(s(state.enemyHp), \"11\", \"next enemy at full HP\")\n",
		"\t\t\texpectEqual(s(state.enemyMaxHp), \"11\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a burst of hits defeats and rewards each enemy exactly once\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal state = CombatRules.newState()\n",
		"\t\t\tlocal defeatedIds: { [number]: boolean } = {}\n",
		"\t\t\tlocal defeats = 0\n",
		"\t\t\tlocal totalGold = BigNum.zero\n",
		"\t\t\tfor _ = 1, 200 do\n",
		"\t\t\t\tlocal enemyIdBefore = state.enemyId\n",
		"\t\t\t\tlocal stageBefore = state.stage\n",
		"\t\t\t\tlocal outcome = CombatRules.resolveHit(state, BigNum.one)\n",
		"\t\t\t\tif outcome.defeated then\n",
		"\t\t\t\t\texpectTrue(not defeatedIds[enemyIdBefore], `enemy {enemyIdBefore} defeated only once`)\n",
		"\t\t\t\t\tdefeatedIds[enemyIdBefore] = true\n",
		"\t\t\t\t\tdefeats += 1\n",
		"\t\t\t\t\texpectEqual(outcome.defeatedStage, stageBefore, \"defeat belongs to the stage it happened on\")\n",
		"\t\t\t\t\texpectTrue(BigNum.eq(outcome.goldAwarded, GameConfig.GetGoldReward(stageBefore)), \"reward for that stage\")\n",
		"\t\t\t\t\texpectEqual(state.stage, stageBefore + 1, \"stage advances by exactly one\")\n",
		"\t\t\t\t\ttotalGold = BigNum.add(totalGold, outcome.goldAwarded)\n",
		"\t\t\t\telse\n",
		"\t\t\t\t\texpectEqual(state.enemyId, enemyIdBefore, \"no respawn without a defeat\")\n",
		"\t\t\t\tend\n",
		"\t\t\t\texpectTrue(not BigNum.isZero(state.enemyHp), \"a zero-HP enemy never persists\")\n",
		"\t\t\tend\n",
		"\t\t\t-- HP 10+11+13+16+19+22+26+31+37 = 185 hits for 9 defeats; 15 more hits on the 44 HP stage-10 enemy.\n",
		"\t\t\texpectEqual(defeats, 9)\n",
		"\t\t\texpectEqual(state.stage, 10)\n",
		"\t\t\texpectEqual(s(state.enemyHp), \"29\")\n",
		"\t\t\texpectEqual(s(totalGold), \"70\", \"gold for stages 1-9\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"ten one-hit kills follow the Milestone 1 stage table\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal state = CombatRules.newState()\n",
		"\t\t\tlocal expectedGold = { \"5\", \"5\", \"6\", \"7\", \"7\", \"8\", \"9\", \"11\", \"12\", \"13\" }\n",
		"\t\t\tlocal totalGold = BigNum.zero\n",
		"\t\t\tfor index, goldText in expectedGold do\n",
		"\t\t\t\tlocal outcome = CombatRules.resolveHit(state, BigNum.parse(\"1e100\") :: BigNum.BigNum)\n",
		"\t\t\t\texpectTrue(outcome.defeated, `kill {index}`)\n",
		"\t\t\t\texpectEqual(s(outcome.goldAwarded), goldText, `gold for kill {index}`)\n",
		"\t\t\t\ttotalGold = BigNum.add(totalGold, outcome.goldAwarded)\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(s(totalGold), \"83\")\n",
		"\t\t\texpectEqual(state.stage, 11)\n",
		"\t\t\texpectEqual(s(state.enemyHp), \"52\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"CombatRulesTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[19] = {
	path = "ServerScriptService/Tests/ProfileSchemaTests",
	className = "ModuleScript",
	bytes = 9972,
	lines = 280,
	adler32 = 1411935786,
	sha256 = "35f7662b5a118e3a7b35b7627c49dbd1825848272662e3480541aa7085fdee7e",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tProfileSchemaTests\n",
		"\tLocation: ServerScriptService > Tests > ProfileSchemaTests (ModuleScript)\n",
		"\n",
		"\tV1 migration and V2 profiles: defaults, round trips, and rejection of malformed\n",
		"\tor out-of-range stored value (a rejected profile is never replaced by defaults).\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectNil = TestKit.expectNil\n",
		"\n",
		"local GOLD = ProgressionConfig.GoldCurrencyId\n",
		"local TAP = ProgressionConfig.TapDamageUpgrade\n",
		"\n",
		"-- A valid stored profile with every field present.\n",
		"local function stored(): { [string]: any }\n",
		"\treturn {\n",
		"\t\tv = 1,\n",
		"\t\tcurrencies = { [GOLD] = \"1234\" },\n",
		"\t\tstage = 7,\n",
		"\t\tupgrades = { [TAP.id] = 5 },\n",
		"\t\tactiveSeconds = 90,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function decodeOk(raw: unknown): ProfileSchema.Profile\n",
		"\tlocal profile, reason = ProfileSchema.decode(raw)\n",
		"\tif profile == nil then\n",
		"\t\terror(`expected a valid profile, got: {reason}`, 2)\n",
		"\tend\n",
		"\treturn profile\n",
		"end\n",
		"\n",
		"local function expectRejected(raw: unknown, label: string)\n",
		"\tlocal profile, reason = ProfileSchema.decode(raw)\n",
		"\texpectNil(profile, label)\n",
		"\texpectTrue(typeof(reason) == \"string\" and #(reason :: string) > 0, `{label}: a reason is given`)\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"a new profile has the starting balances, stage, levels and zero active seconds\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\texpectEqual(BigNum.toString(profile.currencies[GOLD]), \"0\")\n",
		"\t\t\texpectEqual(profile.stage, GameConfig.Combat.StartingStage)\n",
		"\t\t\texpectEqual(profile.upgrades[TAP.id], TAP.startingLevel)\n",
		"\t\t\texpectEqual(profile.activeSeconds, 0)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"encode then decode returns the same profile, at small and huge values\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor _, goldText in { \"0\", \"1234\", \"9007199254740991\", \"1.5e16\", \"9.99e9007199254740991\" } do\n",
		"\t\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\t\tprofile.currencies[GOLD] = BigNum.parse(goldText) :: BigNum.BigNum\n",
		"\t\t\t\tprofile.stage = 4321\n",
		"\t\t\t\tprofile.runHighestStage = 4320\n",
		"\t\t\t\tprofile.lifetimeHighestStage = 4320\n",
		"\t\t\t\tprofile.upgrades[TAP.id] = TAP.maxLevel\n",
		"\t\t\t\tprofile.activeSeconds = 1800\n",
		"\t\t\t\tlocal encoded = ProfileSchema.encode(profile)\n",
		"\t\t\t\texpectEqual(encoded.v, ProfileSchema.Version)\n",
		"\t\t\t\texpectEqual(typeof(encoded.currencies[GOLD]), \"string\", \"balances are stored as text\")\n",
		"\t\t\t\tlocal decoded = decodeOk(encoded)\n",
		"\t\t\t\texpectTrue(BigNum.eq(decoded.currencies[GOLD], profile.currencies[GOLD]), `Gold {goldText} round-trips`)\n",
		"\t\t\t\texpectEqual(decoded.stage, 4321)\n",
		"\t\t\t\texpectEqual(decoded.upgrades[TAP.id], TAP.maxLevel)\n",
		"\t\t\t\texpectEqual(decoded.activeSeconds, 1800)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decode reads every field of a valid stored profile\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = decodeOk(stored())\n",
		"\t\t\texpectEqual(BigNum.toString(profile.currencies[GOLD]), \"1234\")\n",
		"\t\t\texpectEqual(profile.stage, 7)\n",
		"\t\t\texpectEqual(profile.upgrades[TAP.id], 5)\n",
		"\t\t\texpectEqual(profile.activeSeconds, 90)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"missing optional entries take starting values; unknown entries are ignored\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal raw = stored()\n",
		"\t\t\traw.currencies = { FutureCurrency = \"50\" }\n",
		"\t\t\traw.upgrades = { FutureUpgrade = 3 }\n",
		"\t\t\traw.activeSeconds = nil\n",
		"\t\t\traw.unknownField = \"kept out\"\n",
		"\t\t\tlocal profile = decodeOk(raw)\n",
		"\t\t\texpectEqual(BigNum.toString(profile.currencies[GOLD]), \"0\")\n",
		"\t\t\texpectNil(profile.currencies.FutureCurrency, \"an unknown currency is not loaded\")\n",
		"\t\t\texpectEqual(profile.upgrades[TAP.id], TAP.startingLevel)\n",
		"\t\t\texpectNil(profile.upgrades.FutureUpgrade, \"an unknown upgrade is not loaded\")\n",
		"\t\t\texpectEqual(profile.activeSeconds, 0)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decode rejects a missing, malformed or newer version\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectRejected(nil, \"nil\")\n",
		"\t\t\texpectRejected(\"profile\", \"a string\")\n",
		"\t\t\tfor _, version in { 0, -1, 1.5, 0 / 0, math.huge, \"1\" } do\n",
		"\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\traw.v = version\n",
		"\t\t\t\texpectRejected(raw, `version {version}`)\n",
		"\t\t\tend\n",
		"\t\t\tlocal raw = stored()\n",
		"\t\t\traw.v = nil\n",
		"\t\t\texpectRejected(raw, \"no version\")\n",
		"\t\t\traw = stored()\n",
		"\t\t\traw.v = ProfileSchema.Version + 1\n",
		"\t\t\tlocal profile, reason = ProfileSchema.decode(raw)\n",
		"\t\t\texpectNil(profile, \"a newer version\")\n",
		"\t\t\texpectTrue(string.find(reason or \"\", \"newer\", 1, true) ~= nil, \"the reason says the profile is newer\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decode rejects invalid balances, including out-of-range decimals (decision 9)\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal bad: { unknown } = {\n",
		"\t\t\t\t\"-5\",\n",
		"\t\t\t\t\"abc\",\n",
		"\t\t\t\t\"\",\n",
		"\t\t\t\t\"inf\",\n",
		"\t\t\t\t\"nan\",\n",
		"\t\t\t\t\"0x10\",\n",
		"\t\t\t\t\"1e9007199254740992\",\n",
		"\t\t\t\t\"10e9007199254740991\",\n",
		"\t\t\t\t\"1\" .. string.rep(\"0\", 23) .. \"e9007199254740969\", -- R2-1: 10^(2^53)\n",
		"\t\t\t\tstring.rep(\"9\", 65),\n",
		"\t\t\t\t12,\n",
		"\t\t\t\ttrue,\n",
		"\t\t\t\t{},\n",
		"\t\t\t}\n",
		"\t\t\tfor _, value in bad do\n",
		"\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\traw.currencies = { [GOLD] = value }\n",
		"\t\t\t\texpectRejected(raw, `Gold {tostring(value)}`)\n",
		"\t\t\tend\n",
		"\t\t\tlocal raw = stored()\n",
		"\t\t\traw.currencies = \"1234\"\n",
		"\t\t\texpectRejected(raw, \"currencies is not a table\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decode rejects invalid stages, levels and active seconds\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor _, stage in { 0, -3, 2.5, 0 / 0, math.huge, \"7\", 9007199254740992 } do\n",
		"\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\traw.stage = stage\n",
		"\t\t\t\texpectRejected(raw, `stage {stage}`)\n",
		"\t\t\tend\n",
		"\t\t\tfor _, level in { TAP.startingLevel - 1, TAP.maxLevel + 1, 2.5, 0 / 0, \"5\" } do\n",
		"\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\traw.upgrades = { [TAP.id] = level }\n",
		"\t\t\t\texpectRejected(raw, `level {level}`)\n",
		"\t\t\tend\n",
		"\t\t\tlocal raw = stored()\n",
		"\t\t\traw.upgrades = 5\n",
		"\t\t\texpectRejected(raw, \"upgrades is not a table\")\n",
		"\t\t\tfor _, seconds in { -1, 0 / 0, math.huge, \"90\" } do\n",
		"\t\t\t\traw = stored()\n",
		"\t\t\t\traw.activeSeconds = seconds\n",
		"\t\t\t\texpectRejected(raw, `activeSeconds {seconds}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"decode never changes the stored table, and decoded profiles are independent\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal raw = stored()\n",
		"\t\t\tlocal first = decodeOk(raw)\n",
		"\t\t\tlocal second = decodeOk(raw)\n",
		"\t\t\tfirst.upgrades[TAP.id] = 99\n",
		"\t\t\tfirst.currencies[GOLD] = BigNum.fromNumber(1)\n",
		"\t\t\texpectEqual(second.upgrades[TAP.id], 5)\n",
		"\t\t\texpectEqual(BigNum.toString(second.currencies[GOLD]), \"1234\")\n",
		"\t\t\texpectEqual(raw.currencies[GOLD], \"1234\")\n",
		"\t\t\texpectEqual(raw.upgrades[TAP.id], 5)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"v1 migration seeds cleared-stage records and canonical prestige defaults\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = decodeOk(stored())\n",
		"\t\t\texpectEqual(profile.runHighestStage, 6)\n",
		"\t\t\texpectEqual(profile.lifetimeHighestStage, 6)\n",
		"\t\t\texpectEqual(profile.prestige.count, 0)\n",
		"\t\t\texpectEqual(profile.prestige.runId, 1)\n",
		"\t\t\texpectEqual(ProfileSchema.encode(profile).prestige.multiplier, \"1\")\n",
		"\t\t\texpectEqual(ProfileSchema.encode(profile).v, 2)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"v2 preserves lifetime progress, claims and huge prestige multipliers\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tprofile.lifetimeHighestStage = 500\n",
		"\t\t\tprofile.prestige.multiplier = BigNum.parse(\"1e400\") :: BigNum.BigNum\n",
		"\t\t\tprofile.claimedMilestones[\"stage:100\"] = true\n",
		"\t\t\tlocal copy = decodeOk(ProfileSchema.encode(profile))\n",
		"\t\t\texpectEqual(copy.lifetimeHighestStage, 500)\n",
		"\t\t\texpectEqual(copy.runHighestStage, 0)\n",
		"\t\t\texpectEqual(ProfileSchema.encode(copy).prestige.multiplier, \"1e400\")\n",
		"\t\t\texpectTrue(copy.claimedMilestones[\"stage:100\"], \"claim survives\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"whole-number currencies reject fractions and over-cap balances\",\n",
		"\t\trun = function()\n",
		"\t\t\tfor _, currencyId in { \"Gems\", \"Crowns\" } do\n",
		"\t\t\t\tfor _, amount in { \"0.5\", \"9007199254740992\", \"-1\" } do\n",
		"\t\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\t\traw.currencies[currencyId] = amount\n",
		"\t\t\t\t\texpectRejected(raw, currencyId .. \" \" .. amount)\n",
		"\t\t\t\tend\n",
		"\t\t\t\tlocal raw = stored()\n",
		"\t\t\t\traw.currencies[currencyId] = \"9007199254740991\"\n",
		"\t\t\t\texpectEqual(BigNum.toString(decodeOk(raw).currencies[currencyId]), \"9007199254740991\")\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"current-version missing or inconsistent stage and prestige fields are rejected\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal valid = ProfileSchema.encode(ProfileSchema.new()) :: any\n",
		"\t\t\tfor _, key in { \"prestige\", \"runHighestStage\", \"lifetimeHighestStage\", \"transactions\", \"claimedMilestones\", \"activeSeconds\" } do\n",
		"\t\t\t\tlocal raw = table.clone(valid)\n",
		"\t\t\t\traw[key] = nil\n",
		"\t\t\t\texpectRejected(raw, \"missing \" .. key)\n",
		"\t\t\tend\n",
		"\t\t\tlocal missingGold = ProfileSchema.encode(ProfileSchema.new()) :: any\n",
		"\t\t\tmissingGold.currencies[GOLD] = nil\n",
		"\t\t\texpectRejected(missingGold, \"missing Gold\")\n",
		"\t\t\tlocal missingLevel = ProfileSchema.encode(ProfileSchema.new()) :: any\n",
		"\t\t\tmissingLevel.upgrades[TAP.id] = nil\n",
		"\t\t\texpectRejected(missingLevel, \"missing upgrade level\")\n",
		"\t\t\tvalid.runHighestStage = 5\n",
		"\t\t\texpectRejected(valid, \"run best exceeds lifetime best\")\n",
		"\t\t\tvalid.runHighestStage = 0\n",
		"\t\t\tvalid.prestige.multiplier = \"0.5\"\n",
		"\t\t\texpectRejected(valid, \"multiplier below one\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"malformed pending operations and disordered history are rejected\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal raw = ProfileSchema.encode(ProfileSchema.new()) :: any\n",
		"\t\t\traw.pendingTransaction = { id = 2, kind = \"Grant\", currencyId = \"Gold\", amount = \"1\" }\n",
		"\t\t\texpectRejected(raw, \"skipped id\")\n",
		"\t\t\traw.pendingTransaction = { id = 1, kind = \"Prestige\", runId = 1, runHighestStage = 0, calculatedGain = \"nan\", gainCurveVersion = \"A\" }\n",
		"\t\t\texpectRejected(raw, \"invalid saved gain\")\n",
		"\t\t\traw.pendingTransaction = nil\n",
		"\t\t\traw.transactionId = 2\n",
		"\t\t\traw.transactions = {\n",
		"\t\t\t\t{ id = 2, kind = \"Grant\", currencyId = \"Gold\", amount = \"1\" },\n",
		"\t\t\t\t{ id = 1, kind = \"Grant\", currencyId = \"Gold\", amount = \"1\" },\n",
		"\t\t\t}\n",
		"\t\t\texpectRejected(raw, \"disordered receipts\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"ProfileSchemaTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[20] = {
	path = "ServerScriptService/Tests/ProfileStoreTests",
	className = "ModuleScript",
	bytes = 13769,
	lines = 372,
	adler32 = 2260419114,
	sha256 = "bcc1cd6faf8bb5394f7b74fb605e673840772889264c74cc976331583b03b7a2",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tProfileStoreTests\n",
		"\tLocation: ServerScriptService > Tests > ProfileStoreTests (ModuleScript)\n",
		"\n",
		"\tSession-lock rules on an in-memory store (no DataStore is touched): claiming,\n",
		"\toverlapping servers, stale locks, lost locks, store errors and retries, and\n",
		"\tdamaged records that must never be claimed or overwritten.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local ProfileStore = require(ServerScriptService:WaitForChild(\"ProfileStore\"))\n",
		"local ProfileTransactions = require(ServerScriptService:WaitForChild(\"ProfileTransactions\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectNil = TestKit.expectNil\n",
		"\n",
		"local GOLD = ProgressionConfig.GoldCurrencyId\n",
		"local USER = 42\n",
		"local KEY = ProfileStore.keyFor(USER)\n",
		"local LOCK_TIMEOUT = 300\n",
		"\n",
		"type World = {\n",
		"\trecords: { [string]: any },\n",
		"\tclock: number,\n",
		"\twaits: { number },\n",
		"\tfailNext: number,\n",
		"\tcalls: number,\n",
		"\tbeforeTransform: (() -> ())?,\n",
		"}\n",
		"\n",
		"local function copy(value: any): any\n",
		"\tif typeof(value) ~= \"table\" then\n",
		"\t\treturn value\n",
		"\tend\n",
		"\tlocal result = {}\n",
		"\tfor key, item in value do\n",
		"\t\tresult[key] = copy(item)\n",
		"\tend\n",
		"\treturn result\n",
		"end\n",
		"\n",
		"local function newWorld(): World\n",
		"\treturn { records = {}, clock = 1000, waits = {}, failNext = 0, calls = 0, beforeTransform = nil }\n",
		"end\n",
		"\n",
		"-- One server's view of the shared store: its own job id, the shared records and clock.\n",
		"local function server(world: World, job: string): ProfileStore.Options\n",
		"\treturn {\n",
		"\t\tstore = {\n",
		"\t\t\tupdate = function(key: string, transform: (unknown) -> unknown?, _userId: number)\n",
		"\t\t\t\tworld.calls += 1\n",
		"\t\t\t\tif world.failNext > 0 then\n",
		"\t\t\t\t\tworld.failNext -= 1\n",
		"\t\t\t\t\terror(\"injected store failure\", 0)\n",
		"\t\t\t\tend\n",
		"\t\t\t\tlocal hook = world.beforeTransform\n",
		"\t\t\t\tif hook then\n",
		"\t\t\t\t\thook()\n",
		"\t\t\t\tend\n",
		"\t\t\t\tlocal new = transform(copy(world.records[key]))\n",
		"\t\t\t\tif new ~= nil then\n",
		"\t\t\t\t\tworld.records[key] = copy(new)\n",
		"\t\t\t\tend\n",
		"\t\t\tend,\n",
		"\t\t},\n",
		"\t\tjob = job,\n",
		"\t\tnow = function(): number\n",
		"\t\t\treturn world.clock\n",
		"\t\tend,\n",
		"\t\twait = function(seconds: number)\n",
		"\t\t\ttable.insert(world.waits, seconds)\n",
		"\t\t\tworld.clock += seconds\n",
		"\t\tend,\n",
		"\t\tlockTimeout = LOCK_TIMEOUT,\n",
		"\t\tattempts = 4,\n",
		"\t\tlockedRetries = 2,\n",
		"\t\tlockedRetryDelay = 5,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function always(): boolean\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"local function withGold(amount: number): ProfileSchema.Profile\n",
		"\tlocal profile = ProfileSchema.new()\n",
		"\tprofile.currencies[GOLD] = BigNum.fromNumber(amount)\n",
		"\treturn profile\n",
		"end\n",
		"\n",
		"local function storedGold(world: World): string?\n",
		"\tlocal record = world.records[KEY]\n",
		"\treturn record and record.profile and record.profile.currencies[GOLD]\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"a first load creates a new profile and locks it\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\texpectEqual(result.status, \"Loaded\")\n",
		"\t\t\texpectEqual(BigNum.toString((result.profile :: ProfileSchema.Profile).currencies[GOLD]), \"0\")\n",
		"\t\t\tlocal record = world.records[KEY]\n",
		"\t\t\texpectEqual(record.lock.session, \"s1\")\n",
		"\t\t\texpectEqual(record.lock.job, \"A\")\n",
		"\t\t\texpectEqual(record.profile.v, ProfileSchema.Version)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"save writes the profile and refreshes the lock; release clears it\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, USER, \"s1\", always)\n",
		"\t\t\tworld.clock += 60\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", withGold(25), false), \"Saved\")\n",
		"\t\t\texpectEqual(storedGold(world), \"25\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.at, 1060)\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", withGold(30), true), \"Saved\")\n",
		"\t\t\texpectEqual(storedGold(world), \"30\")\n",
		"\t\t\texpectNil(world.records[KEY].lock, \"released\")\n",
		"\t\t\tlocal again = ProfileStore.load(a, USER, \"s2\", always)\n",
		"\t\t\texpectEqual(again.status, \"Loaded\")\n",
		"\t\t\texpectEqual(BigNum.toString((again.profile :: ProfileSchema.Profile).currencies[GOLD]), \"30\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"another server cannot load a live profile and writes nothing\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\tProfileStore.save(server(world, \"A\"), USER, \"s1\", withGold(25), false)\n",
		"\t\t\tlocal before = copy(world.records[KEY])\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"B\"), USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Locked\")\n",
		"\t\t\texpectNil(result.profile, \"no profile is handed out\")\n",
		"\t\t\texpectEqual(#world.waits, 2, \"two retry rounds\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, before.lock.session)\n",
		"\t\t\texpectEqual(storedGold(world), \"25\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a load waiting on another server succeeds once that server releases\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, USER, \"s1\", always)\n",
		"\t\t\tlocal b = server(world, \"B\")\n",
		"\t\t\tlocal realWait = b.wait\n",
		"\t\t\tb.wait = function(seconds: number)\n",
		"\t\t\t\trealWait(seconds)\n",
		"\t\t\t\tProfileStore.save(a, USER, \"s1\", withGold(77), true) -- server A finishes leaving\n",
		"\t\t\tend\n",
		"\t\t\tlocal result = ProfileStore.load(b, USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Loaded\")\n",
		"\t\t\texpectEqual(BigNum.toString((result.profile :: ProfileSchema.Profile).currencies[GOLD]), \"77\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, \"s2\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a stale lock is taken over, and the old session can no longer save\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, USER, \"s1\", always)\n",
		"\t\t\tProfileStore.save(a, USER, \"s1\", withGold(10), false)\n",
		"\t\t\tworld.clock += LOCK_TIMEOUT\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"B\"), USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Loaded\")\n",
		"\t\t\texpectEqual(BigNum.toString((result.profile :: ProfileSchema.Profile).currencies[GOLD]), \"10\")\n",
		"\t\t\tProfileStore.save(server(world, \"B\"), USER, \"s2\", withGold(500), false)\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", withGold(999), false), \"LockLost\")\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", withGold(999), true), \"LockLost\")\n",
		"\t\t\texpectEqual(storedGold(world), \"500\", \"the old session wrote nothing\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, \"s2\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"one second before the timeout the lock is still live\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\t-- The two 5 s retry waits bring the lock's age to timeout - 1 on the last round.\n",
		"\t\t\tworld.clock += LOCK_TIMEOUT - 1 - 10\n",
		"\t\t\tlocal options = server(world, \"B\")\n",
		"\t\t\tlocal result = ProfileStore.load(options, USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Locked\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a new session on the same server waits for the previous lock\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"A\"), USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Locked\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, \"s1\")\n",
		"\t\t\texpectEqual(#world.waits, 2)\n",
		"\t\t\t-- Studio's empty JobId never counts as the same server.\n",
		"\t\t\tlocal studio = newWorld()\n",
		"\t\t\tProfileStore.load(server(studio, \"\"), USER, \"s1\", always)\n",
		"\t\t\texpectEqual(ProfileStore.load(server(studio, \"\"), USER, \"s2\", always).status, \"Locked\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"store errors are retried with doubling waits, then reported\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tworld.failNext = 2\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\texpectEqual(result.status, \"Loaded\")\n",
		"\t\t\texpectEqual(table.concat(world.waits, \",\"), \"1,2\")\n",
		"\t\t\tlocal failing = newWorld()\n",
		"\t\t\tfailing.failNext = 10\n",
		"\t\t\tlocal failed = ProfileStore.load(server(failing, \"A\"), USER, \"s1\", always)\n",
		"\t\t\texpectEqual(failed.status, \"Error\")\n",
		"\t\t\texpectEqual(failing.calls, 4)\n",
		"\t\t\texpectTrue(string.find(failed.detail or \"\", \"injected\", 1, true) ~= nil, \"the error is reported\")\n",
		"\t\t\texpectNil(failing.records[KEY], \"nothing was written\")\n",
		"\t\t\tfailing.failNext = 0\n",
		"\t\t\texpectEqual(ProfileStore.load(server(failing, \"A\"), USER, \"s1\", always).status, \"Loaded\")\n",
		"\t\t\tfailing.failNext = 10\n",
		"\t\t\tlocal status = ProfileStore.save(server(failing, \"A\"), USER, \"s1\", withGold(5), false)\n",
		"\t\t\texpectEqual(status, \"Error\")\n",
		"\t\t\texpectEqual(storedGold(failing), \"0\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a damaged or newer record is neither claimed nor overwritten\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal damaged: { [string]: any } = {\n",
		"\t\t\t\tnotTable = \"garbage\",\n",
		"\t\t\t\tbadGold = { profile = { v = 1, currencies = { [GOLD] = \"-1\" }, stage = 1, upgrades = {} } },\n",
		"\t\t\t\tnewer = { profile = { v = ProfileSchema.Version + 1, currencies = {}, stage = 1, upgrades = {} } },\n",
		"\t\t\t\tnoProfile = {},\n",
		"\t\t\t}\n",
		"\t\t\tfor label, record in damaged do\n",
		"\t\t\t\tlocal world = newWorld()\n",
		"\t\t\t\tworld.records[KEY] = copy(record)\n",
		"\t\t\t\tlocal result = ProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\t\texpectEqual(result.status, \"Invalid\", label)\n",
		"\t\t\t\texpectTrue(typeof(result.detail) == \"string\", `{label}: a reason is given`)\n",
		"\t\t\t\tlocal after = world.records[KEY]\n",
		"\t\t\t\tif typeof(record) == \"table\" then\n",
		"\t\t\t\t\texpectNil(after.lock, `{label}: not claimed`)\n",
		"\t\t\t\telse\n",
		"\t\t\t\t\texpectEqual(after, record, `{label}: unchanged`)\n",
		"\t\t\t\tend\n",
		"\t\t\t\texpectEqual(ProfileStore.save(server(world, \"A\"), USER, \"s1\", withGold(5), true), \"LockLost\", `{label}: cannot be overwritten`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a cancelled load claims nothing\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal result = ProfileStore.load(server(world, \"A\"), USER, \"s1\", function(): boolean\n",
		"\t\t\t\treturn false\n",
		"\t\t\tend)\n",
		"\t\t\texpectEqual(result.status, \"Cancelled\")\n",
		"\t\t\texpectEqual(world.calls, 0)\n",
		"\t\t\t-- Cancelled while waiting on another server's lock: no further store calls.\n",
		"\t\t\tProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\tlocal wanted = true\n",
		"\t\t\tlocal b = server(world, \"B\")\n",
		"\t\t\tb.wait = function(_seconds: number)\n",
		"\t\t\t\twanted = false\n",
		"\t\t\tend\n",
		"\t\t\tlocal before = world.calls\n",
		"\t\t\tlocal waiting = ProfileStore.load(b, USER, \"s2\", function(): boolean\n",
		"\t\t\t\treturn wanted\n",
		"\t\t\tend)\n",
		"\t\t\texpectEqual(waiting.status, \"Cancelled\")\n",
		"\t\t\texpectEqual(world.calls - before, 1)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"release without a profile keeps the stored profile and clears the lock\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, USER, \"s1\", always)\n",
		"\t\t\tProfileStore.save(a, USER, \"s1\", withGold(40), false)\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", nil, true), \"Saved\")\n",
		"\t\t\texpectEqual(storedGold(world), \"40\")\n",
		"\t\t\texpectNil(world.records[KEY].lock, \"released\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a transform that runs twice (a store conflict retry) reports its last run\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tProfileStore.load(server(world, \"A\"), USER, \"s1\", always)\n",
		"\t\t\tlocal b = server(world, \"B\")\n",
		"\t\t\tlocal realUpdate = b.store.update\n",
		"\t\t\tb.store = {\n",
		"\t\t\t\tupdate = function(key: string, transform: (unknown) -> unknown?, userId: number)\n",
		"\t\t\t\t\ttransform(copy(world.records[key])) -- first run sees A's live lock\n",
		"\t\t\t\t\tworld.records[key].lock = nil -- A releases before the store retries\n",
		"\t\t\t\t\trealUpdate(key, transform, userId)\n",
		"\t\t\t\tend,\n",
		"\t\t\t}\n",
		"\t\t\tlocal result = ProfileStore.load(b, USER, \"s2\", always)\n",
		"\t\t\texpectEqual(result.status, \"Loaded\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, \"s2\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"players' records are independent\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, 1, \"s1\", always)\n",
		"\t\t\tProfileStore.load(a, 2, \"s2\", always)\n",
		"\t\t\tProfileStore.save(a, 1, \"s1\", withGold(11), true)\n",
		"\t\t\texpectEqual(world.records[ProfileStore.keyFor(1)].profile.currencies[GOLD], \"11\")\n",
		"\t\t\texpectEqual(world.records[ProfileStore.keyFor(2)].profile.currencies[GOLD], \"0\")\n",
		"\t\t\texpectEqual(world.records[ProfileStore.keyFor(2)].lock.session, \"s2\")\n",
		"\t\t\texpectEqual(ProfileStore.save(a, 2, \"s1\", withGold(99), false), \"LockLost\", \"another player's session cannot write\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"claiming a session recovers and persists a saved pending grant once\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal a = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(a, USER, \"s1\", always)\n",
		"\t\t\tlocal pending = ProfileTransactions.prepare(ProfileSchema.new(), {\n",
		"\t\t\t\tid = 1, kind = \"Grant\", currencyId = GOLD, amount = \"25\",\n",
		"\t\t\t})\n",
		"\t\t\texpectTrue(pending ~= nil, \"preparation succeeded\")\n",
		"\t\t\texpectEqual(ProfileStore.save(a, USER, \"s1\", pending, true), \"Saved\")\n",
		"\t\t\texpectEqual(storedGold(world), \"0\", \"prepare is written before the reward\")\n",
		"\t\t\tlocal b = server(world, \"B\")\n",
		"\t\t\tlocal loaded = ProfileStore.load(b, USER, \"s2\", always)\n",
		"\t\t\texpectEqual(loaded.status, \"Loaded\")\n",
		"\t\t\texpectEqual(storedGold(world), \"25\")\n",
		"\t\t\texpectNil(world.records[KEY].profile.pendingTransaction)\n",
		"\t\t\texpectEqual(world.records[KEY].profile.transactionId, 1)\n",
		"\t\t\tProfileStore.save(b, USER, \"s2\", loaded.profile, true)\n",
		"\t\t\tProfileStore.load(server(world, \"C\"), USER, \"s3\", always)\n",
		"\t\t\texpectEqual(storedGold(world), \"25\", \"another load grants nothing extra\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"an invalid current snapshot is refused before replacing a stored profile\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal world = newWorld()\n",
		"\t\t\tlocal options = server(world, \"A\")\n",
		"\t\t\tProfileStore.load(options, USER, \"s1\", always)\n",
		"\t\t\tlocal bad = withGold(50)\n",
		"\t\t\tbad.stage = 5 -- its run record still says no cleared stage\n",
		"\t\t\texpectEqual(ProfileStore.save(options, USER, \"s1\", bad, false), \"Error\")\n",
		"\t\t\texpectEqual(storedGold(world), \"0\")\n",
		"\t\t\texpectEqual(world.records[KEY].lock.session, \"s1\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"ProfileStoreTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[21] = {
	path = "ServerScriptService/Tests/ProfileTransactionsTests",
	className = "ModuleScript",
	bytes = 7455,
	lines = 168,
	adler32 = 919576819,
	sha256 = "bf9e17d0cd9a9fa153fe67cde33f7afb894bbb0ffaac793ed8a90ebd122d1007",
	text = {
		"--!strict\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local ProfileSchema = require(ServerScriptService:WaitForChild(\"ProfileSchema\"))\n",
		"local ProfileTransactions = require(ServerScriptService:WaitForChild(\"ProfileTransactions\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectNil = TestKit.expectNil\n",
		"\n",
		"local function number(text: string): BigNum.BigNum\n",
		"\treturn BigNum.parse(text) :: BigNum.BigNum\n",
		"end\n",
		"\n",
		"local function prepared(profile: ProfileSchema.Profile, operation: { [string]: any }): ProfileSchema.Profile\n",
		"\tlocal result, problem = ProfileTransactions.prepare(profile, operation)\n",
		"\tassert(result, problem)\n",
		"\treturn result :: ProfileSchema.Profile\n",
		"end\n",
		"\n",
		"local function recovered(profile: ProfileSchema.Profile): ProfileSchema.Profile\n",
		"\t-- Exercise the stored representation between preparation and recovery.\n",
		"\tlocal decoded, decodeProblem = ProfileSchema.decode(ProfileSchema.encode(profile))\n",
		"\tassert(decoded, decodeProblem)\n",
		"\tlocal result, problem = ProfileTransactions.recover(decoded :: ProfileSchema.Profile)\n",
		"\tassert(result, problem)\n",
		"\treturn result :: ProfileSchema.Profile\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"a saved grant recovers once and retains its milestone claim\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal original = ProfileSchema.new()\n",
		"\t\t\tlocal operation = { id = 1, kind = \"Grant\", currencyId = \"Gems\", amount = \"10\", claimId = \"stage:10\" }\n",
		"\t\t\tlocal pending = prepared(original, operation)\n",
		"\t\t\texpectEqual(BigNum.toString(pending.currencies.Gems), \"0\")\n",
		"\t\t\texpectNil(original.pendingTransaction)\n",
		"\t\t\toperation.amount = \"999\"\n",
		"\t\t\tlocal result = recovered(pending)\n",
		"\t\t\texpectEqual(BigNum.toString(result.currencies.Gems), \"10\")\n",
		"\t\t\texpectTrue(result.claimedMilestones[\"stage:10\"], \"claim retained\")\n",
		"\t\t\texpectEqual(result.transactionId, 1)\n",
		"\t\t\texpectEqual(BigNum.toString(recovered(result).currencies.Gems), \"10\")\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(result, { id = 2, kind = \"Grant\", currencyId = \"Gems\", amount = \"10\", claimId = \"stage:10\" }))\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"upgrade recovery uses the saved price and changes balance and level together\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tprofile.currencies.Gold = number(\"100\")\n",
		"\t\t\tlocal pending = prepared(profile, {\n",
		"\t\t\t\tid = 1, kind = \"Upgrade\", currencyId = \"Gold\", amount = \"7\",\n",
		"\t\t\t\tupgradeId = \"TapDamage\", fromLevel = 1, toLevel = 2,\n",
		"\t\t\t})\n",
		"\t\t\tlocal result = recovered(pending)\n",
		"\t\t\texpectEqual(BigNum.toString(result.currencies.Gold), \"93\", \"the saved cost replaces the current price for recovery\")\n",
		"\t\t\texpectEqual(result.upgrades.TapDamage, 2)\n",
		"\t\t\texpectEqual(profile.upgrades.TapDamage, 1)\n",
		"\t\t\texpectEqual(BigNum.toString(profile.currencies.Gold), \"100\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"an unaffordable or stale operation changes nothing\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(profile, { id = 1, kind = \"Spend\", currencyId = \"Gold\", amount = \"5\" }))\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(profile, { id = 2, kind = \"Grant\", currencyId = \"Gold\", amount = \"5\" }))\n",
		"\t\t\texpectEqual(profile.transactionId, 0)\n",
		"\t\t\texpectEqual(BigNum.toString(profile.currencies.Gold), \"0\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"prestige recovery uses the snapshotted gain across curve changes\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tprofile.stage = 101\n",
		"\t\t\tprofile.runHighestStage = 100\n",
		"\t\t\tprofile.lifetimeHighestStage = 150\n",
		"\t\t\tprofile.currencies.Gold = number(\"100\")\n",
		"\t\t\tprofile.currencies.Crowns = number(\"20\")\n",
		"\t\t\tprofile.upgrades.TapDamage = 25\n",
		"\t\t\tprofile.prestige.multiplier = number(\"10\")\n",
		"\t\t\tprofile.claimedMilestones[\"stage:50\"] = true\n",
		"\t\t\tprofile.activeSeconds = 1800\n",
		"\t\t\tlocal pending = prepared(profile, {\n",
		"\t\t\t\tid = 1, kind = \"Prestige\", runId = 1, runHighestStage = 100,\n",
		"\t\t\t\tcalculatedGain = \"5\", gainCurveVersion = \"curve-A\",\n",
		"\t\t\t})\n",
		"\t\t\t-- New code can use a different curve; the persisted payload is authoritative.\n",
		"\t\t\tlocal result = recovered(pending)\n",
		"\t\t\texpectEqual(BigNum.toString(result.prestige.multiplier), \"15\")\n",
		"\t\t\texpectEqual(result.prestige.count, 1)\n",
		"\t\t\texpectEqual(result.prestige.runId, 2)\n",
		"\t\t\texpectEqual(result.stage, 1)\n",
		"\t\t\texpectEqual(result.runHighestStage, 0)\n",
		"\t\t\texpectEqual(result.lifetimeHighestStage, 150)\n",
		"\t\t\texpectEqual(result.upgrades.TapDamage, 1)\n",
		"\t\t\texpectEqual(BigNum.toString(result.currencies.Gold), \"0\")\n",
		"\t\t\texpectEqual(BigNum.toString(result.currencies.Crowns), \"20\")\n",
		"\t\t\texpectTrue(result.claimedMilestones[\"stage:50\"], \"claims survive\")\n",
		"\t\t\texpectEqual(result.activeSeconds, 1800)\n",
		"\t\t\texpectEqual(recovered(result).prestige.count, 1)\n",
		"\t\t\texpectEqual(result.transactions[1].calculatedGain, \"5\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"huge prestige multipliers and saved gains round trip\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tprofile.prestige.multiplier = number(\"1e400\")\n",
		"\t\t\tlocal result = recovered(prepared(profile, {\n",
		"\t\t\t\tid = 1, kind = \"Prestige\", runId = 1, runHighestStage = 0,\n",
		"\t\t\t\tcalculatedGain = \"2e399\", gainCurveVersion = \"test\",\n",
		"\t\t\t}))\n",
		"\t\t\texpectEqual(ProfileSchema.encode(result).prestige.multiplier, \"1.2e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"overflow or the wrong run rejects a prestige without resetting progress\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tprofile.prestige.multiplier = number(\"9e9007199254740991\")\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(profile, {\n",
		"\t\t\t\tid = 1, kind = \"Prestige\", runId = 1, runHighestStage = 0,\n",
		"\t\t\t\tcalculatedGain = \"9e9007199254740991\", gainCurveVersion = \"test\",\n",
		"\t\t\t}))\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(profile, {\n",
		"\t\t\t\tid = 1, kind = \"Prestige\", runId = 2, runHighestStage = 0,\n",
		"\t\t\t\tcalculatedGain = \"1\", gainCurveVersion = \"test\",\n",
		"\t\t\t}))\n",
		"\t\t\texpectEqual(profile.prestige.count, 0)\n",
		"\t\t\texpectEqual(BigNum.toString(profile.prestige.multiplier), \"9e9007199254740991\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"history pruning retains the high-water id and all pending work\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal profile = ProfileSchema.new()\n",
		"\t\t\tfor id = 1, ProfileSchema.HistoryLimit + 5 do\n",
		"\t\t\t\tprofile = recovered(prepared(profile, { id = id, kind = \"Grant\", currencyId = \"Gold\", amount = \"1\" }))\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(#profile.transactions, ProfileSchema.HistoryLimit)\n",
		"\t\t\texpectEqual(profile.transactionId, ProfileSchema.HistoryLimit + 5)\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(profile, { id = 1, kind = \"Grant\", currencyId = \"Gold\", amount = \"1\" }))\n",
		"\t\t\tlocal pending = prepared(profile, { id = profile.transactionId + 1, kind = \"Grant\", currencyId = \"Gold\", amount = \"7\" })\n",
		"\t\t\texpectTrue(pending.pendingTransaction ~= nil, \"pending work retained\")\n",
		"\t\t\texpectNil(ProfileTransactions.prepare(pending, { id = profile.transactionId + 2, kind = \"Grant\", currencyId = \"Gold\", amount = \"7\" }))\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a leftover applied marker is cleared without a second grant\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal operation = { id = 1, kind = \"Grant\", currencyId = \"Gold\", amount = \"10\" }\n",
		"\t\t\tlocal profile = recovered(prepared(ProfileSchema.new(), operation))\n",
		"\t\t\tprofile.pendingTransaction = ProfileSchema.readTransaction(operation)\n",
		"\t\t\tlocal result = recovered(profile)\n",
		"\t\t\texpectEqual(BigNum.toString(result.currencies.Gold), \"10\")\n",
		"\t\t\texpectNil(result.pendingTransaction)\n",
		"\t\t\texpectEqual(#result.transactions, 1)\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return { name = \"ProfileTransactionsTests\", tests = tests }\n",
	},
}
FILES[22] = {
	path = "ServerScriptService/Tests/ProgressionTests",
	className = "ModuleScript",
	bytes = 4170,
	lines = 128,
	adler32 = 3226287864,
	sha256 = "8d019e1c842334f5692c6debb59933268f50965678281beb33b6ccd814a9e953",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tProgressionTests\n",
		"\tLocation: ServerScriptService > Tests > ProgressionTests (ModuleScript)\n",
		"\n",
		"\tTap Damage upgrade curve, cost curve and config lookups.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectError = TestKit.expectError\n",
		"\n",
		"local tap = ProgressionConfig.TapDamageUpgrade\n",
		"\n",
		"local function damageText(level: number): string\n",
		"\treturn BigNum.toString(ProgressionConfig.GetUpgradeValue(tap, level))\n",
		"end\n",
		"\n",
		"local function costText(level: number): string\n",
		"\treturn BigNum.toString(ProgressionConfig.GetUpgradeCost(tap, level))\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"level 1 tap damage equals Milestone 1's starting damage\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectTrue(\n",
		"\t\t\t\tBigNum.eq(ProgressionConfig.GetUpgradeValue(tap, 1), BigNum.fromNumber(GameConfig.Combat.StartingTapDamage)),\n",
		"\t\t\t\t\"level 1 damage\"\n",
		"\t\t\t)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"tap damage curve: level x 3 every 25 levels\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal expected = {\n",
		"\t\t\t\t[1] = \"1\",\n",
		"\t\t\t\t[2] = \"2\",\n",
		"\t\t\t\t[24] = \"24\",\n",
		"\t\t\t\t[25] = \"75\",\n",
		"\t\t\t\t[26] = \"78\",\n",
		"\t\t\t\t[49] = \"147\",\n",
		"\t\t\t\t[50] = \"450\",\n",
		"\t\t\t\t[74] = \"666\",\n",
		"\t\t\t\t[75] = \"2025\",\n",
		"\t\t\t\t[100] = \"8100\",\n",
		"\t\t\t}\n",
		"\t\t\tfor level, text in expected do\n",
		"\t\t\t\texpectEqual(damageText(level), text, `damage at level {level}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"tap damage strictly increases with level\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal previous = ProgressionConfig.GetUpgradeValue(tap, 1)\n",
		"\t\t\tfor level = 2, 500 do\n",
		"\t\t\t\tlocal value = ProgressionConfig.GetUpgradeValue(tap, level)\n",
		"\t\t\t\texpectTrue(BigNum.gt(value, previous), `damage increases at level {level}`)\n",
		"\t\t\t\tprevious = value\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"cost curve: floor(5 x 1.07^(level - 1))\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal expected = { \"5\", \"5\", \"5\", \"6\", \"6\", \"7\", \"7\", \"8\", \"8\", \"9\" }\n",
		"\t\t\tfor level, text in expected do\n",
		"\t\t\t\texpectEqual(costText(level), text, `cost at level {level}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"costs never decrease and stay finite up to the max level\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal previous = ProgressionConfig.GetUpgradeCost(tap, 1)\n",
		"\t\t\tfor level = 2, 2000 do\n",
		"\t\t\t\tlocal cost = ProgressionConfig.GetUpgradeCost(tap, level)\n",
		"\t\t\t\texpectTrue(BigNum.gte(cost, previous), `cost does not decrease at level {level}`)\n",
		"\t\t\t\tprevious = cost\n",
		"\t\t\tend\n",
		"\t\t\tlocal topCost = ProgressionConfig.GetUpgradeCost(tap, tap.maxLevel)\n",
		"\t\t\texpectTrue(BigNum.isValid(topCost) and topCost.e > 308, \"cost at max level is a valid number beyond 1e308\")\n",
		"\t\t\tlocal topDamage = ProgressionConfig.GetUpgradeValue(tap, tap.maxLevel)\n",
		"\t\t\texpectTrue(BigNum.isValid(topDamage) and topDamage.e > 308, \"damage at max level is a valid number beyond 1e308\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"invalid levels are rejected\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tProgressionConfig.GetUpgradeValue(tap, 0)\n",
		"\t\t\tend, \"level 0\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tProgressionConfig.GetUpgradeValue(tap, 1.5)\n",
		"\t\t\tend, \"fractional level\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tProgressionConfig.GetUpgradeValue(tap, tap.maxLevel + 1)\n",
		"\t\t\tend, \"above max level\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tProgressionConfig.GetUpgradeCost(tap, -3)\n",
		"\t\t\tend, \"negative level\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"config lookups\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectTrue(ProgressionConfig.GetUpgrade(\"TapDamage\") ~= nil, \"TapDamage exists\")\n",
		"\t\t\texpectTrue(ProgressionConfig.GetUpgrade(\"NotAnUpgrade\") == nil, \"unknown upgrade\")\n",
		"\t\t\tlocal gold = ProgressionConfig.GetCurrency(ProgressionConfig.GoldCurrencyId)\n",
		"\t\t\texpectTrue(gold ~= nil and gold.startingBalance == 0, \"Gold exists and starts at 0\")\n",
		"\t\t\texpectTrue(ProgressionConfig.GetCurrency(\"PremiumGems\") == nil, \"no other currencies yet\")\n",
		"\t\t\texpectEqual(tap.currencyId, ProgressionConfig.GoldCurrencyId, \"Tap Damage is bought with Gold\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"ProgressionTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[23] = {
	path = "ServerScriptService/Tests/RateLimiterTests",
	className = "ModuleScript",
	bytes = 2042,
	lines = 65,
	adler32 = 2206831031,
	sha256 = "0a9b237905367c963dd3f83aefaf668295105de941f716c5d516e08c11ec1faa",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tRateLimiterTests\n",
		"\tLocation: ServerScriptService > Tests > RateLimiterTests (ModuleScript)\n",
		"\n",
		"\tToken bucket behavior with an injected clock, so results never depend on timing.\n",
		"]]\n",
		"\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local RateLimiter = require(ServerScriptService:WaitForChild(\"RateLimiter\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectTrue = TestKit.expectTrue\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"allows a burst, then refills at the configured rate\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal now = 0\n",
		"\t\t\tlocal limiter = RateLimiter.new(3, 2, function()\n",
		"\t\t\t\treturn now\n",
		"\t\t\tend)\n",
		"\t\t\texpectTrue(limiter:allow(\"a\") and limiter:allow(\"a\") and limiter:allow(\"a\"), \"burst of 3\")\n",
		"\t\t\texpectTrue(not limiter:allow(\"a\"), \"4th request in the same instant is refused\")\n",
		"\t\t\tnow = 0.5 -- 0.5 s x 2 per second = 1 token\n",
		"\t\t\texpectTrue(limiter:allow(\"a\"), \"one token after 0.5 s\")\n",
		"\t\t\texpectTrue(not limiter:allow(\"a\"), \"and only one\")\n",
		"\t\t\tnow = 100 -- refill caps at capacity\n",
		"\t\t\texpectTrue(limiter:allow(\"a\") and limiter:allow(\"a\") and limiter:allow(\"a\"), \"back to a full burst\")\n",
		"\t\t\texpectTrue(not limiter:allow(\"a\"), \"never more than capacity\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"keys are independent and can be forgotten\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal now = 0\n",
		"\t\t\tlocal limiter = RateLimiter.new(1, 1, function()\n",
		"\t\t\t\treturn now\n",
		"\t\t\tend)\n",
		"\t\t\texpectTrue(limiter:allow(\"a\"), \"a's first request\")\n",
		"\t\t\texpectTrue(not limiter:allow(\"a\"), \"a is limited\")\n",
		"\t\t\texpectTrue(limiter:allow(\"b\"), \"b is not affected by a\")\n",
		"\t\t\tlimiter:remove(\"a\")\n",
		"\t\t\texpectTrue(limiter:allow(\"a\"), \"a starts fresh after remove\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a clock that goes backwards never grants extra tokens\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal now = 10\n",
		"\t\t\tlocal limiter = RateLimiter.new(1, 1, function()\n",
		"\t\t\t\treturn now\n",
		"\t\t\tend)\n",
		"\t\t\texpectTrue(limiter:allow(\"a\"), \"first request\")\n",
		"\t\t\tnow = 5\n",
		"\t\t\texpectTrue(not limiter:allow(\"a\"), \"no refill from negative elapsed time\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"RateLimiterTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[24] = {
	path = "ServerScriptService/Tests/StatRulesTests",
	className = "ModuleScript",
	bytes = 12309,
	lines = 264,
	adler32 = 3037874736,
	sha256 = "89c1e4a423e7e026f964b3cb3fe1151b154b7e532ff6ddc3ee2e9f6e659bc88a",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tStatRulesTests\n",
		"\tLocation: ServerScriptService > Tests > StatRulesTests (ModuleScript)\n",
		"\n",
		"\tMilestone 2.1 (DECISIONS.md decision 1): stat combination by source.\n",
		"\t- No modifiers: the combined value is exactly the base, so Milestone 2 tap damage is unchanged.\n",
		"\t- Stacking: flat bonuses, then summed percentages, then multipliers, rounded down once.\n",
		"\t- Modifiers are grouped by source and id; the result does not depend on insertion order.\n",
		"\t- Invalid input is rejected without changing the sheet.\n",
		"\tExact-string expectations use values that are exact in binary (0.25, 0.5, 1.5, 2).\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local StatRules = require(ServerScriptService:WaitForChild(\"StatRules\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectNil = TestKit.expectNil\n",
		"\n",
		"local TAP = StatRules.Stats.TapDamage\n",
		"\n",
		"local function n(value: number): BigNum\n",
		"\treturn BigNum.fromNumber(value)\n",
		"end\n",
		"\n",
		"local function p(text: string): BigNum\n",
		"\tlocal value = BigNum.parse(text)\n",
		"\tif value == nil then\n",
		"\t\terror(`test setup: could not parse \"{text}\"`, 2)\n",
		"\tend\n",
		"\treturn value\n",
		"end\n",
		"\n",
		"local function combined(sheet: StatRules.Sheet): string\n",
		"\tlocal value = StatRules.combine(sheet, TAP)\n",
		"\tif value == nil then\n",
		"\t\treturn \"nil\"\n",
		"\tend\n",
		"\treturn BigNum.toString(value)\n",
		"end\n",
		"\n",
		"local function sheetWithBase(value: BigNum): StatRules.Sheet\n",
		"\tlocal sheet = StatRules.newSheet()\n",
		"\texpectTrue(StatRules.setBase(sheet, TAP, value), \"setBase accepts a valid value\")\n",
		"\treturn sheet\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"with no modifiers the combined value is exactly the base\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal tap = ProgressionConfig.TapDamageUpgrade\n",
		"\t\t\tfor _, level in { 1, 2, 24, 25, 26, 100, 510, 1000, 100000 } do\n",
		"\t\t\t\tlocal base = ProgressionConfig.GetUpgradeValue(tap, level)\n",
		"\t\t\t\tlocal value = StatRules.combine(sheetWithBase(base), TAP)\n",
		"\t\t\t\texpectTrue(value ~= nil and BigNum.eq(value, base), `level {level}: combined equals the upgrade value`)\n",
		"\t\t\t\texpectEqual(combined(sheetWithBase(base)), BigNum.toString(base), `level {level}: same canonical text`)\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(combined(sheetWithBase(p(\"1.5e400\"))), \"1.5e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a stat without a base has no combined value\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = StatRules.newSheet()\n",
		"\t\t\texpectNil(StatRules.combine(sheet, TAP))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { flat = n(5) }), \"a modifier can wait for the base\")\n",
		"\t\t\texpectNil(StatRules.combine(sheet, TAP))\n",
		"\t\t\texpectTrue(StatRules.setBase(sheet, TAP, n(10)))\n",
		"\t\t\texpectEqual(combined(sheet), \"15\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"flat bonuses, then summed percentages, then multipliers\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(10))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"equipment\", \"sword\", { flat = n(6) }))\n",
		"\t\t\texpectEqual(combined(sheet), \"16\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { percent = 0.25 }))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"p1\", { percent = 0.25 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"24\", \"(10 + 6) * (1 + 0.25 + 0.25): percentages are summed, not compounded\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"upgrade\", \"u1\", { multiplier = 2 }))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h2\", { multiplier = 1.5 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"72\", \"24 * 2 * 1.5: multipliers multiply\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"the result is rounded down once, at the end\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(1))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { percent = 0.5 }))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"p1\", { multiplier = 1.5 }))\n",
		"\t\t\t-- 1 * 1.5 * 1.5 = 2.25 -> 2. Rounding after each step would give floor(floor(1.5) * 1.5) = 1.\n",
		"\t\t\texpectEqual(combined(sheet), \"2\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"tap damage never drops below 1\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(1))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"p1\", { multiplier = 0.5 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"1\", \"0.5 rounds down to 0 but tap damage stays positive\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"modifiers are grouped by source and id; the same id replaces, never stacks\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(10))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"bonus\", { flat = n(5) }))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"equipment\", \"bonus\", { flat = n(5) }))\n",
		"\t\t\texpectEqual(combined(sheet), \"20\", \"the same id in two sources counts twice\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"bonus\", { flat = n(7) }))\n",
		"\t\t\texpectEqual(combined(sheet), \"22\", \"setting hero/bonus again replaces it\")\n",
		"\t\t\texpectEqual(StatRules.countModifiers(sheet, TAP), 2)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"removing every modifier restores the exact base\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal base = ProgressionConfig.GetUpgradeValue(ProgressionConfig.TapDamageUpgrade, 25)\n",
		"\t\t\tlocal sheet = sheetWithBase(base)\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { percent = 0.5, flat = n(3) }))\n",
		"\t\t\texpectEqual(combined(sheet), \"117\", \"(75 + 3) * 1.5\")\n",
		"\t\t\texpectTrue(StatRules.removeModifier(sheet, TAP, \"hero\", \"h1\"), \"removal reports an existing modifier\")\n",
		"\t\t\texpectTrue(not StatRules.removeModifier(sheet, TAP, \"hero\", \"h1\"), \"removing twice reports false\")\n",
		"\t\t\texpectEqual(StatRules.countModifiers(sheet, TAP), 0)\n",
		"\t\t\tlocal value = StatRules.combine(sheet, TAP)\n",
		"\t\t\texpectTrue(value ~= nil and BigNum.eq(value, base), \"back to exactly the upgrade value (75)\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"the result does not depend on the order modifiers were added\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal modifiers: { { source: StatRules.Source, id: string, modifier: StatRules.Modifier } } = {\n",
		"\t\t\t\t{ source = \"perk\", id = \"p\", modifier = { multiplier = 1.5 } },\n",
		"\t\t\t\t{ source = \"upgrade\", id = \"u\", modifier = { flat = n(3), percent = 0.25 } },\n",
		"\t\t\t\t{ source = \"hero\", id = \"h\", modifier = { percent = 0.5, multiplier = 2 } },\n",
		"\t\t\t\t{ source = \"equipment\", id = \"e\", modifier = { flat = n(1) } },\n",
		"\t\t\t}\n",
		"\t\t\tlocal forward = sheetWithBase(n(12))\n",
		"\t\t\tfor index = 1, #modifiers do\n",
		"\t\t\t\tlocal entry = modifiers[index]\n",
		"\t\t\t\texpectTrue(StatRules.setModifier(forward, TAP, entry.source, entry.id, entry.modifier))\n",
		"\t\t\tend\n",
		"\t\t\tlocal backward = sheetWithBase(n(12))\n",
		"\t\t\tfor index = #modifiers, 1, -1 do\n",
		"\t\t\t\tlocal entry = modifiers[index]\n",
		"\t\t\t\texpectTrue(StatRules.setModifier(backward, TAP, entry.source, entry.id, entry.modifier))\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(combined(forward), combined(backward))\n",
		"\t\t\texpectEqual(combined(forward), \"84\", \"(12 + 3 + 1) * (1 + 0.25 + 0.5) * 2 * 1.5\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"large values combine without overflow\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(p(\"1e400\"))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { percent = 0.5 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"1.5e400\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"p1\", { multiplier = 1e300 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"1.5e700\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"equipment\", \"e1\", { flat = n(5) }))\n",
		"\t\t\texpectEqual(combined(sheet), \"1.5e700\", \"a flat 5 is absorbed at 1e400 (bounded precision contract)\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"invalid stats, sources, ids and modifiers are rejected without changing the sheet\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(10))\n",
		"\t\t\tlocal bad: { { label: string, ok: boolean } } = {\n",
		"\t\t\t\t{ label = \"unknown stat\", ok = StatRules.setModifier(sheet, \"Speed\", \"hero\", \"h\", { flat = n(1) }) },\n",
		"\t\t\t\t{ label = \"unknown source\", ok = StatRules.setModifier(sheet, TAP, \"pet\" :: any, \"h\", { flat = n(1) }) },\n",
		"\t\t\t\t{ label = \"empty id\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"\", { flat = n(1) }) },\n",
		"\t\t\t\t{ label = \"non-string id\", ok = StatRules.setModifier(sheet, TAP, \"hero\", 7 :: any, { flat = n(1) }) },\n",
		"\t\t\t\t{ label = \"empty modifier\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", {}) },\n",
		"\t\t\t\t{ label = \"unknown field\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { bonus = 1 } :: any) },\n",
		"\t\t\t\t{ label = \"flat is not a BigNum\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { flat = 5 :: any }) },\n",
		"\t\t\t\t{ label = \"negative percent\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { percent = -0.25 }) },\n",
		"\t\t\t\t{ label = \"NaN percent\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { percent = 0 / 0 }) },\n",
		"\t\t\t\t{ label = \"zero multiplier\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { multiplier = 0 }) },\n",
		"\t\t\t\t{ label = \"negative multiplier\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { multiplier = -2 }) },\n",
		"\t\t\t\t{ label = \"infinite multiplier\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", { multiplier = math.huge }) },\n",
		"\t\t\t\t{ label = \"modifier is not a table\", ok = StatRules.setModifier(sheet, TAP, \"hero\", \"h\", 3 :: any) },\n",
		"\t\t\t\t{ label = \"invalid base\", ok = StatRules.setBase(sheet, TAP, { m = -1, e = 0 } :: any) },\n",
		"\t\t\t\t{ label = \"base for an unknown stat\", ok = StatRules.setBase(sheet, \"Speed\", n(1)) },\n",
		"\t\t\t}\n",
		"\t\t\tfor _, case in bad do\n",
		"\t\t\t\texpectTrue(not case.ok, `{case.label} is rejected`)\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(StatRules.countModifiers(sheet, TAP), 0, \"no modifier was stored\")\n",
		"\t\t\texpectEqual(combined(sheet), \"10\", \"the base is unchanged\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"stored modifiers are copies the caller cannot change\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(10))\n",
		"\t\t\tlocal modifier: StatRules.Modifier = { flat = n(5) }\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", modifier))\n",
		"\t\t\tmodifier.flat = n(500)\n",
		"\t\t\texpectEqual(combined(sheet), \"15\", \"editing the caller's table after setModifier changes nothing\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a multiplier and its inverse cancel even at the largest exponent\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- The factors are combined before the sum is multiplied, so x2 then x0.5 never overflows on the way.\n",
		"\t\t\tlocal sheet = sheetWithBase(n(1))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"equipment\", \"huge\", { flat = p(\"9e9007199254740991\") }))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"double\", { multiplier = 2 }) and true)\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"half\", { multiplier = 0.5 }))\n",
		"\t\t\texpectEqual(combined(sheet), \"9e9007199254740991\", \"hero x2 (applied first by source order) and perk x0.5 cancel\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"copySheet makes an independent copy\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal sheet = sheetWithBase(n(10))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"hero\", \"h1\", { flat = n(5) }))\n",
		"\t\t\tlocal copy = StatRules.copySheet(sheet)\n",
		"\t\t\texpectTrue(StatRules.setModifier(copy, TAP, \"hero\", \"h2\", { multiplier = 2 }))\n",
		"\t\t\texpectTrue(StatRules.removeModifier(copy, TAP, \"hero\", \"h1\"))\n",
		"\t\t\texpectTrue(StatRules.setBase(copy, TAP, n(40)))\n",
		"\t\t\texpectEqual(combined(copy), \"80\")\n",
		"\t\t\texpectEqual(combined(sheet), \"15\", \"the original keeps its base and its modifiers\")\n",
		"\t\t\texpectEqual(StatRules.countModifiers(sheet, TAP), 1)\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"combining past the largest exponent raises BigNum's overflow error\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- StatService catches this and keeps the previous sheet and tap damage (DEFECT regression for M2.1).\n",
		"\t\t\tlocal sheet = sheetWithBase(n(1))\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"equipment\", \"huge\", { flat = p(\"9e9007199254740991\") }))\n",
		"\t\t\texpectEqual(combined(sheet), \"9e9007199254740991\", \"the flat bonus alone is still representable\")\n",
		"\t\t\texpectTrue(StatRules.setModifier(sheet, TAP, \"perk\", \"double\", { multiplier = 2 }))\n",
		"\t\t\tlocal ok, problem = pcall(StatRules.combine, sheet, TAP)\n",
		"\t\t\texpectTrue(not ok and string.find(tostring(problem), \"overflow\", 1, true) ~= nil, \"x2 overflows the exponent\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"separate sheets are independent\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal first = sheetWithBase(n(10))\n",
		"\t\t\tlocal second = sheetWithBase(n(10))\n",
		"\t\t\texpectTrue(StatRules.setModifier(first, TAP, \"hero\", \"h1\", { multiplier = 2 }))\n",
		"\t\t\texpectEqual(combined(first), \"20\")\n",
		"\t\t\texpectEqual(combined(second), \"10\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"StatRulesTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[25] = {
	path = "ServerScriptService/Tests/TestKit",
	className = "ModuleScript",
	bytes = 4287,
	lines = 138,
	adler32 = 3224874915,
	sha256 = "da6a4882d5177dc5537871a3aff302b2692e0fcd293e18f4993f6b763ccea969",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tTestKit\n",
		"\tLocation: ServerScriptService > Tests > TestKit (ModuleScript)\n",
		"\n",
		"\tMinimal assertions and a runner for deterministic unit tests. No external\n",
		"\tframework. Each test module returns a Suite; TestRunner runs them in Studio.\n",
		"]]\n",
		"\n",
		"export type TestCase = {\n",
		"\tname: string,\n",
		"\trun: () -> (),\n",
		"}\n",
		"\n",
		"export type Suite = {\n",
		"\tname: string,\n",
		"\ttests: { TestCase },\n",
		"}\n",
		"\n",
		"local TestKit = {}\n",
		"\n",
		"local function describe(value: unknown): string\n",
		"\tif typeof(value) == \"string\" then\n",
		"\t\treturn `\"{value}\"`\n",
		"\tend\n",
		"\treturn tostring(value)\n",
		"end\n",
		"\n",
		"function TestKit.expectEqual(actual: unknown, expected: unknown, label: string?)\n",
		"\tif actual ~= expected then\n",
		"\t\terror(`{label or \"expectEqual\"}: expected {describe(expected)}, got {describe(actual)}`, 2)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function TestKit.expectTrue(condition: boolean, label: string?)\n",
		"\tif not condition then\n",
		"\t\terror(`{label or \"expectTrue\"}: condition was false`, 2)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function TestKit.expectNil(value: unknown, label: string?)\n",
		"\tif value ~= nil then\n",
		"\t\terror(`{label or \"expectNil\"}: expected nil, got {describe(value)}`, 2)\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- NaN never passes, and the tolerance must be a finite number >= 0. Equal infinities pass.\n",
		"function TestKit.expectNear(actual: number, expected: number, tolerance: number, label: string?)\n",
		"\tlocal name = label or \"expectNear\"\n",
		"\tif typeof(tolerance) ~= \"number\" or tolerance ~= tolerance or tolerance < 0 or tolerance == math.huge then\n",
		"\t\terror(`{name}: invalid tolerance {tolerance}`, 2)\n",
		"\tend\n",
		"\tif typeof(actual) ~= \"number\" or typeof(expected) ~= \"number\" or actual ~= actual or expected ~= expected then\n",
		"\t\terror(`{name}: expected {expected} \194\177 {tolerance}, got {actual} (NaN or not a number)`, 2)\n",
		"\tend\n",
		"\t-- Written so that NaN (from opposite infinities) fails the check instead of slipping through.\n",
		"\tif actual ~= expected and not (math.abs(actual - expected) <= tolerance) then\n",
		"\t\terror(`{name}: expected {expected} \194\177 {tolerance}, got {actual}`, 2)\n",
		"\tend\n",
		"end\n",
		"\n",
		"function TestKit.expectError(callback: () -> (), label: string?)\n",
		"\tlocal ok = pcall(callback)\n",
		"\tif ok then\n",
		"\t\terror(`{label or \"expectError\"}: expected an error, but none was raised`, 2)\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- True for a value shaped like a Suite. TestRunner uses it to reject test modules that return anything else.\n",
		"function TestKit.isSuite(value: unknown): boolean\n",
		"\tif typeof(value) ~= \"table\" then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal suite: any = value\n",
		"\tif typeof(suite.name) ~= \"string\" or typeof(suite.tests) ~= \"table\" then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tfor _, test in suite.tests do\n",
		"\t\tif typeof(test) ~= \"table\" or typeof(test.name) ~= \"string\" or typeof(test.run) ~= \"function\" then\n",
		"\t\t\treturn false\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Receives each output line; problem lines go to warn. Tests pass their own to run suites quietly.\n",
		"export type Reporter = (isProblem: boolean, message: string) -> ()\n",
		"\n",
		"local function defaultReporter(isProblem: boolean, message: string)\n",
		"\tif isProblem then\n",
		"\t\twarn(message)\n",
		"\telse\n",
		"\t\tprint(message)\n",
		"\tend\n",
		"end\n",
		"\n",
		"--[[\n",
		"\tRuns every test in every suite, prints one line per suite and a final verdict.\n",
		"\tEach entry in loadFailures (a test module that could not be loaded) counts as a\n",
		"\tfailure, and a run with no tests at all fails, so a broken or missing suite can\n",
		"\tnever produce \"ALL PASSED\". Returns (passed, failed).\n",
		"]]\n",
		"function TestKit.runSuites(suites: { Suite }, loadFailures: { string }?, reporter: Reporter?): (number, number)\n",
		"\tlocal report = reporter or defaultReporter\n",
		"\tlocal failures: { string } = loadFailures or {}\n",
		"\tlocal passed, failed = 0, 0\n",
		"\tfor _, problem in failures do\n",
		"\t\tfailed += 1\n",
		"\t\treport(true, `[Tests] FAIL could not load {problem}`)\n",
		"\tend\n",
		"\tfor _, suite in suites do\n",
		"\t\tlocal suitePassed, suiteFailed = 0, 0\n",
		"\t\tfor _, test in suite.tests do\n",
		"\t\t\tlocal ok, problem = pcall(test.run)\n",
		"\t\t\tif ok then\n",
		"\t\t\t\tsuitePassed += 1\n",
		"\t\t\telse\n",
		"\t\t\t\tsuiteFailed += 1\n",
		"\t\t\t\treport(true, `[Tests] FAIL {suite.name} > {test.name}: {problem}`)\n",
		"\t\t\tend\n",
		"\t\tend\n",
		"\t\treport(false, `[Tests] {suite.name}: {suitePassed} passed, {suiteFailed} failed`)\n",
		"\t\tpassed += suitePassed\n",
		"\t\tfailed += suiteFailed\n",
		"\tend\n",
		"\tif passed + failed == 0 then\n",
		"\t\tfailed = 1\n",
		"\t\treport(true, \"[Tests] FAIL no tests ran\")\n",
		"\tend\n",
		"\tif failed == 0 then\n",
		"\t\treport(false, `[Tests] ALL PASSED ({passed} tests)`)\n",
		"\telse\n",
		"\t\treport(true, `[Tests] {failed} FAILED, {passed} passed`)\n",
		"\tend\n",
		"\treturn passed, failed\n",
		"end\n",
		"\n",
		"return table.freeze(TestKit)\n",
	},
}
FILES[26] = {
	path = "ServerScriptService/Tests/TestKitTests",
	className = "ModuleScript",
	bytes = 4545,
	lines = 151,
	adler32 = 991929235,
	sha256 = "74454d4a387afc7c9f7eecbf801506c9fb089528298c3ee4c64b1bc200198bd0",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tTestKitTests\n",
		"\tLocation: ServerScriptService > Tests > TestKitTests (ModuleScript)\n",
		"\n",
		"\tTests for the test kit itself, from the Milestone 2 Codex audit: an\n",
		"\tapproximate assertion must never pass on NaN (F6), and a suite that fails to\n",
		"\tload, or a run with no tests, must never be reported as ALL PASSED (F3).\n",
		"\tSuites run here use a quiet reporter, so they print nothing.\n",
		"]]\n",
		"\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectError = TestKit.expectError\n",
		"local expectNear = TestKit.expectNear\n",
		"\n",
		"local NAN = 0 / 0\n",
		"\n",
		"-- Runs suites without printing and returns (passed, failed, every reported line).\n",
		"local function runQuietly(suites: { TestKit.Suite }, loadFailures: { string }?): (number, number, { string })\n",
		"\tlocal lines: { string } = {}\n",
		"\tlocal passed, failed = TestKit.runSuites(suites, loadFailures, function(_isProblem: boolean, message: string)\n",
		"\t\ttable.insert(lines, message)\n",
		"\tend)\n",
		"\treturn passed, failed, lines\n",
		"end\n",
		"\n",
		"local function reportedAllPassed(lines: { string }): boolean\n",
		"\tfor _, line in lines do\n",
		"\t\tif string.find(line, \"ALL PASSED\", 1, true) then\n",
		"\t\t\treturn true\n",
		"\t\tend\n",
		"\tend\n",
		"\treturn false\n",
		"end\n",
		"\n",
		"local passingSuite: TestKit.Suite = {\n",
		"\tname = \"PassingTests\",\n",
		"\ttests = {\n",
		"\t\t{ name = \"passes\", run = function() end },\n",
		"\t},\n",
		"}\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"expectNear accepts values within the tolerance\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectNear(1, 1.05, 0.1)\n",
		"\t\t\texpectNear(5, 5, 0)\n",
		"\t\t\texpectNear(-2, -2.5, 0.5)\n",
		"\t\t\texpectNear(math.huge, math.huge, 0, \"equal infinities\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"expectNear never passes on NaN\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(NAN, 123, 0)\n",
		"\t\t\tend, \"NaN actual\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(123, NAN, 0)\n",
		"\t\t\tend, \"NaN expected\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(NAN, NAN, 1)\n",
		"\t\t\tend, \"both NaN\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(math.huge, -math.huge, 1)\n",
		"\t\t\tend, \"opposite infinities (their difference is NaN)\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(math.huge, 5, 1e300)\n",
		"\t\t\tend, \"infinity is not near a finite value\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(5, 7, 1)\n",
		"\t\t\tend, \"plain mismatch\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"expectNear rejects invalid tolerances\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(1, 1, NAN)\n",
		"\t\t\tend, \"NaN tolerance\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(1, 1, -1)\n",
		"\t\t\tend, \"negative tolerance\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\texpectNear(1, 2, math.huge)\n",
		"\t\t\tend, \"infinite tolerance\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a suite that failed to load is a failure, never ALL PASSED\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal passed, failed, lines = runQuietly({ passingSuite }, { \"BrokenTests: boom\" })\n",
		"\t\t\texpectEqual(passed, 1, \"the loaded suite still runs\")\n",
		"\t\t\texpectEqual(failed, 1, \"the load failure is counted\")\n",
		"\t\t\texpectTrue(not reportedAllPassed(lines), \"no ALL PASSED line\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"a run with no tests is a failure\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal passed, failed, lines = runQuietly({})\n",
		"\t\t\texpectEqual(passed, 0)\n",
		"\t\t\texpectEqual(failed, 1, \"an empty run fails\")\n",
		"\t\t\texpectTrue(not reportedAllPassed(lines), \"no ALL PASSED line for an empty run\")\n",
		"\t\t\tlocal _, emptySuiteFailed = runQuietly({ { name = \"EmptyTests\", tests = {} } })\n",
		"\t\t\texpectEqual(emptySuiteFailed, 1, \"a suite with no tests also fails\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"failing tests are counted and reported\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal failing: TestKit.Suite = {\n",
		"\t\t\t\tname = \"FailingTests\",\n",
		"\t\t\t\ttests = {\n",
		"\t\t\t\t\t{\n",
		"\t\t\t\t\t\tname = \"fails\",\n",
		"\t\t\t\t\t\trun = function()\n",
		"\t\t\t\t\t\t\terror(\"expected failure\")\n",
		"\t\t\t\t\t\tend,\n",
		"\t\t\t\t\t},\n",
		"\t\t\t\t},\n",
		"\t\t\t}\n",
		"\t\t\tlocal passed, failed, lines = runQuietly({ passingSuite, failing })\n",
		"\t\t\texpectEqual(passed, 1)\n",
		"\t\t\texpectEqual(failed, 1)\n",
		"\t\t\texpectTrue(not reportedAllPassed(lines), \"no ALL PASSED line\")\n",
		"\t\t\tlocal _, _, cleanLines = runQuietly({ passingSuite })\n",
		"\t\t\texpectTrue(reportedAllPassed(cleanLines), \"a clean run still reports ALL PASSED\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"isSuite rejects modules that do not return a suite\",\n",
		"\t\trun = function()\n",
		"\t\t\texpectTrue(TestKit.isSuite(passingSuite), \"a real suite\")\n",
		"\t\t\texpectTrue(not TestKit.isSuite(42), \"a number\")\n",
		"\t\t\texpectTrue(not TestKit.isSuite(nil), \"nil\")\n",
		"\t\t\texpectTrue(not TestKit.isSuite({}), \"an empty table\")\n",
		"\t\t\texpectTrue(not TestKit.isSuite({ name = \"X\", tests = { { name = \"no run function\" } } }), \"a test without run\")\n",
		"\t\t\texpectTrue(not TestKit.isSuite({ name = \"X\", tests = \"not a list\" }), \"tests is not a table\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"TestKitTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[27] = {
	path = "ServerScriptService/Tests/TestRunner",
	className = "Script",
	bytes = 1574,
	lines = 45,
	adler32 = 1141053416,
	sha256 = "e3a24f14a5a5a14bd9838502eea7a5b8111480e596a2c894db0701af6b96c512",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tTestRunner\n",
		"\tLocation: ServerScriptService > Tests > TestRunner (Script)\n",
		"\n",
		"\tRuns every ModuleScript in this folder whose name ends in \"Tests\" when you\n",
		"\tpress Play in Studio. Never runs in live game servers. Results appear in the\n",
		"\tOutput window: one line per suite, then \"ALL PASSED\" or the failures. A test\n",
		"\tmodule that cannot be loaded counts as a failure, and so does a run with no tests.\n",
		"\tSet RUN_TESTS_IN_STUDIO to false to skip them.\n",
		"]]\n",
		"\n",
		"local RunService = game:GetService(\"RunService\")\n",
		"\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"local RUN_TESTS_IN_STUDIO = true\n",
		"\n",
		"if RUN_TESTS_IN_STUDIO and RunService:IsStudio() then\n",
		"\tlocal testModules: { ModuleScript } = {}\n",
		"\tfor _, child in script.Parent:GetChildren() do\n",
		"\t\tif child:IsA(\"ModuleScript\") and string.match(child.Name, \"Tests$\") then\n",
		"\t\t\ttable.insert(testModules, child)\n",
		"\t\tend\n",
		"\tend\n",
		"\ttable.sort(testModules, function(a: ModuleScript, b: ModuleScript)\n",
		"\t\treturn a.Name < b.Name\n",
		"\tend)\n",
		"\n",
		"\tlocal suites: { TestKit.Suite } = {}\n",
		"\tlocal loadFailures: { string } = {}\n",
		"\tfor _, moduleScript in testModules do\n",
		"\t\tlocal ok, suiteOrError = pcall(require, moduleScript)\n",
		"\t\tif ok and TestKit.isSuite(suiteOrError) then\n",
		"\t\t\ttable.insert(suites, suiteOrError :: TestKit.Suite)\n",
		"\t\telseif ok then\n",
		"\t\t\ttable.insert(loadFailures, `{moduleScript.Name}: did not return a test suite`)\n",
		"\t\telse\n",
		"\t\t\ttable.insert(loadFailures, `{moduleScript.Name}: {suiteOrError}`)\n",
		"\t\tend\n",
		"\tend\n",
		"\n",
		"\t-- Load failures count as failures, and an empty run fails, so the verdict is never a false pass.\n",
		"\tTestKit.runSuites(suites, loadFailures)\n",
		"end\n",
	},
}
FILES[28] = {
	path = "ServerScriptService/Tests/WalletTests",
	className = "ModuleScript",
	bytes = 8091,
	lines = 194,
	adler32 = 4028171145,
	sha256 = "1ea7bc80054c9be9e0a1ed50ba3f04d0e4b4be48b77ebd23e77ec1fe4548b9f8",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tWalletTests\n",
		"\tLocation: ServerScriptService > Tests > WalletTests (ModuleScript)\n",
		"\n",
		"\tBalance rules: exact grants, all-or-nothing spends, no negative balances,\n",
		"\tindependent currencies, and a rapid purchase sequence that mirrors\n",
		"\tUpgradeService's transaction (spend, then raise the level by one).\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local Wallet = require(ServerScriptService:WaitForChild(\"Wallet\"))\n",
		"local TestKit = require(script.Parent:WaitForChild(\"TestKit\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"local expectEqual = TestKit.expectEqual\n",
		"local expectTrue = TestKit.expectTrue\n",
		"local expectError = TestKit.expectError\n",
		"\n",
		"local GOLD = ProgressionConfig.GoldCurrencyId\n",
		"\n",
		"local function n(value: number): BigNum\n",
		"\treturn BigNum.fromNumber(value)\n",
		"end\n",
		"\n",
		"local function balanceText(wallet: Wallet.Wallet, currencyId: string): string\n",
		"\treturn BigNum.toString(Wallet.get(wallet, currencyId))\n",
		"end\n",
		"\n",
		"local tests: { TestKit.TestCase } = {\n",
		"\t{\n",
		"\t\tname = \"a new wallet holds its starting balances\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(0) })\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"0\")\n",
		"\t\t\texpectTrue(Wallet.has(wallet, GOLD), \"has Gold\")\n",
		"\t\t\texpectTrue(not Wallet.has(wallet, \"PremiumGems\"), \"has no other currency\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"grants add exactly\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(0) })\n",
		"\t\t\texpectTrue(Wallet.grant(wallet, GOLD, n(5)), \"grant 5\")\n",
		"\t\t\texpectTrue(Wallet.grant(wallet, GOLD, n(7)), \"grant 7\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"12\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"spends succeed only when the whole amount is available\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(10) })\n",
		"\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, n(3)), \"spend 3 of 10\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"7\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, GOLD, n(8)), \"spend 8 of 7 is refused\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"7\", \"a refused spend changes nothing\")\n",
		"\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, n(7)), \"spend the exact balance\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"0\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, GOLD, n(1)), \"nothing left to spend\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"0\", \"never negative\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"invalid amounts and unknown currencies change nothing\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(10) })\n",
		"\t\t\tlocal invalid: any = { m = -1, e = 0 }\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, GOLD, BigNum.zero), \"zero grant\")\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, GOLD, invalid), \"malformed grant\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, GOLD, invalid), \"malformed spend\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, GOLD, BigNum.zero), \"zero spend\")\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, \"PremiumGems\", n(5)), \"unknown currency grant\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, \"PremiumGems\", n(5)), \"unknown currency spend\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"10\", \"Gold unchanged\")\n",
		"\t\t\texpectError(function()\n",
		"\t\t\t\tWallet.get(wallet, \"PremiumGems\")\n",
		"\t\t\tend, \"reading an unknown currency\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"currencies are independent\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(10), TestTickets = n(3) })\n",
		"\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, n(10)), \"spend all Gold\")\n",
		"\t\t\texpectEqual(balanceText(wallet, \"TestTickets\"), \"3\", \"tickets untouched\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, GOLD, n(1)), \"Gold cannot borrow from tickets\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"huge balances\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(0) })\n",
		"\t\t\texpectTrue(Wallet.grant(wallet, GOLD, BigNum.parse(\"1.5e400\") :: BigNum), \"grant 1.5e400\")\n",
		"\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, BigNum.parse(\"5e399\") :: BigNum), \"spend 5e399\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"1e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"rapid purchases never overdraw and each charge buys exactly one level\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal tap = ProgressionConfig.TapDamageUpgrade\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(1000) })\n",
		"\t\t\tlocal level = tap.startingLevel\n",
		"\t\t\tlocal totalSpent = BigNum.zero\n",
		"\t\t\t-- 100 back-to-back requests, more than the balance can pay for.\n",
		"\t\t\tfor _ = 1, 100 do\n",
		"\t\t\t\tlocal cost = ProgressionConfig.GetUpgradeCost(tap, level)\n",
		"\t\t\t\tif Wallet.trySpend(wallet, GOLD, cost) then\n",
		"\t\t\t\t\tlevel += 1\n",
		"\t\t\t\t\ttotalSpent = BigNum.add(totalSpent, cost)\n",
		"\t\t\t\tend\n",
		"\t\t\t\texpectTrue(BigNum.isValid(Wallet.get(wallet, GOLD)), \"balance stays valid\")\n",
		"\t\t\tend\n",
		"\t\t\texpectEqual(level, 41, \"1000 Gold buys exactly 40 levels\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"19\", \"19 Gold left over\")\n",
		"\t\t\texpectEqual(BigNum.toString(BigNum.add(totalSpent, Wallet.get(wallet, GOLD))), \"1000\", \"spent + left = starting Gold\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t-- Regression tests for Milestone 2 Codex audit finding F1 (subtraction precision near 2^53).\n",
		"\t{\n",
		"\t\tname = \"spending across 2^53 leaves an exact whole balance\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- This purchase used to leave 4485383672432620.5 Gold.\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(9007199254740992) })\n",
		"\t\t\tlocal cost = ProgressionConfig.GetUpgradeCost(ProgressionConfig.TapDamageUpgrade, 510)\n",
		"\t\t\texpectEqual(BigNum.toString(cost), \"4521815582308372\", \"level 510 cost\")\n",
		"\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, cost), \"affordable\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"4485383672432620\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"Gold is conserved when a balance crosses 2^53 and is spent back below it\",\n",
		"\t\trun = function()\n",
		"\t\t\t-- Seeded. Balances above 2^53 are kept even: doubles there hold only even whole numbers.\n",
		"\t\t\tlocal rng = Random.new(510)\n",
		"\t\t\tfor _ = 1, 200 do\n",
		"\t\t\t\tlocal start = 9007199254740992 - 2 * rng:NextInteger(1, 1000000) -- even, below 2^53\n",
		"\t\t\t\tlocal granted = 2 * rng:NextInteger(1100000, 2000000) -- lifts the balance at least 200000 above 2^53\n",
		"\t\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(start) })\n",
		"\t\t\t\texpectTrue(Wallet.grant(wallet, GOLD, n(granted)), \"grant\")\n",
		"\t\t\t\tlocal spent = 0\n",
		"\t\t\t\tfor _ = 1, 3 do -- at most 180000 in total, so the balance stays above 2^53\n",
		"\t\t\t\t\tlocal cost = 2 * rng:NextInteger(1, 30000)\n",
		"\t\t\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, n(cost)), \"spend above 2^53\")\n",
		"\t\t\t\t\texpectTrue(Wallet.get(wallet, GOLD).e > 0, \"the balance is still above 2^53\")\n",
		"\t\t\t\t\tspent += cost\n",
		"\t\t\t\tend\n",
		"\t\t\t\t-- One more spend lands on start - 1: an odd balance below 2^53, which must be exact.\n",
		"\t\t\t\tlocal back = granted - spent + 1\n",
		"\t\t\t\texpectTrue(Wallet.trySpend(wallet, GOLD, n(back)), \"spend back below 2^53\")\n",
		"\t\t\t\texpectEqual(balanceText(wallet, GOLD), tostring(start - 1), `start {start}, granted {granted}, spent {spent + back}`)\n",
		"\t\t\tend\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"snapshot lists every balance as canonical text\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = n(42), TestTickets = BigNum.parse(\"1.5e400\") :: BigNum })\n",
		"\t\t\tlocal snapshot = Wallet.snapshot(wallet)\n",
		"\t\t\texpectEqual(snapshot[GOLD], \"42\")\n",
		"\t\t\texpectEqual(snapshot.TestTickets, \"1.5e400\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"whole-number wallets enforce amounts and caps atomically\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal wallet = Wallet.new({ Gems = n(10), Crowns = n(9007199254740991) })\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, \"Gems\", n(0.5)), \"fractional grant rejected\")\n",
		"\t\t\texpectTrue(not Wallet.trySpend(wallet, \"Gems\", n(0.5)), \"fractional spend rejected\")\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, \"Crowns\", n(1)), \"cap protected\")\n",
		"\t\t\texpectEqual(balanceText(wallet, \"Gems\"), \"10\")\n",
		"\t\t\texpectEqual(balanceText(wallet, \"Crowns\"), \"9007199254740991\")\n",
		"\t\tend,\n",
		"\t},\n",
		"\t{\n",
		"\t\tname = \"overflowing grants return false with the previous balance retained\",\n",
		"\t\trun = function()\n",
		"\t\t\tlocal amount = BigNum.parse(\"9e9007199254740991\") :: BigNum\n",
		"\t\t\tlocal wallet = Wallet.new({ [GOLD] = amount })\n",
		"\t\t\texpectTrue(not Wallet.grant(wallet, GOLD, amount), \"overflow rejected\")\n",
		"\t\t\texpectEqual(balanceText(wallet, GOLD), \"9e9007199254740991\")\n",
		"\t\tend,\n",
		"\t},\n",
		"}\n",
		"\n",
		"return {\n",
		"\tname = \"WalletTests\",\n",
		"\ttests = tests,\n",
		"}\n",
	},
}
FILES[29] = {
	path = "ServerScriptService/UpgradeService",
	className = "ModuleScript",
	bytes = 10245,
	lines = 261,
	adler32 = 3653372142,
	sha256 = "02fefabc98b541b5b4d1e61c0d2e986a297ec7c5cf3a4016b65a87c9276927fd",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tUpgradeService\n",
		"\tLocation: ServerScriptService > UpgradeService (ModuleScript)\n",
		"\n",
		"\tServer-authoritative upgrades. Milestone 2 has one upgrade: Tap Damage.\n",
		"\n",
		"\tA purchase is one non-yielding transaction:\n",
		"\t  rate limit -> validate request id and upgrade id -> check the level cap ->\n",
		"\t  prepare the new base tap damage with StatService (nothing changes yet) ->\n",
		"\t  spend Gold (all or nothing) -> raise the level -> apply the prepared tap\n",
		"\t  damage -> reply to that player only.\n",
		"\tIf the new tap damage cannot be applied (StatService cannot combine it, for\n",
		"\texample a BigNum overflow), the purchase is refused with \"EffectFailed\"\n",
		"\tbefore any Gold moves, so Gold and the level stay unchanged.\n",
		"\tPrices and values come only from ProgressionConfig; the client sends ids.\n",
		"\n",
		"\tNo duplicate charges: each successful spend raises the level by exactly one,\n",
		"\tand a request id that is not newer than the last one accepted is ignored, so\n",
		"\ta replayed request can never charge twice.\n",
		"\n",
		"\tMilestone 3: AddPlayer accepts the levels loaded by PlayerDataService.\n",
		"]]\n",
		"\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local ServerScriptService = game:GetService(\"ServerScriptService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local CombatService = require(ServerScriptService:WaitForChild(\"CombatService\"))\n",
		"local CurrencyService = require(ServerScriptService:WaitForChild(\"CurrencyService\"))\n",
		"local RateLimiter = require(ServerScriptService:WaitForChild(\"RateLimiter\"))\n",
		"local StatService = require(ServerScriptService:WaitForChild(\"StatService\"))\n",
		"local PlayerDataService = require(ServerScriptService:WaitForChild(\"PlayerDataService\"))\n",
		"\n",
		"type UpgradeDefinition = ProgressionConfig.UpgradeDefinition\n",
		"type UpgradeView = GameConfig.UpgradeView\n",
		"type UpgradeUpdate = GameConfig.UpgradeUpdate\n",
		"type PurchaseReason = GameConfig.PurchaseReason\n",
		"\n",
		"type UpgradeState = {\n",
		"\tlevels: { [string]: number },\n",
		"\tlastRequestId: number,\n",
		"\tsynced: boolean, -- false until the client's first full sync\n",
		"}\n",
		"\n",
		"local REMOTE_WAIT_TIMEOUT = 10\n",
		"local MAX_REQUEST_ID = 9007199254740991 -- request ids stay exact integers\n",
		"\n",
		"local remotesFolder = ReplicatedStorage:WaitForChild(GameConfig.Network.RemotesFolderName)\n",
		"\n",
		"local function getRemoteEvent(remoteName: string): RemoteEvent\n",
		"\tlocal instance = remotesFolder:WaitForChild(remoteName, REMOTE_WAIT_TIMEOUT)\n",
		"\tif instance and instance:IsA(\"RemoteEvent\") then\n",
		"\t\treturn instance\n",
		"\tend\n",
		"\terror(`[UpgradeService] Missing RemoteEvent ReplicatedStorage.{GameConfig.Network.RemotesFolderName}.{remoteName}`)\n",
		"end\n",
		"\n",
		"local requestUpgradeRemote = getRemoteEvent(GameConfig.Network.RequestUpgrade)\n",
		"local upgradeUpdateRemote = getRemoteEvent(GameConfig.Network.UpgradeUpdate)\n",
		"\n",
		"local requestLimiter = RateLimiter.new(GameConfig.Network.UpgradeRequestBurst, GameConfig.Network.UpgradeRequestsPerSecond)\n",
		"\n",
		"local states: { [Player]: UpgradeState } = {}\n",
		"local started = false\n",
		"\n",
		"local UpgradeService = {}\n",
		"\n",
		"local function buildView(definition: UpgradeDefinition, level: number): UpgradeView\n",
		"\tlocal atMax = level >= definition.maxLevel\n",
		"\treturn {\n",
		"\t\tupgradeId = definition.id,\n",
		"\t\tlevel = level,\n",
		"\t\tmaxLevel = definition.maxLevel,\n",
		"\t\tcurrencyId = definition.currencyId,\n",
		"\t\tcurrentValue = BigNum.toString(ProgressionConfig.GetUpgradeValue(definition, level)),\n",
		"\t\tnextValue = if atMax then nil else BigNum.toString(ProgressionConfig.GetUpgradeValue(definition, level + 1)),\n",
		"\t\tnextCost = if atMax then nil else BigNum.toString(ProgressionConfig.GetUpgradeCost(definition, level)),\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function buildViews(state: UpgradeState): { [string]: UpgradeView }\n",
		"\tlocal views: { [string]: UpgradeView } = {}\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tviews[definition.id] = buildView(definition, state.levels[definition.id])\n",
		"\tend\n",
		"\treturn views\n",
		"end\n",
		"\n",
		"local function send(player: Player, state: UpgradeState, update: UpgradeUpdate)\n",
		"\tif not state.synced or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tupgradeUpdateRemote:FireClient(player, update)\n",
		"end\n",
		"\n",
		"local function reply(player: Player, state: UpgradeState, requestId: number, upgradeId: string, reason: PurchaseReason)\n",
		"\tsend(player, state, {\n",
		"\t\tkind = \"PurchaseResult\",\n",
		"\t\tupgrades = buildViews(state),\n",
		"\t\tresult = {\n",
		"\t\t\trequestId = requestId,\n",
		"\t\t\tupgradeId = upgradeId,\n",
		"\t\t\tsuccess = reason == \"Ok\",\n",
		"\t\t\treason = reason,\n",
		"\t\t},\n",
		"\t})\n",
		"end\n",
		"\n",
		"type ApplyEffect = () -> boolean\n",
		"\n",
		"--[[\n",
		"\tPrepares the stat an upgrade level sets, without changing anything. Milestone 2 only has\n",
		"\tTap Damage, whose value is the base tap damage StatService combines. Returns the function\n",
		"\tthat applies it, or nil if it cannot be applied.\n",
		"]]\n",
		"local function prepareUpgradeEffect(player: Player, definition: UpgradeDefinition, level: number): ApplyEffect?\n",
		"\tif definition.id == ProgressionConfig.TapDamageUpgrade.id then\n",
		"\t\treturn StatService.PrepareBase(player, StatService.Stats.TapDamage, ProgressionConfig.GetUpgradeValue(definition, level))\n",
		"\tend\n",
		"\twarn(`[UpgradeService] No effect is defined for upgrade {definition.id}`)\n",
		"\treturn nil\n",
		"end\n",
		"\n",
		"local function applyUpgradeEffect(player: Player, definition: UpgradeDefinition, level: number): boolean\n",
		"\tlocal applyEffect = prepareUpgradeEffect(player, definition, level)\n",
		"\treturn applyEffect ~= nil and applyEffect()\n",
		"end\n",
		"\n",
		"local function isValidRequestId(requestId: unknown, lastRequestId: number): boolean\n",
		"\treturn typeof(requestId) == \"number\"\n",
		"\t\tand requestId % 1 == 0\n",
		"\t\tand requestId > lastRequestId\n",
		"\t\tand requestId <= MAX_REQUEST_ID\n",
		"end\n",
		"\n",
		"local function handlePurchaseRequest(player: Player, upgradeId: unknown, requestId: unknown)\n",
		"\tlocal state = states[player]\n",
		"\tif not state or not state.synced or not PlayerDataService.CanMutate(player) then\n",
		"\t\treturn -- not ready yet; the client's panel stays disabled until the first sync\n",
		"\tend\n",
		"\tif not requestLimiter:allow(player) then\n",
		"\t\treturn -- over the limit: dropped without a reply, like rapid taps\n",
		"\tend\n",
		"\tif not isValidRequestId(requestId, state.lastRequestId) or typeof(upgradeId) ~= \"string\" then\n",
		"\t\treturn -- malformed or replayed request\n",
		"\tend\n",
		"\tlocal definition = ProgressionConfig.GetUpgrade(upgradeId :: string)\n",
		"\tif definition == nil then\n",
		"\t\treturn -- unknown upgrade id\n",
		"\tend\n",
		"\n",
		"\tlocal acceptedRequestId = requestId :: number\n",
		"\tstate.lastRequestId = acceptedRequestId\n",
		"\n",
		"\tlocal level = state.levels[definition.id]\n",
		"\tif level >= definition.maxLevel then\n",
		"\t\treply(player, state, acceptedRequestId, definition.id, \"MaxLevel\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tif not CombatService.HasPlayer(player) then\n",
		"\t\treturn -- player is leaving; charge nothing\n",
		"\tend\n",
		"\n",
		"\t-- Everything from here to the reply runs without yielding: one atomic transaction.\n",
		"\tlocal newLevel = level + 1\n",
		"\t-- The new tap damage is prepared before any Gold moves: if it cannot be applied, nothing is charged.\n",
		"\tlocal applyEffect = prepareUpgradeEffect(player, definition, newLevel)\n",
		"\tif applyEffect == nil then\n",
		"\t\treply(player, state, acceptedRequestId, definition.id, \"EffectFailed\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal cost = ProgressionConfig.GetUpgradeCost(definition, level)\n",
		"\tif not CurrencyService.TrySpend(player, definition.currencyId, cost, `Upgrade:{definition.id}`, false) then\n",
		"\t\treply(player, state, acceptedRequestId, definition.id, \"InsufficientFunds\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tstate.levels[definition.id] = newLevel\n",
		"\tif not applyEffect() then\n",
		"\t\t-- Not reachable while CombatService accepts what StatService prepared (nothing yields in between).\n",
		"\t\t-- Undo the purchase instead of charging for an upgrade that did not apply.\n",
		"\t\tstate.levels[definition.id] = level\n",
		"\t\tCurrencyService.Grant(player, definition.currencyId, cost, `Refund:Upgrade:{definition.id}`, false)\n",
		"\t\twarn(`[UpgradeService] {definition.id} level {newLevel} could not be applied for {player.Name}; the purchase was refunded`)\n",
		"\t\treply(player, state, acceptedRequestId, definition.id, \"EffectFailed\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tPlayerDataService.RecordTransaction(player, {\n",
		"\t\tkind = \"Upgrade\", currencyId = definition.currencyId, amount = BigNum.toString(cost),\n",
		"\t\tupgradeId = definition.id, fromLevel = level, toLevel = newLevel,\n",
		"\t})\n",
		"\tPlayerDataService.RecordActivity(player)\n",
		"\treply(player, state, acceptedRequestId, definition.id, \"Ok\")\n",
		"end\n",
		"\n",
		"-- Requires CombatService.AddPlayer and StatService.AddPlayer first, so the starting tap damage can be applied.\n",
		"-- saved: levels from the player's profile, already validated by ProfileSchema (nil for a new player).\n",
		"function UpgradeService.AddPlayer(player: Player, saved: { [string]: number }?)\n",
		"\tif states[player] or player.Parent ~= Players then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal levels: { [string]: number } = {}\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tlocal level = if saved then saved[definition.id] else nil\n",
		"\t\tlocal valid = typeof(level) == \"number\" and level % 1 == 0 and level >= definition.startingLevel and level <= definition.maxLevel\n",
		"\t\tlevels[definition.id] = if valid then level :: number else definition.startingLevel\n",
		"\tend\n",
		"\tstates[player] = {\n",
		"\t\tlevels = levels,\n",
		"\t\tlastRequestId = 0,\n",
		"\t\tsynced = false,\n",
		"\t}\n",
		"\tfor _, definition in ProgressionConfig.Upgrades do\n",
		"\t\tapplyUpgradeEffect(player, definition, levels[definition.id])\n",
		"\tend\n",
		"end\n",
		"\n",
		"function UpgradeService.RemovePlayer(player: Player)\n",
		"\tstates[player] = nil\n",
		"\trequestLimiter:remove(player)\n",
		"end\n",
		"\n",
		"function UpgradeService.GetLevel(player: Player, upgradeId: string): number?\n",
		"\tlocal state = states[player]\n",
		"\tif not state then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn state.levels[upgradeId]\n",
		"end\n",
		"\n",
		"-- Sends every upgrade's current view and allows purchase replies from now on.\n",
		"function UpgradeService.SyncPlayer(player: Player)\n",
		"\tlocal state = states[player]\n",
		"\tif not state then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstate.synced = true\n",
		"\tsend(player, state, {\n",
		"\t\tkind = \"Sync\",\n",
		"\t\tupgrades = buildViews(state),\n",
		"\t})\n",
		"end\n",
		"\n",
		"-- Connects the purchase remote. Safe to call once; repeated calls are ignored.\n",
		"function UpgradeService.Start()\n",
		"\tif started then\n",
		"\t\twarn(\"[UpgradeService] Start() was called more than once; ignoring.\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tstarted = true\n",
		"\n",
		"\trequestUpgradeRemote.OnServerEvent:Connect(function(player: Player, upgradeId: unknown, requestId: unknown)\n",
		"\t\thandlePurchaseRequest(player, upgradeId, requestId)\n",
		"\tend)\n",
		"end\n",
		"\n",
		"return UpgradeService\n",
	},
}
FILES[30] = {
	path = "ServerScriptService/Wallet",
	className = "ModuleScript",
	bytes = 2966,
	lines = 85,
	adler32 = 3038385218,
	sha256 = "7e481dcc70f474e8d515bb5894e13f3a6c1418a8cd073fb43ac6bfe427583e30",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tWallet\n",
		"\tLocation: ServerScriptService > Wallet (ModuleScript)\n",
		"\n",
		"\tPure balance bookkeeping for one player: no Roblox services, no networking,\n",
		"\tno yields. CurrencyService owns one Wallet per player; tests use it directly.\n",
		"\tEvery operation either fully succeeds or changes nothing, and no operation\n",
		"\tcan make a balance negative.\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"export type Wallet = {\n",
		"\tbalances: { [string]: BigNum },\n",
		"}\n",
		"\n",
		"local Wallet = {}\n",
		"\n",
		"-- Creates a wallet holding exactly the given currencies.\n",
		"function Wallet.new(startingBalances: { [string]: BigNum }): Wallet\n",
		"\tlocal balances: { [string]: BigNum } = {}\n",
		"\tfor currencyId, amount in startingBalances do\n",
		"\t\tassert(ProgressionConfig.IsCurrencyValue(currencyId, amount), `Wallet.new: invalid starting balance for {currencyId}`)\n",
		"\t\tbalances[currencyId] = amount\n",
		"\tend\n",
		"\treturn { balances = balances }\n",
		"end\n",
		"\n",
		"function Wallet.has(wallet: Wallet, currencyId: string): boolean\n",
		"\treturn wallet.balances[currencyId] ~= nil\n",
		"end\n",
		"\n",
		"-- Errors for an unknown currency: callers check has() or use ids from ProgressionConfig.\n",
		"function Wallet.get(wallet: Wallet, currencyId: string): BigNum\n",
		"\tlocal balance = wallet.balances[currencyId]\n",
		"\tif balance == nil then\n",
		"\t\terror(`Wallet: unknown currency \"{currencyId}\"`, 2)\n",
		"\tend\n",
		"\treturn balance\n",
		"end\n",
		"\n",
		"-- Adds a positive amount. Returns false, changing nothing, for an unknown currency or an invalid or zero amount.\n",
		"function Wallet.grant(wallet: Wallet, currencyId: string, amount: BigNum): boolean\n",
		"\tlocal balance = wallet.balances[currencyId]\n",
		"\tif balance == nil or not ProgressionConfig.IsCurrencyValue(currencyId, amount) or BigNum.isZero(amount) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal ok, updated = pcall(BigNum.add, balance, amount)\n",
		"\tif not ok or not ProgressionConfig.IsCurrencyValue(currencyId, updated) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\twallet.balances[currencyId] = updated\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Removes the whole amount only if it is available. Returns false, changing nothing, otherwise.\n",
		"function Wallet.trySpend(wallet: Wallet, currencyId: string, amount: BigNum): boolean\n",
		"\tlocal balance = wallet.balances[currencyId]\n",
		"\tif balance == nil or not ProgressionConfig.IsCurrencyValue(currencyId, amount) or BigNum.isZero(amount) then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal remaining = BigNum.trySub(balance, amount)\n",
		"\tif remaining == nil then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\twallet.balances[currencyId] = remaining\n",
		"\treturn true\n",
		"end\n",
		"\n",
		"-- Every balance as a canonical BigNum string, ready to send to the client.\n",
		"function Wallet.snapshot(wallet: Wallet): { [string]: string }\n",
		"\tlocal result: { [string]: string } = {}\n",
		"\tfor currencyId, balance in wallet.balances do\n",
		"\t\tresult[currencyId] = BigNum.toString(balance)\n",
		"\tend\n",
		"\treturn result\n",
		"end\n",
		"\n",
		"return table.freeze(Wallet)\n",
	},
}
FILES[31] = {
	path = "StarterPlayer/StarterPlayerScripts/CombatClient",
	className = "LocalScript",
	bytes = 10496,
	lines = 291,
	adler32 = 1711349078,
	sha256 = "fb56fece6ba29d4ea31ef308a4de775355c1079f7266d882d42a828e190c67ca",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatClient\n",
		"\tLocation: StarterPlayer > StarterPlayerScripts > CombatClient (LocalScript)\n",
		"\tChildren: ArenaView, CombatHud, UpgradePanel (ModuleScripts)\n",
		"\n",
		"\tClient controller. It:\n",
		"\t  1. builds the local arena/camera (ArenaView), interface (CombatHud) and\n",
		"\t     upgrade panel (UpgradePanel)\n",
		"\t  2. listens for every server update FIRST, then tells the server it is\n",
		"\t     ready, so no initial sync can be missed\n",
		"\t  3. turns mouse clicks and touches into attack requests, and panel presses\n",
		"\t     into upgrade requests\n",
		"\n",
		"\tIt sends no numbers the server trusts: attacks carry nothing, upgrade\n",
		"\trequests carry only an upgrade id and an increasing request id. It never\n",
		"\tchanges HP, Gold, stage, damage or prices itself.\n",
		"]]\n",
		"\n",
		"local GuiService = game:GetService(\"GuiService\")\n",
		"local Players = game:GetService(\"Players\")\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local StarterGui = game:GetService(\"StarterGui\")\n",
		"local UserInputService = game:GetService(\"UserInputService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"local GameConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"GameConfig\"))\n",
		"local ProgressionConfig = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"ProgressionConfig\"))\n",
		"local ArenaView = require(script:WaitForChild(\"ArenaView\"))\n",
		"local CombatHud = require(script:WaitForChild(\"CombatHud\"))\n",
		"local UpgradePanel = require(script:WaitForChild(\"UpgradePanel\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"type CombatView = CombatHud.CombatView\n",
		"type UpgradeViewModel = UpgradePanel.UpgradeViewModel\n",
		"type CombatSnapshot = GameConfig.CombatSnapshot\n",
		"type CombatUpdate = GameConfig.CombatUpdate\n",
		"type CurrencyUpdate = GameConfig.CurrencyUpdate\n",
		"type UpgradeUpdate = GameConfig.UpgradeUpdate\n",
		"\n",
		"local REMOTE_WAIT_TIMEOUT = 30\n",
		"-- Some touch-screen PCs report a touch AND an emulated mouse click; ignore the click if a touch just happened.\n",
		"local TOUCH_THEN_MOUSE_IGNORE_SECONDS = 0.5\n",
		"local SYNC_RETRY_INTERVAL = 3\n",
		"local SYNC_RETRY_ATTEMPTS = 3\n",
		"local CORE_GUI_RETRY_ATTEMPTS = 10\n",
		"local CORE_GUI_RETRY_INTERVAL = 0.5\n",
		"\n",
		"local TAP_UPGRADE_ID = ProgressionConfig.TapDamageUpgrade.id\n",
		"local GOLD_ID = ProgressionConfig.GoldCurrencyId\n",
		"\n",
		"local localPlayer = Players.LocalPlayer\n",
		"local playerGui = localPlayer:WaitForChild(\"PlayerGui\") :: PlayerGui\n",
		"\n",
		"local currentView: CombatView? = nil\n",
		"local lastAttackRequestAt = -math.huge\n",
		"local lastTouchAt = -math.huge\n",
		"local lastUpgradeRequestId = 0\n",
		"\n",
		"local function getRemoteEvent(remoteName: string): RemoteEvent\n",
		"\tlocal folderName = GameConfig.Network.RemotesFolderName\n",
		"\tlocal folder = ReplicatedStorage:WaitForChild(folderName, REMOTE_WAIT_TIMEOUT)\n",
		"\tif folder then\n",
		"\t\tlocal remote = folder:WaitForChild(remoteName, REMOTE_WAIT_TIMEOUT)\n",
		"\t\tif remote and remote:IsA(\"RemoteEvent\") then\n",
		"\t\t\treturn remote\n",
		"\t\tend\n",
		"\tend\n",
		"\terror(`[CombatClient] RemoteEvent ReplicatedStorage.{folderName}.{remoteName} was not found`)\n",
		"end\n",
		"\n",
		"-- No avatar exists, so hide character-only core UI and on-screen movement controls.\n",
		"local function configureCoreGui()\n",
		"\tGuiService.TouchControlsEnabled = false\n",
		"\tStarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Backpack, false)\n",
		"\tStarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Health, false)\n",
		"\n",
		"\t-- SetCore can fail until the core scripts have registered it, so retry a bounded number of times.\n",
		"\tfor _ = 1, CORE_GUI_RETRY_ATTEMPTS do\n",
		"\t\tlocal success = pcall(function()\n",
		"\t\t\tStarterGui:SetCore(\"ResetButtonCallback\", false)\n",
		"\t\tend)\n",
		"\t\tif success then\n",
		"\t\t\treturn\n",
		"\t\tend\n",
		"\t\ttask.wait(CORE_GUI_RETRY_INTERVAL)\n",
		"\tend\n",
		"\twarn(\"[CombatClient] Could not disable the reset button (it does nothing without a character).\")\n",
		"end\n",
		"\n",
		"-- Turns the network snapshot (BigNum strings) into a view; nil if any number is malformed.\n",
		"local function decodeSnapshot(snapshot: CombatSnapshot): CombatView?\n",
		"\tlocal tapDamage = BigNum.parse(snapshot.tapDamage)\n",
		"\tlocal enemyHp = BigNum.parse(snapshot.enemyHp)\n",
		"\tlocal enemyMaxHp = BigNum.parse(snapshot.enemyMaxHp)\n",
		"\tif tapDamage == nil or enemyHp == nil or enemyMaxHp == nil then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tif typeof(snapshot.stage) ~= \"number\" or typeof(snapshot.enemyId) ~= \"number\" or typeof(snapshot.enemyName) ~= \"string\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn {\n",
		"\t\tstage = snapshot.stage,\n",
		"\t\ttapDamage = tapDamage,\n",
		"\t\tenemyId = snapshot.enemyId,\n",
		"\t\tenemyName = snapshot.enemyName,\n",
		"\t\tenemyHp = enemyHp,\n",
		"\t\tenemyMaxHp = enemyMaxHp,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function decodeUpgradeView(raw: unknown): UpgradeViewModel?\n",
		"\tif typeof(raw) ~= \"table\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\tlocal view: any = raw\n",
		"\tlocal currentValue = BigNum.parse(view.currentValue)\n",
		"\tif currentValue == nil or typeof(view.level) ~= \"number\" or typeof(view.maxLevel) ~= \"number\" then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\t-- nextValue and nextCost are absent at max level; if present they must be valid.\n",
		"\tlocal nextValue = BigNum.parse(view.nextValue)\n",
		"\tlocal nextCost = BigNum.parse(view.nextCost)\n",
		"\tif (view.nextValue ~= nil and nextValue == nil) or (view.nextCost ~= nil and nextCost == nil) then\n",
		"\t\treturn nil\n",
		"\tend\n",
		"\treturn {\n",
		"\t\tupgradeId = tostring(view.upgradeId),\n",
		"\t\tlevel = view.level,\n",
		"\t\tmaxLevel = view.maxLevel,\n",
		"\t\tcurrencyId = tostring(view.currencyId),\n",
		"\t\tcurrentValue = currentValue,\n",
		"\t\tnextValue = nextValue,\n",
		"\t\tnextCost = nextCost,\n",
		"\t}\n",
		"end\n",
		"\n",
		"local function onCombatUpdate(update: CombatUpdate)\n",
		"\tif typeof(update) ~= \"table\" or typeof(update.snapshot) ~= \"table\" then\n",
		"\t\twarn(\"[CombatClient] Ignored a malformed combat update\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal view = decodeSnapshot(update.snapshot)\n",
		"\tif view == nil then\n",
		"\t\twarn(\"[CombatClient] Ignored a combat update with invalid numbers\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal isFirstSnapshot = currentView == nil\n",
		"\tcurrentView = view\n",
		"\n",
		"\t-- ShowEnemy is a no-op when this enemy is already displayed.\n",
		"\t-- On \"Defeated\" the snapshot already describes the NEXT enemy, so the old one plays its defeat animation.\n",
		"\tArenaView.ShowEnemy(view.enemyId, isFirstSnapshot or update.kind == \"Defeated\")\n",
		"\n",
		"\tif update.kind == \"Hit\" then\n",
		"\t\tArenaView.PlayHit()\n",
		"\tend\n",
		"\n",
		"\tCombatHud.Render(view, update.kind ~= \"Hit\")\n",
		"\n",
		"\tlocal damage = BigNum.parse(update.damage)\n",
		"\tif damage and not BigNum.isZero(damage) then\n",
		"\t\tCombatHud.ShowDamage(damage)\n",
		"\tend\n",
		"\n",
		"\tlocal goldAwarded = BigNum.parse(update.goldAwarded)\n",
		"\tif goldAwarded and not BigNum.isZero(goldAwarded) then\n",
		"\t\tCombatHud.ShowGoldGain(goldAwarded)\n",
		"\tend\n",
		"end\n",
		"\n",
		"local function onCurrencyUpdate(update: CurrencyUpdate)\n",
		"\tif typeof(update) ~= \"table\" or typeof(update.balances) ~= \"table\" then\n",
		"\t\twarn(\"[CombatClient] Ignored a malformed currency update\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal gold = BigNum.parse(update.balances[GOLD_ID])\n",
		"\tif gold == nil then\n",
		"\t\twarn(\"[CombatClient] Ignored a currency update without a valid Gold balance\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tCombatHud.SetGold(gold)\n",
		"\tUpgradePanel.SetBalance(gold)\n",
		"end\n",
		"\n",
		"local function onUpgradeUpdate(update: UpgradeUpdate)\n",
		"\tif typeof(update) ~= \"table\" or typeof(update.upgrades) ~= \"table\" then\n",
		"\t\twarn(\"[CombatClient] Ignored a malformed upgrade update\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlocal view = decodeUpgradeView(update.upgrades[TAP_UPGRADE_ID])\n",
		"\tif view == nil then\n",
		"\t\twarn(\"[CombatClient] Ignored an upgrade update with invalid values\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\tUpgradePanel.Render(view)\n",
		"\n",
		"\tlocal result = update.result\n",
		"\tif update.kind == \"PurchaseResult\" and typeof(result) == \"table\" then\n",
		"\t\tUpgradePanel.ShowResult(result.success == true, tostring(result.reason))\n",
		"\tend\n",
		"end\n",
		"\n",
		"local function tryRequestAttack(screenPosition: Vector2, requestAttackRemote: RemoteEvent)\n",
		"\tif currentView == nil then\n",
		"\t\treturn -- not synced yet\n",
		"\tend\n",
		"\tif not CombatHud.IsInTapArea(screenPosition) or UpgradePanel.ContainsPoint(screenPosition) then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\t-- Matches the server cooldown so we don't send requests the server would drop anyway.\n",
		"\tlocal now = os.clock()\n",
		"\tif now - lastAttackRequestAt < GameConfig.Combat.TapCooldown then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tlastAttackRequestAt = now\n",
		"\n",
		"\trequestAttackRemote:FireServer() -- no arguments: the server decides everything\n",
		"\tCombatHud.PlayTapRipple(screenPosition)\n",
		"end\n",
		"\n",
		"local function connectInput(requestAttackRemote: RemoteEvent)\n",
		"\t-- One handler for mouse and touch. gameProcessedEvent is true when the press\n",
		"\t-- landed on an interactive GUI element (the upgrade panel and its button,\n",
		"\t-- chat, Roblox menus), so those presses never become attacks.\n",
		"\tUserInputService.InputBegan:Connect(function(input: InputObject, gameProcessedEvent: boolean)\n",
		"\t\tif gameProcessedEvent then\n",
		"\t\t\treturn\n",
		"\t\tend\n",
		"\n",
		"\t\tlocal inputType = input.UserInputType\n",
		"\t\tif inputType == Enum.UserInputType.Touch then\n",
		"\t\t\tlastTouchAt = os.clock()\n",
		"\t\telseif inputType == Enum.UserInputType.MouseButton1 then\n",
		"\t\t\tif os.clock() - lastTouchAt < TOUCH_THEN_MOUSE_IGNORE_SECONDS then\n",
		"\t\t\t\treturn\n",
		"\t\t\tend\n",
		"\t\telse\n",
		"\t\t\treturn\n",
		"\t\tend\n",
		"\n",
		"\t\ttryRequestAttack(Vector2.new(input.Position.X, input.Position.Y), requestAttackRemote)\n",
		"\tend)\n",
		"end\n",
		"\n",
		"local function start()\n",
		"\ttask.spawn(configureCoreGui)\n",
		"\n",
		"\tlocal requestAttackRemote = getRemoteEvent(GameConfig.Network.RequestAttack)\n",
		"\tlocal clientReadyRemote = getRemoteEvent(GameConfig.Network.ClientReady)\n",
		"\tlocal combatUpdateRemote = getRemoteEvent(GameConfig.Network.CombatUpdate)\n",
		"\tlocal currencyUpdateRemote = getRemoteEvent(GameConfig.Network.CurrencyUpdate)\n",
		"\tlocal upgradeUpdateRemote = getRemoteEvent(GameConfig.Network.UpgradeUpdate)\n",
		"\tlocal requestUpgradeRemote = getRemoteEvent(GameConfig.Network.RequestUpgrade)\n",
		"\n",
		"\tArenaView.Mount()\n",
		"\tCombatHud.Mount(playerGui)\n",
		"\tUpgradePanel.Mount(playerGui, function()\n",
		"\t\t-- Each press gets a new, increasing id; the server ignores any id it has already seen.\n",
		"\t\tlastUpgradeRequestId += 1\n",
		"\t\trequestUpgradeRemote:FireServer(TAP_UPGRADE_ID, lastUpgradeRequestId)\n",
		"\tend)\n",
		"\n",
		"\t-- Listen first, then announce readiness: no sync reply can arrive before we're listening.\n",
		"\tcombatUpdateRemote.OnClientEvent:Connect(onCombatUpdate)\n",
		"\tcurrencyUpdateRemote.OnClientEvent:Connect(onCurrencyUpdate)\n",
		"\tupgradeUpdateRemote.OnClientEvent:Connect(onUpgradeUpdate)\n",
		"\tconnectInput(requestAttackRemote)\n",
		"\tclientReadyRemote:FireServer()\n",
		"\n",
		"\t-- Safety net: if no sync arrived (e.g. the server was still starting), ask again a few times.\n",
		"\ttask.spawn(function()\n",
		"\t\tfor attempt = 1, SYNC_RETRY_ATTEMPTS do\n",
		"\t\t\ttask.wait(SYNC_RETRY_INTERVAL)\n",
		"\t\t\tif currentView ~= nil then\n",
		"\t\t\t\treturn\n",
		"\t\t\tend\n",
		"\t\t\twarn(`[CombatClient] No combat sync yet; re-sending ClientReady (attempt {attempt}/{SYNC_RETRY_ATTEMPTS})`)\n",
		"\t\t\tclientReadyRemote:FireServer()\n",
		"\t\tend\n",
		"\t\t-- Give the final retry the same response window before concluding that sync failed.\n",
		"\t\ttask.wait(SYNC_RETRY_INTERVAL)\n",
		"\t\tif currentView == nil then\n",
		"\t\t\twarn(\"[CombatClient] Combat state never arrived. Check the server Output for CombatService errors.\")\n",
		"\t\tend\n",
		"\tend)\n",
		"end\n",
		"\n",
		"start()\n",
	},
}
FILES[32] = {
	path = "StarterPlayer/StarterPlayerScripts/CombatClient/ArenaView",
	className = "ModuleScript",
	bytes = 15520,
	lines = 528,
	adler32 = 2016899911,
	sha256 = "b3e05e45d0c907b4242b05b055d11dc1105cb0f2733fd3351e8130b63f7495e0",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tArenaView\n",
		"\tLocation: StarterPlayer > StarterPlayerScripts > CombatClient > ArenaView (ModuleScript)\n",
		"\n",
		"\tEverything 3D that only this client sees:\n",
		"\t  - the fixed Scriptable camera\n",
		"\t  - the arena backdrop and lighting\n",
		"\t  - the local placeholder Forest Slime and its hit / defeat / spawn animations\n",
		"\n",
		"\tIt holds no game state. CombatClient tells it which enemy (by enemyId)\n",
		"\tshould be on screen and when a confirmed hit happened.\n",
		"]]\n",
		"\n",
		"local TweenService = game:GetService(\"TweenService\")\n",
		"local Workspace = game:GetService(\"Workspace\")\n",
		"\n",
		"-- Layout (world space). The arena floats above the origin so it never\n",
		"-- clashes with the template Baseplate if that was left in the place.\n",
		"local ARENA_ORIGIN = Vector3.new(0, 50, 0)\n",
		"local ENEMY_POSITION = ARENA_ORIGIN + Vector3.new(0, 0.6, 0) -- top of the stone platform\n",
		"local CAMERA_POSITION = ARENA_ORIGIN + Vector3.new(0, 6, 18)\n",
		"local CAMERA_FOCUS = ARENA_ORIGIN + Vector3.new(0, 4, 0)\n",
		"local CAMERA_FIELD_OF_VIEW = 50\n",
		"\n",
		"local STAGE_FOLDER_NAME = \"CombatStage\"\n",
		"\n",
		"-- Placeholder palette\n",
		"local SLIME_BODY_COLOR = Color3.fromRGB(112, 206, 92)\n",
		"local SLIME_BASE_COLOR = Color3.fromRGB(82, 170, 70)\n",
		"local SLIME_EYE_COLOR = Color3.fromRGB(25, 28, 36)\n",
		"local SLIME_MOUTH_COLOR = Color3.fromRGB(38, 70, 34)\n",
		"local WHITE = Color3.fromRGB(255, 255, 255)\n",
		"local EMBER_COLOR = Color3.fromRGB(255, 150, 70)\n",
		"\n",
		"-- Animation\n",
		"local MIN_SCALE = 0.05\n",
		"local HIT_SQUASH_SCALE = 0.86\n",
		"local HIT_FLASH_TRANSPARENCY = 0.35\n",
		"local IDLE_BOB_HEIGHT = 0.2\n",
		"local DEFEAT_PARTICLE_COUNT = 24\n",
		"\n",
		"local HIT_PULSE_INFO = TweenInfo.new(0.18, Enum.EasingStyle.Back, Enum.EasingDirection.Out)\n",
		"local HIT_FLASH_INFO = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n",
		"local SPAWN_INFO = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out, 0, false, 0.12)\n",
		"local DEFEAT_INFO = TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.In)\n",
		"local IDLE_BOB_INFO = TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true)\n",
		"\n",
		"type PartSpec = {\n",
		"\tname: string,\n",
		"\tsize: Vector3,\n",
		"\tcframe: CFrame,\n",
		"\tcolor: Color3,\n",
		"\tmaterial: Enum.Material,\n",
		"\tshape: Enum.PartType?,\n",
		"\ttransparency: number?,\n",
		"\tcastShadow: boolean?,\n",
		"}\n",
		"\n",
		"type EnemyVisual = {\n",
		"\tid: number,\n",
		"\tmodel: Model,\n",
		"\tparts: { BasePart },\n",
		"\thighlight: Highlight,\n",
		"\tbasePivot: CFrame,\n",
		"\tbaseScale: NumberValue, -- spawn / defeat size\n",
		"\tpulseScale: NumberValue, -- short squash on hit\n",
		"\tbobOffset: NumberValue, -- idle up/down motion\n",
		"\tidleTween: Tween?,\n",
		"\tpulseTween: Tween?,\n",
		"\tflashTween: Tween?,\n",
		"\tspawnTween: Tween?,\n",
		"}\n",
		"\n",
		"local ArenaView = {}\n",
		"\n",
		"local mounted = false\n",
		"local stageFolder: Folder? = nil\n",
		"local burstEmitter: ParticleEmitter? = nil\n",
		"local currentEnemy: EnemyVisual? = nil\n",
		"local cameraConnections: { RBXScriptConnection } = {}\n",
		"\n",
		"local function newPart(spec: PartSpec, parent: Instance): Part\n",
		"\tlocal part = Instance.new(\"Part\")\n",
		"\tpart.Name = spec.name\n",
		"\tpart.Shape = spec.shape or Enum.PartType.Block\n",
		"\tpart.Size = spec.size\n",
		"\tpart.CFrame = spec.cframe\n",
		"\tpart.Color = spec.color\n",
		"\tpart.Material = spec.material\n",
		"\tpart.Transparency = spec.transparency or 0\n",
		"\tpart.CastShadow = spec.castShadow == true\n",
		"\tpart.Anchored = true\n",
		"\tpart.CanCollide = false\n",
		"\tpart.CanTouch = false\n",
		"\tpart.CanQuery = false\n",
		"\tpart.TopSurface = Enum.SurfaceType.Smooth\n",
		"\tpart.BottomSurface = Enum.SurfaceType.Smooth\n",
		"\tpart.Parent = parent\n",
		"\treturn part\n",
		"end\n",
		"\n",
		"-- Cylinders point along X by default; this stands them upright.\n",
		"local UPRIGHT = CFrame.Angles(0, 0, math.rad(90))\n",
		"\n",
		"local function buildTree(parent: Instance, groundPosition: Vector3, height: number)\n",
		"\tnewPart({\n",
		"\t\tname = \"TreeTrunk\",\n",
		"\t\tshape = Enum.PartType.Cylinder,\n",
		"\t\tsize = Vector3.new(height, 2.2, 2.2),\n",
		"\t\tcframe = CFrame.new(groundPosition + Vector3.new(0, height / 2, 0)) * UPRIGHT,\n",
		"\t\tcolor = Color3.fromRGB(58, 42, 32),\n",
		"\t\tmaterial = Enum.Material.Wood,\n",
		"\t}, parent)\n",
		"\tnewPart({\n",
		"\t\tname = \"TreeCanopy\",\n",
		"\t\tshape = Enum.PartType.Ball,\n",
		"\t\tsize = Vector3.new(10, 10, 10),\n",
		"\t\tcframe = CFrame.new(groundPosition + Vector3.new(0, height + 3, 0)),\n",
		"\t\tcolor = Color3.fromRGB(34, 66, 40),\n",
		"\t\tmaterial = Enum.Material.Grass,\n",
		"\t}, parent)\n",
		"end\n",
		"\n",
		"local function buildBrazier(parent: Instance, groundPosition: Vector3)\n",
		"\tlocal pillarHeight = 10\n",
		"\tnewPart({\n",
		"\t\tname = \"Pillar\",\n",
		"\t\tsize = Vector3.new(2.5, pillarHeight, 2.5),\n",
		"\t\tcframe = CFrame.new(groundPosition + Vector3.new(0, pillarHeight / 2, 0)),\n",
		"\t\tcolor = Color3.fromRGB(88, 84, 78),\n",
		"\t\tmaterial = Enum.Material.Cobblestone,\n",
		"\t\tcastShadow = true,\n",
		"\t}, parent)\n",
		"\n",
		"\tlocal bowl = newPart({\n",
		"\t\tname = \"Brazier\",\n",
		"\t\tsize = Vector3.new(2.8, 0.8, 2.8),\n",
		"\t\tcframe = CFrame.new(groundPosition + Vector3.new(0, pillarHeight + 0.4, 0)),\n",
		"\t\tcolor = Color3.fromRGB(60, 50, 45),\n",
		"\t\tmaterial = Enum.Material.Metal,\n",
		"\t}, parent)\n",
		"\n",
		"\tlocal fire = Instance.new(\"Fire\")\n",
		"\tfire.Size = 4\n",
		"\tfire.Heat = 8\n",
		"\tfire.Color = EMBER_COLOR\n",
		"\tfire.SecondaryColor = Color3.fromRGB(255, 80, 30)\n",
		"\tfire.Parent = bowl\n",
		"\n",
		"\tlocal light = Instance.new(\"PointLight\")\n",
		"\tlight.Color = EMBER_COLOR\n",
		"\tlight.Brightness = 2\n",
		"\tlight.Range = 24\n",
		"\tlight.Parent = bowl\n",
		"end\n",
		"\n",
		"local function buildArena(parent: Instance)\n",
		"\tlocal arena = Instance.new(\"Folder\")\n",
		"\tarena.Name = \"Arena\"\n",
		"\n",
		"\tnewPart({\n",
		"\t\tname = \"Floor\",\n",
		"\t\tsize = Vector3.new(100, 1, 70),\n",
		"\t\tcframe = CFrame.new(ARENA_ORIGIN + Vector3.new(0, -0.5, -6)),\n",
		"\t\tcolor = Color3.fromRGB(62, 84, 56),\n",
		"\t\tmaterial = Enum.Material.Grass,\n",
		"\t}, arena)\n",
		"\n",
		"\tnewPart({\n",
		"\t\tname = \"Backdrop\",\n",
		"\t\tsize = Vector3.new(180, 80, 2),\n",
		"\t\tcframe = CFrame.new(ARENA_ORIGIN + Vector3.new(0, 38, -24)),\n",
		"\t\tcolor = Color3.fromRGB(34, 46, 52),\n",
		"\t\tmaterial = Enum.Material.Slate,\n",
		"\t}, arena)\n",
		"\n",
		"\tnewPart({\n",
		"\t\tname = \"Platform\",\n",
		"\t\tshape = Enum.PartType.Cylinder,\n",
		"\t\tsize = Vector3.new(0.6, 12, 12),\n",
		"\t\tcframe = CFrame.new(ARENA_ORIGIN + Vector3.new(0, 0.3, 0)) * UPRIGHT,\n",
		"\t\tcolor = Color3.fromRGB(96, 92, 84),\n",
		"\t\tmaterial = Enum.Material.Slate,\n",
		"\t}, arena)\n",
		"\n",
		"\tfor _, x in { -30, -15, 16, 31 } do\n",
		"\t\tbuildTree(arena, ARENA_ORIGIN + Vector3.new(x, 0, -19), 14)\n",
		"\tend\n",
		"\n",
		"\tbuildBrazier(arena, ARENA_ORIGIN + Vector3.new(-13, 0, -6))\n",
		"\tbuildBrazier(arena, ARENA_ORIGIN + Vector3.new(13, 0, -6))\n",
		"\n",
		"\t-- Key light aimed at the enemy from above the camera.\n",
		"\tlocal keyLightPosition = ARENA_ORIGIN + Vector3.new(0, 14, 12)\n",
		"\tlocal keyLightAnchor = newPart({\n",
		"\t\tname = \"KeyLight\",\n",
		"\t\tsize = Vector3.new(1, 1, 1),\n",
		"\t\tcframe = CFrame.lookAt(keyLightPosition, ENEMY_POSITION + Vector3.new(0, 2.5, 0)),\n",
		"\t\tcolor = WHITE,\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\ttransparency = 1,\n",
		"\t}, arena)\n",
		"\tlocal keyLight = Instance.new(\"SpotLight\")\n",
		"\tkeyLight.Face = Enum.NormalId.Front\n",
		"\tkeyLight.Angle = 55\n",
		"\tkeyLight.Range = 45\n",
		"\tkeyLight.Brightness = 2.5\n",
		"\tkeyLight.Color = Color3.fromRGB(255, 240, 220)\n",
		"\tkeyLight.Parent = keyLightAnchor\n",
		"\n",
		"\t-- Invisible emitter used for the defeat burst.\n",
		"\tlocal burstAnchor = newPart({\n",
		"\t\tname = \"BurstAnchor\",\n",
		"\t\tsize = Vector3.new(1, 1, 1),\n",
		"\t\tcframe = CFrame.new(ENEMY_POSITION + Vector3.new(0, 2.4, 0)),\n",
		"\t\tcolor = WHITE,\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\ttransparency = 1,\n",
		"\t}, arena)\n",
		"\tlocal emitter = Instance.new(\"ParticleEmitter\")\n",
		"\temitter.Enabled = false\n",
		"\temitter.Color = ColorSequence.new(SLIME_BODY_COLOR, Color3.fromRGB(210, 255, 170))\n",
		"\temitter.LightEmission = 0.4\n",
		"\temitter.Size = NumberSequence.new({\n",
		"\t\tNumberSequenceKeypoint.new(0, 0.7),\n",
		"\t\tNumberSequenceKeypoint.new(1, 0),\n",
		"\t})\n",
		"\temitter.Lifetime = NumberRange.new(0.4, 0.7)\n",
		"\temitter.Speed = NumberRange.new(8, 14)\n",
		"\temitter.SpreadAngle = Vector2.new(180, 180)\n",
		"\temitter.Acceleration = Vector3.new(0, -25, 0)\n",
		"\temitter.Drag = 2\n",
		"\temitter.Parent = burstAnchor\n",
		"\tburstEmitter = emitter\n",
		"\n",
		"\tarena.Parent = parent\n",
		"end\n",
		"\n",
		"local function buildSlimeModel(basePivot: CFrame): (Model, { BasePart })\n",
		"\tlocal model = Instance.new(\"Model\")\n",
		"\tmodel.Name = \"Enemy\"\n",
		"\tlocal parts: { BasePart } = {}\n",
		"\n",
		"\t-- Offsets are relative to the pivot (ground point under the slime).\n",
		"\t-- The pivot faces the camera, so the slime's front is local -Z.\n",
		"\tlocal function addPart(spec: PartSpec)\n",
		"\t\ttable.insert(parts, newPart(spec, model))\n",
		"\tend\n",
		"\n",
		"\taddPart({\n",
		"\t\tname = \"Puddle\",\n",
		"\t\tshape = Enum.PartType.Cylinder,\n",
		"\t\tsize = Vector3.new(0.35, 7.2, 7.2),\n",
		"\t\tcframe = basePivot * CFrame.new(0, 0.175, 0) * UPRIGHT,\n",
		"\t\tcolor = SLIME_BASE_COLOR,\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\ttransparency = 0.15,\n",
		"\t})\n",
		"\taddPart({\n",
		"\t\tname = \"Body\",\n",
		"\t\tshape = Enum.PartType.Ball,\n",
		"\t\tsize = Vector3.new(6, 6, 6),\n",
		"\t\tcframe = basePivot * CFrame.new(0, 2.2, 0),\n",
		"\t\tcolor = SLIME_BODY_COLOR,\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\ttransparency = 0.08,\n",
		"\t\tcastShadow = true,\n",
		"\t})\n",
		"\tfor _, side in { -1, 1 } do\n",
		"\t\taddPart({\n",
		"\t\t\tname = \"Eye\",\n",
		"\t\t\tshape = Enum.PartType.Ball,\n",
		"\t\t\tsize = Vector3.new(1, 1, 1),\n",
		"\t\t\tcframe = basePivot * CFrame.new(side * 1.0, 3.0, -2.55),\n",
		"\t\t\tcolor = SLIME_EYE_COLOR,\n",
		"\t\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\t})\n",
		"\t\taddPart({\n",
		"\t\t\tname = \"EyeShine\",\n",
		"\t\t\tshape = Enum.PartType.Ball,\n",
		"\t\t\tsize = Vector3.new(0.32, 0.32, 0.32),\n",
		"\t\t\tcframe = basePivot * CFrame.new(side * 1.0 + 0.15, 3.18, -2.98),\n",
		"\t\t\tcolor = WHITE,\n",
		"\t\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t\t})\n",
		"\tend\n",
		"\taddPart({\n",
		"\t\tname = \"Mouth\",\n",
		"\t\tsize = Vector3.new(0.8, 0.16, 0.2),\n",
		"\t\tcframe = basePivot * CFrame.new(0, 2.1, -2.95),\n",
		"\t\tcolor = SLIME_MOUTH_COLOR,\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t})\n",
		"\taddPart({\n",
		"\t\tname = \"Stem\",\n",
		"\t\tsize = Vector3.new(0.25, 0.7, 0.25),\n",
		"\t\tcframe = basePivot * CFrame.new(0, 5.45, 0),\n",
		"\t\tcolor = Color3.fromRGB(110, 78, 45),\n",
		"\t\tmaterial = Enum.Material.Wood,\n",
		"\t})\n",
		"\taddPart({\n",
		"\t\tname = \"Leaf\",\n",
		"\t\tsize = Vector3.new(1.5, 0.12, 0.7),\n",
		"\t\tcframe = basePivot * CFrame.new(0.6, 5.85, 0) * CFrame.Angles(0, 0, math.rad(20)),\n",
		"\t\tcolor = Color3.fromRGB(60, 150, 60),\n",
		"\t\tmaterial = Enum.Material.SmoothPlastic,\n",
		"\t})\n",
		"\n",
		"\t-- Scaling and moving the model both happen around this ground point.\n",
		"\tmodel.WorldPivot = basePivot\n",
		"\treturn model, parts\n",
		"end\n",
		"\n",
		"local function cancelTween(tween: Tween?)\n",
		"\tif tween then\n",
		"\t\ttween:Cancel()\n",
		"\tend\n",
		"end\n",
		"\n",
		"local function cancelAllTweens(visual: EnemyVisual)\n",
		"\tcancelTween(visual.idleTween)\n",
		"\tcancelTween(visual.pulseTween)\n",
		"\tcancelTween(visual.flashTween)\n",
		"\tcancelTween(visual.spawnTween)\n",
		"\tvisual.idleTween = nil\n",
		"\tvisual.pulseTween = nil\n",
		"\tvisual.flashTween = nil\n",
		"\tvisual.spawnTween = nil\n",
		"end\n",
		"\n",
		"local function applyScale(visual: EnemyVisual)\n",
		"\tlocal scale = math.max(visual.baseScale.Value * visual.pulseScale.Value, MIN_SCALE)\n",
		"\tvisual.model:ScaleTo(scale)\n",
		"end\n",
		"\n",
		"local function applyBob(visual: EnemyVisual)\n",
		"\tvisual.model:PivotTo(visual.basePivot + Vector3.new(0, visual.bobOffset.Value, 0))\n",
		"end\n",
		"\n",
		"local function newNumberValue(name: string, value: number, parent: Instance): NumberValue\n",
		"\tlocal numberValue = Instance.new(\"NumberValue\")\n",
		"\tnumberValue.Name = name\n",
		"\tnumberValue.Value = value\n",
		"\tnumberValue.Parent = parent\n",
		"\treturn numberValue\n",
		"end\n",
		"\n",
		"local function createEnemyVisual(parent: Instance, enemyId: number): EnemyVisual\n",
		"\tlocal lookTarget = Vector3.new(CAMERA_POSITION.X, ENEMY_POSITION.Y, CAMERA_POSITION.Z)\n",
		"\tlocal basePivot = CFrame.lookAt(ENEMY_POSITION, lookTarget)\n",
		"\tlocal model, parts = buildSlimeModel(basePivot)\n",
		"\n",
		"\tlocal highlight = Instance.new(\"Highlight\")\n",
		"\thighlight.FillColor = WHITE\n",
		"\thighlight.FillTransparency = 1\n",
		"\thighlight.OutlineTransparency = 1\n",
		"\thighlight.DepthMode = Enum.HighlightDepthMode.Occluded\n",
		"\thighlight.Parent = model\n",
		"\n",
		"\tlocal visual: EnemyVisual = {\n",
		"\t\tid = enemyId,\n",
		"\t\tmodel = model,\n",
		"\t\tparts = parts,\n",
		"\t\thighlight = highlight,\n",
		"\t\tbasePivot = basePivot,\n",
		"\t\tbaseScale = newNumberValue(\"BaseScale\", 1, model),\n",
		"\t\tpulseScale = newNumberValue(\"PulseScale\", 1, model),\n",
		"\t\tbobOffset = newNumberValue(\"BobOffset\", 0, model),\n",
		"\t\tidleTween = nil,\n",
		"\t\tpulseTween = nil,\n",
		"\t\tflashTween = nil,\n",
		"\t\tspawnTween = nil,\n",
		"\t}\n",
		"\n",
		"\t-- These connections are cleaned up automatically when the model is destroyed.\n",
		"\tvisual.baseScale.Changed:Connect(function()\n",
		"\t\tapplyScale(visual)\n",
		"\tend)\n",
		"\tvisual.pulseScale.Changed:Connect(function()\n",
		"\t\tapplyScale(visual)\n",
		"\tend)\n",
		"\tvisual.bobOffset.Changed:Connect(function()\n",
		"\t\tapplyBob(visual)\n",
		"\tend)\n",
		"\n",
		"\tmodel.Parent = parent\n",
		"\treturn visual\n",
		"end\n",
		"\n",
		"local function retireEnemy(visual: EnemyVisual, animate: boolean)\n",
		"\tcancelAllTweens(visual)\n",
		"\n",
		"\tif not animate then\n",
		"\t\tvisual.model:Destroy()\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal emitter = burstEmitter\n",
		"\tif emitter then\n",
		"\t\temitter:Emit(DEFEAT_PARTICLE_COUNT)\n",
		"\tend\n",
		"\n",
		"\tvisual.highlight.FillTransparency = HIT_FLASH_TRANSPARENCY\n",
		"\tTweenService:Create(visual.highlight, DEFEAT_INFO, { FillTransparency = 1 }):Play()\n",
		"\tfor _, part in visual.parts do\n",
		"\t\tTweenService:Create(part, DEFEAT_INFO, { Transparency = 1 }):Play()\n",
		"\tend\n",
		"\n",
		"\tlocal shrinkTween = TweenService:Create(visual.baseScale, DEFEAT_INFO, { Value = MIN_SCALE })\n",
		"\tshrinkTween.Completed:Once(function()\n",
		"\t\tvisual.model:Destroy()\n",
		"\tend)\n",
		"\tshrinkTween:Play()\n",
		"end\n",
		"\n",
		"local function applyCamera(camera: Camera)\n",
		"\tcamera.CameraType = Enum.CameraType.Scriptable\n",
		"\tcamera.FieldOfView = CAMERA_FIELD_OF_VIEW\n",
		"\tcamera.CFrame = CFrame.lookAt(CAMERA_POSITION, CAMERA_FOCUS)\n",
		"\t-- Scriptable cameras never update Focus on their own. The camera is stationary,\n",
		"\t-- so setting it here (on lock, camera swap or CameraType reset) is enough.\n",
		"\tcamera.Focus = CFrame.new(CAMERA_FOCUS)\n",
		"end\n",
		"\n",
		"local function lockCamera(camera: Camera)\n",
		"\tapplyCamera(camera)\n",
		"\n",
		"\t-- Safety net: if anything switches the camera away from Scriptable, put it back.\n",
		"\ttable.insert(\n",
		"\t\tcameraConnections,\n",
		"\t\tcamera:GetPropertyChangedSignal(\"CameraType\"):Connect(function()\n",
		"\t\t\tif camera.CameraType ~= Enum.CameraType.Scriptable then\n",
		"\t\t\t\tapplyCamera(camera)\n",
		"\t\t\tend\n",
		"\t\tend)\n",
		"\t)\n",
		"end\n",
		"\n",
		"local function bindCamera()\n",
		"\tfor _, connection in cameraConnections do\n",
		"\t\tconnection:Disconnect()\n",
		"\tend\n",
		"\ttable.clear(cameraConnections)\n",
		"\n",
		"\tlocal camera = Workspace.CurrentCamera\n",
		"\tif camera then\n",
		"\t\tlockCamera(camera)\n",
		"\tend\n",
		"\t-- If there is no camera yet, the CurrentCamera changed signal calls this again.\n",
		"end\n",
		"\n",
		"-- Builds the arena and locks the camera. Safe to call more than once.\n",
		"function ArenaView.Mount()\n",
		"\tif mounted then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tmounted = true\n",
		"\n",
		"\tlocal leftover = Workspace:FindFirstChild(STAGE_FOLDER_NAME)\n",
		"\tif leftover then\n",
		"\t\tleftover:Destroy()\n",
		"\tend\n",
		"\n",
		"\tlocal folder = Instance.new(\"Folder\")\n",
		"\tfolder.Name = STAGE_FOLDER_NAME\n",
		"\tbuildArena(folder)\n",
		"\tfolder.Parent = Workspace\n",
		"\tstageFolder = folder\n",
		"\n",
		"\tbindCamera()\n",
		"\tWorkspace:GetPropertyChangedSignal(\"CurrentCamera\"):Connect(bindCamera)\n",
		"end\n",
		"\n",
		"-- Makes sure the enemy with this id is on screen. Does nothing if it already is.\n",
		"-- animate = true plays the defeat burst on the old enemy and a pop-in on the new one.\n",
		"function ArenaView.ShowEnemy(enemyId: number, animate: boolean)\n",
		"\tlocal folder = stageFolder\n",
		"\tif not folder then\n",
		"\t\twarn(\"[ArenaView] ShowEnemy called before Mount\")\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal previous = currentEnemy\n",
		"\tif previous and previous.id == enemyId then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tif previous then\n",
		"\t\tcurrentEnemy = nil\n",
		"\t\tretireEnemy(previous, animate)\n",
		"\tend\n",
		"\n",
		"\tlocal visual = createEnemyVisual(folder, enemyId)\n",
		"\tcurrentEnemy = visual\n",
		"\n",
		"\tif animate then\n",
		"\t\tvisual.baseScale.Value = MIN_SCALE\n",
		"\t\tlocal spawnTween = TweenService:Create(visual.baseScale, SPAWN_INFO, { Value = 1 })\n",
		"\t\tvisual.spawnTween = spawnTween\n",
		"\t\tspawnTween:Play()\n",
		"\tend\n",
		"\n",
		"\tlocal idleTween = TweenService:Create(visual.bobOffset, IDLE_BOB_INFO, { Value = IDLE_BOB_HEIGHT })\n",
		"\tvisual.idleTween = idleTween\n",
		"\tidleTween:Play()\n",
		"end\n",
		"\n",
		"-- Squash + white flash on a server-confirmed hit.\n",
		"function ArenaView.PlayHit()\n",
		"\tlocal visual = currentEnemy\n",
		"\tif not visual then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tcancelTween(visual.pulseTween)\n",
		"\tvisual.pulseScale.Value = HIT_SQUASH_SCALE\n",
		"\tlocal pulseTween = TweenService:Create(visual.pulseScale, HIT_PULSE_INFO, { Value = 1 })\n",
		"\tvisual.pulseTween = pulseTween\n",
		"\tpulseTween:Play()\n",
		"\n",
		"\tcancelTween(visual.flashTween)\n",
		"\tvisual.highlight.FillTransparency = HIT_FLASH_TRANSPARENCY\n",
		"\tlocal flashTween = TweenService:Create(visual.highlight, HIT_FLASH_INFO, { FillTransparency = 1 })\n",
		"\tvisual.flashTween = flashTween\n",
		"\tflashTween:Play()\n",
		"end\n",
		"\n",
		"return ArenaView\n",
	},
}
FILES[33] = {
	path = "StarterPlayer/StarterPlayerScripts/CombatClient/CombatHud",
	className = "ModuleScript",
	bytes = 13480,
	lines = 424,
	adler32 = 4051264347,
	sha256 = "3da101a67005c8957e993f370eb8c15bf20dca37c2b5be220eace41341ce3314",
	text = {
		"--!strict\n",
		"--[[\n",
		"\tCombatHud\n",
		"\tLocation: StarterPlayer > StarterPlayerScripts > CombatClient > CombatHud (ModuleScript)\n",
		"\n",
		"\tBuilds and updates the placeholder combat interface:\n",
		"\t  Top:    Stage, Gold\n",
		"\t  Center: Enemy name, HP bar, \"HP / Max HP\", and the large tap area\n",
		"\t  Bottom: Tap Damage\n",
		"\n",
		"\tIt only renders what it is given; it never decides combat outcomes.\n",
		"\tSizes use Scale + constraints so the same layout works on phones and desktops.\n",
		"\tMilestone 2: numbers arrive as BigNums and are formatted with BigNum.format;\n",
		"\tGold is set separately from combat updates (it comes from CurrencyUpdate).\n",
		"]]\n",
		"\n",
		"local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n",
		"local TweenService = game:GetService(\"TweenService\")\n",
		"\n",
		"local BigNum = require(ReplicatedStorage:WaitForChild(\"Shared\"):WaitForChild(\"BigNum\"))\n",
		"\n",
		"type BigNum = BigNum.BigNum\n",
		"\n",
		"-- Decoded combat state, built by CombatClient from a CombatSnapshot.\n",
		"export type CombatView = {\n",
		"\tstage: number,\n",
		"\ttapDamage: BigNum,\n",
		"\tenemyId: number,\n",
		"\tenemyName: string,\n",
		"\tenemyHp: BigNum,\n",
		"\tenemyMaxHp: BigNum,\n",
		"}\n",
		"\n",
		"type HudElements = {\n",
		"\tscreenGui: ScreenGui,\n",
		"\ttapArea: Frame,\n",
		"\tstageLabel: TextLabel,\n",
		"\tgoldPill: Frame,\n",
		"\tgoldLabel: TextLabel,\n",
		"\tgoldScale: UIScale,\n",
		"\tenemyNameLabel: TextLabel,\n",
		"\thealthFill: Frame,\n",
		"\thealthText: TextLabel,\n",
		"\ttapDamageLabel: TextLabel,\n",
		"}\n",
		"\n",
		"local SCREEN_GUI_NAME = \"CombatHud\"\n",
		"local FONT = Enum.Font.FredokaOne\n",
		"\n",
		"local TEXT_COLOR = Color3.fromRGB(255, 255, 255)\n",
		"local STROKE_COLOR = Color3.fromRGB(20, 20, 28)\n",
		"local PANEL_COLOR = Color3.fromRGB(24, 26, 36)\n",
		"local GOLD_COLOR = Color3.fromRGB(255, 214, 90)\n",
		"local DAMAGE_COLOR = Color3.fromRGB(255, 245, 235)\n",
		"local HEALTH_BACK_COLOR = Color3.fromRGB(45, 18, 22)\n",
		"local HEALTH_FILL_COLOR = Color3.fromRGB(226, 64, 64)\n",
		"\n",
		"local HEALTH_TWEEN_INFO = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n",
		"local RIPPLE_INFO = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n",
		"local POPUP_INFO = TweenInfo.new(0.6, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)\n",
		"local GOLD_POP_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out)\n",
		"\n",
		"local RIPPLE_SIZE = 0.14 -- fraction of the tap area (kept circular by an aspect constraint)\n",
		"\n",
		"local CombatHud = {}\n",
		"\n",
		"local elements: HudElements? = nil\n",
		"local healthTween: Tween? = nil\n",
		"local goldPopTween: Tween? = nil\n",
		"local random = Random.new()\n",
		"\n",
		"local function addCorner(guiObject: GuiObject, radius: UDim)\n",
		"\tlocal corner = Instance.new(\"UICorner\")\n",
		"\tcorner.CornerRadius = radius\n",
		"\tcorner.Parent = guiObject\n",
		"end\n",
		"\n",
		"local function addBorderStroke(guiObject: GuiObject, thickness: number, transparency: number): UIStroke\n",
		"\tlocal stroke = Instance.new(\"UIStroke\")\n",
		"\tstroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n",
		"\tstroke.Color = STROKE_COLOR\n",
		"\tstroke.Thickness = thickness\n",
		"\tstroke.Transparency = transparency\n",
		"\tstroke.Parent = guiObject\n",
		"\treturn stroke\n",
		"end\n",
		"\n",
		"local function newFrame(name: string, parent: Instance): Frame\n",
		"\tlocal frame = Instance.new(\"Frame\")\n",
		"\tframe.Name = name\n",
		"\tframe.BackgroundTransparency = 1\n",
		"\tframe.BorderSizePixel = 0\n",
		"\tframe.Active = false -- never sink input, so taps pass through to the combat area\n",
		"\tframe.Parent = parent\n",
		"\treturn frame\n",
		"end\n",
		"\n",
		"local function newLabel(name: string, parent: Instance, maxTextSize: number): (TextLabel, UIStroke)\n",
		"\tlocal label = Instance.new(\"TextLabel\")\n",
		"\tlabel.Name = name\n",
		"\tlabel.BackgroundTransparency = 1\n",
		"\tlabel.Size = UDim2.fromScale(1, 1)\n",
		"\tlabel.Font = FONT\n",
		"\tlabel.Text = \"\"\n",
		"\tlabel.TextColor3 = TEXT_COLOR\n",
		"\tlabel.TextScaled = true\n",
		"\tlabel.Active = false\n",
		"\n",
		"\tlocal sizeConstraint = Instance.new(\"UITextSizeConstraint\")\n",
		"\tsizeConstraint.MinTextSize = 10\n",
		"\tsizeConstraint.MaxTextSize = maxTextSize\n",
		"\tsizeConstraint.Parent = label\n",
		"\n",
		"\tlocal stroke = Instance.new(\"UIStroke\") -- Contextual mode outlines the text\n",
		"\tstroke.Color = STROKE_COLOR\n",
		"\tstroke.Thickness = 1.5\n",
		"\tstroke.Parent = label\n",
		"\n",
		"\tlabel.Parent = parent\n",
		"\treturn label, stroke\n",
		"end\n",
		"\n",
		"-- Rounded dark \"pill\" with a label inside. Returns the pill, its label and a UIScale for pop effects.\n",
		"local function newPill(name: string, parent: Instance, size: UDim2, maxSize: Vector2): (Frame, TextLabel, UIScale)\n",
		"\tlocal pill = newFrame(name, parent)\n",
		"\tpill.Size = size\n",
		"\tpill.BackgroundColor3 = PANEL_COLOR\n",
		"\tpill.BackgroundTransparency = 0.25\n",
		"\taddCorner(pill, UDim.new(0.3, 0))\n",
		"\taddBorderStroke(pill, 2, 0.3)\n",
		"\n",
		"\tlocal sizeConstraint = Instance.new(\"UISizeConstraint\")\n",
		"\tsizeConstraint.MaxSize = maxSize\n",
		"\tsizeConstraint.Parent = pill\n",
		"\n",
		"\tlocal scale = Instance.new(\"UIScale\")\n",
		"\tscale.Parent = pill\n",
		"\n",
		"\tlocal label = newLabel(\"Label\", pill, 32)\n",
		"\tlabel.AnchorPoint = Vector2.new(0.5, 0.5)\n",
		"\tlabel.Position = UDim2.fromScale(0.5, 0.5)\n",
		"\tlabel.Size = UDim2.fromScale(0.86, 0.72)\n",
		"\n",
		"\treturn pill, label, scale\n",
		"end\n",
		"\n",
		"local function getElements(): HudElements?\n",
		"\tlocal ui = elements\n",
		"\tif not ui then\n",
		"\t\twarn(\"[CombatHud] Used before Mount\")\n",
		"\tend\n",
		"\treturn ui\n",
		"end\n",
		"\n",
		"-- Floats a label from its current Position by `offset`, fading it out, then destroys it.\n",
		"local function floatAndFade(label: TextLabel, stroke: UIStroke, offset: UDim2)\n",
		"\tTweenService:Create(label, POPUP_INFO, {\n",
		"\t\tPosition = label.Position + offset,\n",
		"\t\tTextTransparency = 1,\n",
		"\t}):Play()\n",
		"\tlocal strokeTween = TweenService:Create(stroke, POPUP_INFO, { Transparency = 1 })\n",
		"\tstrokeTween.Completed:Once(function()\n",
		"\t\tlabel:Destroy()\n",
		"\tend)\n",
		"\tstrokeTween:Play()\n",
		"end\n",
		"\n",
		"function CombatHud.Mount(playerGui: PlayerGui)\n",
		"\tif elements then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal leftover = playerGui:FindFirstChild(SCREEN_GUI_NAME)\n",
		"\tif leftover then\n",
		"\t\tleftover:Destroy()\n",
		"\tend\n",
		"\n",
		"\tlocal screenGui = Instance.new(\"ScreenGui\")\n",
		"\tscreenGui.Name = SCREEN_GUI_NAME\n",
		"\tscreenGui.ResetOnSpawn = false\n",
		"\tscreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n",
		"\tscreenGui.ScreenInsets = Enum.ScreenInsets.CoreUISafeInsets -- stays clear of Roblox buttons and notches\n",
		"\tscreenGui.DisplayOrder = 1\n",
		"\n",
		"\t-- Large combat tap area. It is a plain, non-Active Frame: it marks WHERE taps\n",
		"\t-- count. Real buttons placed above it (Active = true) mark input as processed,\n",
		"\t-- which CombatClient ignores, so UI controls never trigger attacks.\n",
		"\tlocal tapArea = newFrame(\"TapArea\", screenGui)\n",
		"\ttapArea.Position = UDim2.fromScale(0, 0.12)\n",
		"\ttapArea.Size = UDim2.fromScale(1, 0.74)\n",
		"\ttapArea.ZIndex = 1\n",
		"\n",
		"\tlocal tapHint = newLabel(\"TapHint\", tapArea, 22)\n",
		"\ttapHint.AnchorPoint = Vector2.new(0.5, 1)\n",
		"\ttapHint.Position = UDim2.fromScale(0.5, 0.99)\n",
		"\ttapHint.Size = UDim2.fromScale(0.5, 0.06)\n",
		"\ttapHint.Text = \"Tap or click to attack\"\n",
		"\ttapHint.TextTransparency = 0.4\n",
		"\n",
		"\t-- Top: Stage and Gold\n",
		"\tlocal topBar = newFrame(\"TopBar\", screenGui)\n",
		"\ttopBar.AnchorPoint = Vector2.new(0.5, 0)\n",
		"\ttopBar.Position = UDim2.fromScale(0.5, 0.015)\n",
		"\ttopBar.Size = UDim2.fromScale(0.92, 0.085)\n",
		"\ttopBar.ZIndex = 2\n",
		"\n",
		"\tlocal topLayout = Instance.new(\"UIListLayout\")\n",
		"\ttopLayout.FillDirection = Enum.FillDirection.Horizontal\n",
		"\ttopLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center\n",
		"\ttopLayout.VerticalAlignment = Enum.VerticalAlignment.Center\n",
		"\ttopLayout.SortOrder = Enum.SortOrder.LayoutOrder\n",
		"\ttopLayout.Padding = UDim.new(0.03, 0)\n",
		"\ttopLayout.Parent = topBar\n",
		"\n",
		"\tlocal stagePill, stageLabel = newPill(\"StagePill\", topBar, UDim2.fromScale(0.36, 1), Vector2.new(280, 64))\n",
		"\tstagePill.LayoutOrder = 1\n",
		"\n",
		"\tlocal goldPill, goldLabel, goldScale = newPill(\"GoldPill\", topBar, UDim2.fromScale(0.36, 1), Vector2.new(280, 64))\n",
		"\tgoldPill.LayoutOrder = 2\n",
		"\tgoldLabel.TextColor3 = GOLD_COLOR\n",
		"\n",
		"\t-- Above the enemy: name, HP bar, HP text\n",
		"\tlocal enemyPanel = newFrame(\"EnemyPanel\", screenGui)\n",
		"\tenemyPanel.AnchorPoint = Vector2.new(0.5, 0)\n",
		"\tenemyPanel.Position = UDim2.fromScale(0.5, 0.13)\n",
		"\tenemyPanel.Size = UDim2.fromScale(0.55, 0.12)\n",
		"\tenemyPanel.ZIndex = 2\n",
		"\n",
		"\tlocal panelConstraint = Instance.new(\"UISizeConstraint\")\n",
		"\tpanelConstraint.MaxSize = Vector2.new(520, 110)\n",
		"\tpanelConstraint.Parent = enemyPanel\n",
		"\n",
		"\tlocal enemyNameLabel = newLabel(\"EnemyName\", enemyPanel, 34)\n",
		"\tenemyNameLabel.Size = UDim2.fromScale(1, 0.45)\n",
		"\n",
		"\tlocal healthBar = newFrame(\"HealthBar\", enemyPanel)\n",
		"\thealthBar.Position = UDim2.fromScale(0, 0.52)\n",
		"\thealthBar.Size = UDim2.fromScale(1, 0.48)\n",
		"\thealthBar.BackgroundColor3 = HEALTH_BACK_COLOR\n",
		"\thealthBar.BackgroundTransparency = 0\n",
		"\taddCorner(healthBar, UDim.new(0.3, 0))\n",
		"\taddBorderStroke(healthBar, 2, 0)\n",
		"\n",
		"\tlocal healthFill = newFrame(\"Fill\", healthBar)\n",
		"\thealthFill.Size = UDim2.fromScale(1, 1)\n",
		"\thealthFill.BackgroundColor3 = HEALTH_FILL_COLOR\n",
		"\thealthFill.BackgroundTransparency = 0\n",
		"\thealthFill.ZIndex = 1\n",
		"\taddCorner(healthFill, UDim.new(0.3, 0))\n",
		"\n",
		"\tlocal healthText = newLabel(\"HealthText\", healthBar, 26)\n",
		"\thealthText.ZIndex = 2\n",
		"\n",
		"\t-- Bottom: Tap Damage\n",
		"\tlocal tapDamagePill, tapDamageLabel = newPill(\"TapDamagePill\", screenGui, UDim2.fromScale(0.42, 0.085), Vector2.new(320, 64))\n",
		"\ttapDamagePill.AnchorPoint = Vector2.new(0.5, 1)\n",
		"\ttapDamagePill.Position = UDim2.fromScale(0.5, 0.985)\n",
		"\ttapDamagePill.ZIndex = 2\n",
		"\n",
		"\t-- Placeholder text until the first server sync arrives\n",
		"\tstageLabel.Text = \"Stage -\"\n",
		"\tgoldLabel.Text = \"Gold: -\"\n",
		"\tenemyNameLabel.Text = \"Connecting...\"\n",
		"\thealthText.Text = \"- / -\"\n",
		"\ttapDamageLabel.Text = \"Tap Damage: -\"\n",
		"\n",
		"\tscreenGui.Parent = playerGui\n",
		"\n",
		"\telements = {\n",
		"\t\tscreenGui = screenGui,\n",
		"\t\ttapArea = tapArea,\n",
		"\t\tstageLabel = stageLabel,\n",
		"\t\tgoldPill = goldPill,\n",
		"\t\tgoldLabel = goldLabel,\n",
		"\t\tgoldScale = goldScale,\n",
		"\t\tenemyNameLabel = enemyNameLabel,\n",
		"\t\thealthFill = healthFill,\n",
		"\t\thealthText = healthText,\n",
		"\t\ttapDamageLabel = tapDamageLabel,\n",
		"\t}\n",
		"end\n",
		"\n",
		"-- Shows the authoritative combat state. instantHealthBar skips the bar tween (used when a new enemy appears).\n",
		"function CombatHud.Render(view: CombatView, instantHealthBar: boolean)\n",
		"\tlocal ui = getElements()\n",
		"\tif not ui then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tui.stageLabel.Text = `Stage {view.stage}`\n",
		"\tui.enemyNameLabel.Text = view.enemyName\n",
		"\tui.healthText.Text = `{BigNum.format(view.enemyHp)} / {BigNum.format(view.enemyMaxHp)}`\n",
		"\tui.tapDamageLabel.Text = `Tap Damage: {BigNum.format(view.tapDamage)}`\n",
		"\n",
		"\tlocal ratio = 0\n",
		"\tif not BigNum.isZero(view.enemyMaxHp) then\n",
		"\t\tratio = math.clamp(BigNum.ratio(view.enemyHp, view.enemyMaxHp), 0, 1)\n",
		"\tend\n",
		"\tlocal targetSize = UDim2.fromScale(ratio, 1)\n",
		"\n",
		"\tlocal previousTween = healthTween\n",
		"\tif previousTween then\n",
		"\t\tpreviousTween:Cancel()\n",
		"\t\thealthTween = nil\n",
		"\tend\n",
		"\n",
		"\tif instantHealthBar then\n",
		"\t\tui.healthFill.Size = targetSize\n",
		"\telse\n",
		"\t\tlocal tween = TweenService:Create(ui.healthFill, HEALTH_TWEEN_INFO, { Size = targetSize })\n",
		"\t\thealthTween = tween\n",
		"\t\ttween:Play()\n",
		"\tend\n",
		"end\n",
		"\n",
		"-- Shows the authoritative Gold balance (from CurrencyUpdate).\n",
		"function CombatHud.SetGold(gold: BigNum)\n",
		"\tlocal ui = getElements()\n",
		"\tif not ui then\n",
		"\t\treturn\n",
		"\tend\n",
		"\tui.goldLabel.Text = `Gold: {BigNum.format(gold)}`\n",
		"end\n",
		"\n",
		"-- True if a screen position (InputObject.Position space) is inside the combat tap area.\n",
		"function CombatHud.IsInTapArea(screenPosition: Vector2): boolean\n",
		"\tlocal ui = elements\n",
		"\tif not ui or not ui.screenGui.Enabled then\n",
		"\t\treturn false\n",
		"\tend\n",
		"\tlocal topLeft = ui.tapArea.AbsolutePosition\n",
		"\tlocal bottomRight = topLeft + ui.tapArea.AbsoluteSize\n",
		"\treturn screenPosition.X >= topLeft.X\n",
		"\t\tand screenPosition.X <= bottomRight.X\n",
		"\t\tand screenPosition.Y >= topLeft.Y\n",
		"\t\tand screenPosition.Y <= bottomRight.Y\n",
		"end\n",
		"\n",
		"-- Instant local feedback where the player tapped (shown before the server replies).\n",
		"function CombatHud.PlayTapRipple(screenPosition: Vector2)\n",
		"\tlocal ui = getElements()\n",
		"\tif not ui then\n",
		"\t\treturn\n",
		"\tend\n",
		"\n",
		"\tlocal localPosition = screenPosition - ui.tapArea.AbsolutePosition\n",
		"\n",
		"\tlocal ripple = newFrame(\"TapRipple\", ui.tapArea)\n",
		"\tripple.AnchorPoint = Vector2.new(0.5, 0.5)\n",
		"\tripple.Position = UDim2.fromOffset(localPosition.X, localPosition.Y)\n",
		"\tripple.Size = UDim2.fromScale(0, 0)\n",
		"\tripple.BackgroundColor3 = TEXT_COLOR\n",
		"\tripple.BackgroundTransparency = 0.6\n",
